/* Curiona 1.0 — généré par npm run build. */
(()=>{
'use strict';
const CATEGORIES = [
  {id:'animals',name:'Monde animal',icon:'butterfly',color:'#466956',bg:'#e7eee0',description:'Des ailes, des pattes et mille façons de vivre.',subs:['Insectes','Faune','Biodiversité']},
  {id:'nature',name:'Nature & jardin',icon:'leaf',color:'#62713a',bg:'#edf0dc',description:'Prendre le temps de comprendre ce qui pousse.',subs:['Plantes','Arbres','Jardinage']},
  {id:'math',name:'Maths & logique',icon:'shapes',color:'#9a572f',bg:'#f8e8d8',description:'Le plaisir du déclic et des idées qui s’assemblent.',subs:['Calcul','Logique','Géométrie']},
  {id:'mind',name:'Esprit humain',icon:'mind',color:'#805772',bg:'#f0e5ed',description:'Mémoire, attention et petits mystères du quotidien.',subs:['Mémoire','Cognition','Vie sociale']},
  {id:'science',name:'Sciences & espace',icon:'planet',color:'#446b83',bg:'#e2edf3',description:'Du plus petit atome aux grandes galaxies.',subs:['Corps humain','Physique et chimie','Astronomie']},
  {id:'world',name:'Culture & monde',icon:'globe',color:'#aa523f',bg:'#f7e5de',description:'Voyager à travers les lieux, les arts et le temps.',subs:['Histoire','Géographie','Arts et culture']},
  {id:'tech',name:'Informatique',icon:'chip',color:'#58628a',bg:'#e8e9f3',description:'Comprendre les outils qui relient nos idées.',subs:['Numérique','Programmation','Réseaux']}
];
const DIFFICULTIES = ['','Débutant','Intermédiaire','Avancé','Expert'];
const MODES = [
  {id:'general',name:'Grand mélange',label:'Général',icon:'spark',description:'Un peu de tout, beaucoup de découvertes.'},
  {id:'specific',name:'À la carte',label:'Spécifique',icon:'compass',description:'Un univers ou un sous-thème à explorer.'},
  {id:'custom',name:'Sur mesure',label:'Personnalisé',icon:'sliders',description:'Compose ton mélange de thèmes.'},
  {id:'review',name:'Le bon rappel',label:'Révision',icon:'repeat',description:'Retrouve les notions au bon moment.'},
  {id:'challenge',name:'Cap sur le défi',label:'Défi',icon:'flag',description:'Un objectif de points, 30 secondes par question.'},
  {id:'relax',name:'À ton rythme',label:'Détente',icon:'cup',description:'Sans chrono. Juste le plaisir d’apprendre.'}
];
const BADGES = [
  {id:'first',name:'Premier pas',description:'Terminer une première exploration.',icon:'compass'},
  {id:'streak',name:'Sur ta lancée',description:'Réussir 5 réponses de suite.',icon:'spark'},
  {id:'curious',name:'Esprit curieux',description:'Découvrir les 7 univers.',icon:'globe'},
  {id:'fifty',name:'Belle récolte',description:'Trouver 50 bonnes réponses.',icon:'leaf'},
  {id:'review',name:'Le déclic',description:'Réussir 5 rappels en mode Révision.',icon:'repeat'},
  {id:'challenge',name:'Cap atteint',description:'Atteindre l’objectif d’un défi terminé.',icon:'flag'},
  {id:'hundred',name:'Cent découvertes',description:'Rencontrer 100 questions différentes.',icon:'planet'},
  {id:'expert',name:'En profondeur',description:'Réussir 10 questions de niveau expert.',icon:'shapes'}
];
function freshState() {
  return {version:1,xp:0,points:0,total:0,correct:0,bestStreak:0,reviewCorrect:0,expertCorrect:0,questions:{},topics:{},history:[],badges:[],sound:false,active:null};
}
function shuffle(items,rng=Math.random) {
  const result=[...items]; for(let i=result.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[result[i],result[j]]=[result[j],result[i]];} return result;
}
function shuffledOptions(question,rng=Math.random){return shuffle(question.options.map((text,id)=>({text,id})),rng);}
function isCorrect(question,optionId){return optionId===question.correct;}
function filterQuestions(bank,config,state,now=Date.now()) {
  return bank.filter(q=>{
    if(config.difficulty!=='adaptive' && q.difficulty!==Number(config.difficulty)) return false;
    if(['specific','custom'].includes(config.mode) && !config.themes.some(t=>t===q.category || t===`${q.category}::${q.subtheme}`)) return false;
    if(config.mode==='review') {const s=state.questions[q.id]; if(!s || s.nextDue>now) return false;}
    return true;
  });
}
function pickQuestion(bank,state,config,used=[],rng=Math.random,now=Date.now()) {
  let eligible=filterQuestions(bank,config,state,now).filter(q=>!used.includes(q.id));
  if(!eligible.length) return null;
  // Écarter la dernière rencontre entre deux parties si un autre choix existe.
  const latest=Object.entries(state.questions).reduce((best,[id,s])=>s.lastSeen>(best.time||0)?{id,time:s.lastSeen}:best,{});
  if(eligible.length>1&&now-latest.time<600000)eligible=eligible.filter(q=>q.id!==latest.id);
  const counts={}; used.forEach(id=>{const c=bank.find(q=>q.id===id)?.category;if(c)counts[c]=(counts[c]||0)+1;});
  const weights=eligible.map(q=>{
    const s=state.questions[q.id],level=state.topics[q.category]?.level||1;
    let w=1/Math.pow(1+(s?.seen||0),1.4);
    if(config.difficulty==='adaptive') w*=Math.pow(0.16,Math.abs(q.difficulty-level));
    if(s && s.nextDue<=now) w*=s.box===0?4:2;
    if(s && now-s.lastSeen<600000) w*=0.03;
    w/=1+(counts[q.category]||0)*1.4;
    return w;
  });
  let n=rng()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<eligible.length;i++){n-=weights[i];if(n<=0)return eligible[i];}return eligible.at(-1);
}
function reward(difficulty,correct,streak){return {points:correct?100+25*(difficulty-1)+Math.min(Math.max(0,streak-1),5)*10:0,xp:correct?25+difficulty*5:8};}
function recordAnswer(state,q,correct,streak,mode,now=Date.now()) {
  const r=reward(q.difficulty,correct,streak); state.xp+=r.xp;state.points+=r.points;state.total++;if(correct)state.correct++;
  state.bestStreak=Math.max(state.bestStreak,streak);
  const s=state.questions[q.id]||{seen:0,correct:0,box:0,lastSeen:0,nextDue:0};
  s.seen++;if(correct)s.correct++;s.box=correct?Math.min(5,s.box+1):0;s.lastSeen=now;
  s.nextDue=now+(correct?[0,1,3,7,14,30][s.box]*86400000:600000);state.questions[q.id]=s;
  const t=state.topics[q.category]||{level:1,momentum:0,total:0,correct:0};t.total++;if(correct)t.correct++;
  t.momentum=correct?Math.max(0,t.momentum)+1:Math.min(0,t.momentum)-1;
  if(t.momentum>=3){t.level=Math.min(4,t.level+1);t.momentum=0;}if(t.momentum<=-2){t.level=Math.max(1,t.level-1);t.momentum=0;}state.topics[q.category]=t;
  if(mode==='review'&&correct)state.reviewCorrect++;if(q.difficulty===4&&correct)state.expertCorrect++;
  return r;
}
function earnedBadges(state) {
  const conditions={first:state.history.some(h=>!h.abandoned),streak:state.bestStreak>=5,curious:CATEGORIES.every(c=>state.topics[c.id]?.total>0),fifty:state.correct>=50,review:state.reviewCorrect>=5,challenge:state.history.some(h=>h.mode==='challenge'&&!h.abandoned&&h.score>=h.target),hundred:Object.keys(state.questions).length>=100,expert:state.expertCorrect>=10};
  return BADGES.filter(b=>conditions[b.id]&&!state.badges.includes(b.id)).map(b=>b.id);
}
function playerLevel(xp){return 1+Math.floor(Math.sqrt(xp/100));}
function validateBank(bank) {
  const ids=new Set(),texts=new Set();for(const q of bank){
    if(ids.has(q.id))throw Error('Identifiant dupliqué : '+q.id);ids.add(q.id);
    const normalized=q.question.toLocaleLowerCase('fr').replace(/[\s’'?.!,;:]/g,'');if(texts.has(normalized))throw Error('Question dupliquée : '+q.id);texts.add(normalized);
    if(!CATEGORIES.some(c=>c.id===q.category&&c.subs.includes(q.subtheme)))throw Error('Thème inconnu : '+q.id);
    if(!Number.isInteger(q.difficulty)||q.difficulty<1||q.difficulty>4)throw Error('Difficulté invalide : '+q.id);
    if(![2,4].includes(q.options.length)||new Set(q.options).size!==q.options.length||!q.options.every(o=>typeof o==='string'&&o.trim()))throw Error('Propositions invalides : '+q.id);
    if(!Number.isInteger(q.correct)||q.correct<0||q.correct>=q.options.length||typeof q.explanation!=='string'||q.explanation.length<70)throw Error('Correction invalide : '+q.id);
    if(q.source&&!/^https:\/\//.test(q.source))throw Error('Source invalide : '+q.id);
  }return true;
}
function parseSave(input,bank) {
  if(!input||input.app!=='curiona'||input.version!==1||!input.state||typeof input.state!=='object')throw Error('Ce fichier n’est pas une sauvegarde Curiona compatible.');
  const raw=input.state,result=freshState();
  const number=(n,max=1e9)=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;
  for(const key of ['xp','points','total','correct','bestStreak','reviewCorrect','expertCorrect']){if(!number(raw[key]))throw Error('La sauvegarde contient des statistiques invalides.');result[key]=Math.floor(raw[key]);}
  if(result.correct>result.total)throw Error('Statistiques incohérentes.');
  const ids=new Set(bank.map(q=>q.id));if(!raw.questions||typeof raw.questions!=='object'||Array.isArray(raw.questions))throw Error('Questions sauvegardées invalides.');
  for(const [id,s] of Object.entries(raw.questions)){
    if(!ids.has(id))continue;if(!s||!['seen','correct','box','lastSeen','nextDue'].every(k=>number(s[k],k.includes('Seen')||k==='nextDue'?1e14:1e9))||s.correct>s.seen||s.box>5)throw Error('Progression invalide.');
    result.questions[id]={seen:Math.floor(s.seen),correct:Math.floor(s.correct),box:Math.floor(s.box),lastSeen:s.lastSeen,nextDue:s.nextDue};
  }
  for(const c of CATEGORIES){const t=raw.topics?.[c.id];if(!t)continue;if(!number(t.level,4)||t.level<1||!number(t.total)||!number(t.correct)||t.correct>t.total||!Number.isInteger(t.momentum)||Math.abs(t.momentum)>3)throw Error('Niveau de thème invalide.');result.topics[c.id]={level:Math.floor(t.level),total:Math.floor(t.total),correct:Math.floor(t.correct),momentum:t.momentum};}
  if(!Array.isArray(raw.history)||raw.history.length>100)throw Error('Historique invalide.');
  result.history=raw.history.map(h=>{
    if(!h||!MODES.some(m=>m.id===h.mode)||!['score','correct','total','xp','date','target'].every(k=>number(h[k],k==='date'?1e14:1e9))||h.correct>h.total||!Array.isArray(h.answers)||h.answers.length>50)throw Error('Partie invalide.');
    const answers=h.answers.map(a=>{if(!a||!ids.has(a.id)||typeof a.correct!=='boolean')throw Error('Réponse invalide.');return{id:a.id,correct:a.correct};});
    if(answers.length!==h.total||answers.filter(a=>a.correct).length!==h.correct||new Set(answers.map(a=>a.id)).size!==answers.length)throw Error('Historique incohérent.');
    return {mode:h.mode,score:h.score,correct:h.correct,total:h.total,xp:h.xp,date:h.date,target:h.target,abandoned:!!h.abandoned,answers};
  });
  result.sound=raw.sound===true;result.badges=BADGES.filter(b=>Array.isArray(raw.badges)&&raw.badges.includes(b.id)).map(b=>b.id);
  // Une sauvegarde importée reprend le carnet, jamais un script ou une session arbitraire.
  result.active=null;return result;
}

const QUESTIONS=[{"id":"nat-in-01","category":"animals","subtheme":"Insectes","difficulty":1,"type":"qcm","question":"Combien de pattes possède normalement un insecte adulte ?","options":["Quatre","Six","Huit","Dix"],"correct":1,"explanation":"Les insectes ont trois paires de pattes fixées au thorax, soit six pattes. Les araignées adultes en ont huit : elles appartiennent aux arachnides.","source":"https://www.mnhn.fr/fr/qu-est-ce-qu-un-insecte"},{"id":"nat-in-02","category":"animals","subtheme":"Insectes","difficulty":1,"type":"qcm","question":"Comment appelle-t-on la larve d’un papillon ?","options":["Une nymphe","Une chenille","Un têtard","Un alevin"],"correct":1,"explanation":"La chenille est le stade larvaire du papillon, consacré surtout à l’alimentation et à la croissance. La chrysalide vient ensuite ; un têtard est une larve d’amphibien."},{"id":"nat-in-03","category":"animals","subtheme":"Insectes","difficulty":1,"type":"qcm","question":"Quel transport réalisé par des abeilles contribue à la reproduction de nombreuses plantes à fleurs ?","options":["Le transport de pollen entre fleurs","Le transport de graines sous terre","Le transport de sève entre tiges","Le transport de racines entre sols"],"correct":0,"explanation":"En visitant les fleurs, une abeille peut déposer du pollen sur un stigmate compatible : c’est la pollinisation. Elle ne transporte pas directement les cellules reproductrices jusqu’à l’ovule ; un tube pollinique pourra ensuite se développer."},{"id":"nat-in-04","category":"animals","subtheme":"Insectes","difficulty":1,"type":"boolean","question":"Une araignée adulte est un insecte.","options":["Vrai","Faux"],"correct":1,"explanation":"Une araignée est un arachnide, pas un insecte. Elle possède notamment quatre paires de pattes et aucune antenne, alors qu’un insecte adulte possède trois paires de pattes et une paire d’antennes."},{"id":"nat-in-05","category":"animals","subtheme":"Insectes","difficulty":2,"type":"qcm","question":"Pourquoi des coccinelles comme la coccinelle à sept points sont-elles utiles contre les pucerons ?","options":["Elles mangent les pucerons","Elles mangent principalement les racines des plantes hôtes","Elles repoussent les pucerons en consommant seulement du nectar","Elles empêchent les pucerons de se nourrir en fermant les feuilles"],"correct":0,"explanation":"Les larves et les adultes de cette espèce consomment des pucerons. Toutes les coccinelles n’ont toutefois pas le même régime : certaines mangent des champignons ou des plantes.","variant":"Au jardin, comment la coccinelle à sept points contribue-t-elle à limiter les populations de pucerons ?"},{"id":"nat-in-06","category":"animals","subtheme":"Insectes","difficulty":2,"type":"qcm","question":"Quelle succession décrit la métamorphose complète d’un papillon ?","options":["Œuf → chrysalide → chenille → adulte","Chenille → œuf → adulte → chrysalide","Œuf → chenille → chrysalide → adulte","Œuf → petit adulte → grand adulte"],"correct":2,"explanation":"Une larve très différente de l’adulte précède le stade nymphal, appelé chrysalide chez les papillons. Les criquets suivent au contraire un développement sans ce stade nymphal immobile.","source":"https://insectes.org/ressources/fiches-pedagogiques/les-insectes-qui-sont-ils/"},{"id":"nat-in-07","category":"animals","subtheme":"Insectes","difficulty":2,"type":"qcm","question":"Combien d’ailes fonctionnelles pour le vol possède normalement une mouche domestique ?","options":["Deux","Quatre","Six","Aucune"],"correct":0,"explanation":"La mouche possède une seule paire d’ailes de vol. Sa seconde paire est transformée en petits balanciers ; les abeilles et les papillons ont normalement deux paires d’ailes."},{"id":"nat-in-08","category":"animals","subtheme":"Insectes","difficulty":2,"type":"qcm","question":"Quelle différence distingue principalement le nectar du pollen ?","options":["Le nectar porte les gamétophytes mâles ; le pollen est une sécrétion sucrée","Le nectar est une sécrétion sucrée ; le pollen porte les gamétophytes mâles","Le nectar contient les ovules ; le pollen ne sert qu’à attirer les insectes","Le nectar et le pollen sont deux noms du même liquide"],"correct":1,"explanation":"Le nectar est une ressource sucrée, tandis que les grains de pollen participent à la reproduction de la plante. Les abeilles récoltent les deux, qui ne remplissent pas la même fonction."},{"id":"nat-in-09","category":"animals","subtheme":"Insectes","difficulty":3,"type":"qcm","question":"Que sont les élytres d’un coléoptère ?","options":["Des antennes olfactives","Des ailes antérieures durcies","Des branchies abdominales","Des mandibules creuses"],"correct":1,"explanation":"Les élytres sont les ailes antérieures transformées en étuis protecteurs. Chez beaucoup de coléoptères, les ailes postérieures se déploient sous ces étuis pour assurer le vol."},{"id":"nat-in-10","category":"animals","subtheme":"Insectes","difficulty":3,"type":"qcm","question":"Chez la plupart des insectes terrestres, quel système apporte directement l’air aux tissus ?","options":["Un réseau de trachées","Des poumons à alvéoles","Des branchies externes permanentes","Un réseau d’artères rempli d’air"],"correct":0,"explanation":"Des orifices appelés stigmates ouvrent sur un réseau de trachées et de trachéoles. Le transport du dioxygène dépend donc peu de l’hémolymphe, contrairement au rôle du sang chez les humains."},{"id":"nat-in-11","category":"animals","subtheme":"Insectes","difficulty":3,"type":"qcm","question":"Quel stade manque au développement habituel d’un criquet, comparé à celui d’un papillon ?","options":["L’œuf","Le stade juvénile qui s’alimente","L’adulte reproducteur","La nymphe de métamorphose complète"],"correct":3,"explanation":"Le jeune criquet ressemble progressivement à l’adulte au fil des mues : il n’existe pas de chrysalide. Cela ne signifie pas qu’il naît adulte ; ses ailes et ses organes reproducteurs se développent encore."},{"id":"nat-in-12","category":"animals","subtheme":"Insectes","difficulty":3,"type":"boolean","question":"Une diapause d’insecte est toujours un simple engourdissement qui cesse dès que la température remonte.","options":["Vrai","Faux"],"correct":1,"explanation":"La diapause est un arrêt de développement régulé, souvent lié aux saisons. Elle peut persister malgré une chaleur momentanée, ce qui la distingue d’un ralentissement directement imposé par le froid.","source":"https://dico.insectes.org/letters/D/Diss%C3%A9mination"},{"id":"nat-in-13","category":"animals","subtheme":"Insectes","difficulty":4,"type":"qcm","question":"Quelle combinaison caractérise l’eusocialité classique chez les insectes ?","options":["Vie en groupe, soins aux jeunes et absence de spécialisation reproductive","Reproduction solitaire et regroupement saisonnier des adultes","Générations qui se chevauchent, soins coopératifs et division reproductive du travail","Soins parentaux sans cohabitation entre générations"],"correct":2,"explanation":"L’eusocialité associe la coopération pour élever les jeunes, plusieurs générations et une spécialisation dans la reproduction. Un rassemblement temporaire d’individus ne suffit donc pas à constituer une société eusociale.","source":"https://insectes.org/faq/insectes-sociaux-subsociaux-eusociaux-quelle-difference/"},{"id":"nat-in-14","category":"animals","subtheme":"Insectes","difficulty":4,"type":"qcm","question":"Qu’est-ce qui distingue un insecte parasitoïde d’un parasite qui conserve durablement son hôte vivant ?","options":["Il consomme obligatoirement de nombreux hôtes pendant un même développement larvaire","Son développement conduit normalement à la mort de l’hôte","Il ne se développe qu’à l’extérieur de l’hôte","Il a toujours la même espèce pour hôte et pour partenaire reproducteur"],"correct":1,"explanation":"La larve d’un parasitoïde se développe aux dépens d’un hôte qu’elle finit normalement par tuer. De petites guêpes parasitoïdes sont ainsi utilisées en protection biologique des cultures.","source":"https://mffp.gouv.qc.ca/wp-content/uploads/parasitoide.pdf"},{"id":"nat-in-15","category":"animals","subtheme":"Insectes","difficulty":4,"type":"qcm","question":"Après plusieurs traitements identiques, une population d’insectes devient résistante. Quel mécanisme peut l’expliquer sans supposer que les insectes « décident » de s’adapter ?","options":["Tous les individus sensibles acquièrent le même variant adaptatif au premier contact","Les individus porteurs de variants héréditaires résistants laissent davantage de descendants","Les résistances acquises dans les cellules somatiques sont toujours transmises aux descendants","La fréquence des variants reste nécessairement constante au fil des générations"],"correct":1,"explanation":"Le traitement peut favoriser les variants résistants déjà présents ou apparus par mutation. Leur fréquence augmente au fil des générations : la sélection agit sur une diversité héréditaire, sans projet conscient."},{"id":"nat-in-16","category":"animals","subtheme":"Insectes","difficulty":4,"type":"qcm","question":"Une espèce inoffensive ressemble à une espèce défendue et profite de l’évitement appris par les prédateurs. Quel type de mimétisme décrit ce cas ?","options":["Un mimétisme batésien","Un mimétisme müllérien","Un camouflage cryptique par ressemblance avec le milieu","Un mimétisme agressif servant à approcher une proie"],"correct":0,"explanation":"Dans le mimétisme batésien, un imitateur peu ou pas défendu ressemble à un modèle protégé. Dans le mimétisme müllérien, plusieurs espèces réellement défendues partagent au contraire un signal d’avertissement.","source":"https://sciences.sorbonne-universite.fr/actualites/quels-messages-codes-portent-les-ailes-des-papillons"},{"id":"nat-fa-01","category":"animals","subtheme":"Faune","difficulty":1,"type":"qcm","question":"Pourquoi un dauphin est-il classé parmi les mammifères ?","options":["Il possède des branchies","Il allaite ses petits","Il vit uniquement en eau douce","Il pond des œufs à coquille"],"correct":1,"explanation":"Une femelle dauphin produit du lait pour son petit, un caractère des mammifères. La vie aquatique et la forme du corps ne font donc pas du dauphin un poisson."},{"id":"nat-fa-02","category":"animals","subtheme":"Faune","difficulty":1,"type":"qcm","question":"À quel groupe appartient une grenouille ?","options":["Aux reptiles","Aux poissons cartilagineux","Aux amphibiens","Aux mammifères"],"correct":2,"explanation":"La grenouille est un amphibien. Son cycle comprend généralement une larve aquatique et une métamorphose, même si les modes de reproduction varient beaucoup selon les espèces."},{"id":"nat-fa-03","category":"animals","subtheme":"Faune","difficulty":1,"type":"qcm","question":"Quel revêtement est caractéristique des oiseaux actuels ?","options":["Les poils","Les plumes","Les élytres","Les écailles placoïdes"],"correct":1,"explanation":"Tous les oiseaux actuels possèdent des plumes, même ceux qui ne volent pas. Les ailes seules ne permettent pas de reconnaître un oiseau : les chauves-souris ont aussi des ailes."},{"id":"nat-fa-04","category":"animals","subtheme":"Faune","difficulty":1,"type":"qcm","question":"Quel animal possède une colonne vertébrale ?","options":["Un escargot","Un ver de terre","Une pieuvre","Une truite"],"correct":3,"explanation":"La truite est un vertébré : son squelette interne comprend une colonne vertébrale. L’escargot et la pieuvre sont des mollusques ; le ver de terre est un annélide."},{"id":"nat-fa-05","category":"animals","subtheme":"Faune","difficulty":2,"type":"qcm","question":"Pourquoi une baleine doit-elle revenir à la surface pour respirer ?","options":["Ses poumons doivent recevoir de l’air","Ses branchies doivent sécher","Elle ne peut absorber l’eau qu’en surface","Le dioxygène n’existe jamais dans l’eau"],"correct":0,"explanation":"Les baleines respirent l’air avec des poumons, par leurs évents. De nombreux animaux aquatiques absorbent au contraire le dioxygène dissous dans l’eau grâce à des branchies.","variant":"Une baleine ne peut pas rester indéfiniment sous l’eau pour respirer. Quelle caractéristique explique son retour à la surface ?"},{"id":"nat-fa-06","category":"animals","subtheme":"Faune","difficulty":2,"type":"qcm","question":"Comment de nombreuses chauves-souris repèrent-elles de petits obstacles dans l’obscurité ?","options":["En analysant l’écho de leurs sons","En produisant de la lumière visible","En suivant uniquement les courants d’eau","En détectant exclusivement la couleur des objets"],"correct":0,"explanation":"L’écholocation consiste à émettre des sons puis à analyser leurs échos. Les chauves-souris possèdent également des yeux : l’écholocation ne signifie pas qu’elles sont aveugles."},{"id":"nat-fa-07","category":"animals","subtheme":"Faune","difficulty":2,"type":"boolean","question":"Tous les mammifères sont vivipares : aucun ne pond d’œufs à l’extérieur du corps.","options":["Vrai","Faux"],"correct":1,"explanation":"Les monotrèmes, dont l’ornithorynque et les échidnés, pondent des œufs. Ils restent des mammifères, notamment parce que les femelles produisent du lait pour nourrir leurs petits."},{"id":"nat-fa-08","category":"animals","subtheme":"Faune","difficulty":2,"type":"qcm","question":"Que détecte notamment la ligne latérale d’un poisson ?","options":["La couleur des objets proches","Les mouvements et vibrations de l’eau","Le goût des substances dissoutes","L’orientation du champ magnétique uniquement"],"correct":1,"explanation":"La ligne latérale comporte des récepteurs sensibles aux déplacements de l’eau. Elle aide notamment à détecter des proies ou des obstacles proches, sans remplacer les autres sens."},{"id":"nat-fa-09","category":"animals","subtheme":"Faune","difficulty":3,"type":"qcm","question":"Que signifie « ectotherme » pour un lézard ?","options":["Sa température dépend surtout de sources externes de chaleur","Sa température reste toujours inférieure à 0 °C","Il ne peut jamais modifier sa température","Il ne produit aucune chaleur métabolique"],"correct":0,"explanation":"Un ectotherme dépend largement de l’environnement pour son bilan thermique. Un lézard peut néanmoins réguler sa température par son comportement, par exemple en passant du soleil à l’ombre."},{"id":"nat-fa-10","category":"animals","subtheme":"Faune","difficulty":3,"type":"qcm","question":"Pourquoi une vache peut-elle tirer beaucoup d’énergie de végétaux riches en cellulose ?","options":["Ses propres enzymes digestives dégradent seules toute la cellulose","Des micro-organismes de son appareil digestif fermentent les fibres","La cellulose traverse intacte la paroi intestinale et fournit directement de l’énergie","La rumination suffit à convertir mécaniquement toute la cellulose en sucres"],"correct":1,"explanation":"Le rumen abrite des micro-organismes capables de dégrader des fibres végétales. Leurs produits de fermentation, notamment des acides gras volatils, fournissent de l’énergie à la vache."},{"id":"nat-fa-11","category":"animals","subtheme":"Faune","difficulty":3,"type":"qcm","question":"Quel mollusque appartient aux céphalopodes ?","options":["L’huître","La limace","La pieuvre","La moule"],"correct":2,"explanation":"Les pieuvres, calmars et seiches sont des céphalopodes, dont les appendices entourent la bouche. Les huîtres et les moules sont des bivalves ; les limaces sont des gastéropodes."},{"id":"nat-fa-12","category":"animals","subtheme":"Faune","difficulty":3,"type":"qcm","question":"Quel rôle jouent principalement les sacs aériens des oiseaux dans la respiration ?","options":["Ils remplacent les poumons pour les échanges gazeux","Ils font circuler l’air à travers les poumons","Ils stockent seulement le CO₂ avant son élimination par les reins","Ils agissent principalement comme des alvéoles très vascularisées"],"correct":1,"explanation":"Les sacs aériens fonctionnent surtout comme des soufflets qui ventilent les poumons. Les échanges avec le sang se déroulent principalement dans les poumons, et non dans les sacs eux-mêmes."},{"id":"nat-fa-13","category":"animals","subtheme":"Faune","difficulty":4,"type":"qcm","question":"Quel avantage procure l’écoulement à contre-courant entre l’eau et le sang dans beaucoup de branchies de poissons ?","options":["Il maintient un gradient favorable au transfert de dioxygène le long des lamelles","Il impose un équilibre de concentration dès l’entrée des lamelles","Il dirige l’eau et le sang dans le même sens pour limiter les pertes","Il supprime la nécessité d’un renouvellement de l’eau"],"correct":0,"explanation":"L’eau et le sang circulent en sens opposés, ce qui entretient une différence de concentration sur une grande partie de l’échangeur. Un équilibre immédiat entre les deux milieux limiterait au contraire l’extraction du dioxygène."},{"id":"nat-fa-14","category":"animals","subtheme":"Faune","difficulty":4,"type":"qcm","question":"Quelle innovation caractérise l’œuf des amniotes, y compris lorsque son développement se déroule dans l’utérus ?","options":["Un embryon dépourvu de membranes","Des membranes extra-embryonnaires, dont l’amnios","Une fécondation obligatoirement externe","Une larve qui doit respirer dans une mare"],"correct":1,"explanation":"L’amnios entoure l’embryon dans un milieu liquide protégé. Les amniotes regroupent notamment les mammifères, les oiseaux et les autres reptiles ; une coquille dure n’est pas obligatoire."},{"id":"nat-fa-15","category":"animals","subtheme":"Faune","difficulty":4,"type":"qcm","question":"Les os du bras humain et ceux du membre antérieur d’une chauve-souris ont un plan commun hérité. Quel terme décrit ce lien ?","options":["Une homologie","Une analogie sans origine commune du membre","Une convergence de fonction uniquement","Une identité complète de forme et de fonction"],"correct":0,"explanation":"Des structures homologues dérivent d’une structure présente chez un ancêtre commun. Leurs fonctions peuvent diverger : manipuler chez l’humain, soutenir une aile chez la chauve-souris."},{"id":"nat-fa-16","category":"animals","subtheme":"Faune","difficulty":4,"type":"qcm","question":"Le corps fuselé d’un requin et celui d’un dauphin illustrent surtout quelle idée évolutive ?","options":["Une parenté plus proche entre dauphins et requins qu’entre dauphins et vaches","Des contraintes comparables peuvent favoriser des formes similaires dans des lignées différentes","Une homologie de toutes leurs nageoires avec des structures identiques","Une absence d’adaptations au milieu aquatique"],"correct":1,"explanation":"C’est un exemple de convergence évolutive liée notamment aux contraintes du déplacement dans l’eau. Le requin est un poisson cartilagineux et le dauphin un mammifère : la silhouette ne suffit pas à établir la parenté."},{"id":"nat-bi-01","category":"animals","subtheme":"Biodiversité","difficulty":1,"type":"boolean","question":"La biodiversité comprend seulement le nombre d’espèces animales.","options":["Vrai","Faux"],"correct":1,"explanation":"Elle inclut aussi les plantes, les champignons et les micro-organismes. On distingue notamment la diversité génétique, celle des espèces et celle des écosystèmes.","source":"https://www.mnhn.fr/fr/qu-est-ce-que-la-biodiversite"},{"id":"nat-bi-02","category":"animals","subtheme":"Biodiversité","difficulty":1,"type":"qcm","question":"Quel organisme participe à la décomposition de feuilles mortes ?","options":["Un champignon saprotrophe","Une feuille vivante qui photosynthétise","Un caillou de granite","Une goutte d’eau pure sans organisme"],"correct":0,"explanation":"Un champignon saprotrophe obtient sa matière et son énergie en dégradant de la matière organique morte. Cette décomposition contribue au recyclage des éléments dans les écosystèmes."},{"id":"nat-bi-03","category":"animals","subtheme":"Biodiversité","difficulty":1,"type":"qcm","question":"Qu’appelle-t-on l’habitat d’une espèce ?","options":["Uniquement le nid où elle se reproduit","Le milieu où elle vit et trouve les conditions nécessaires","Sa place exacte dans la classification","La quantité totale de ses descendants"],"correct":1,"explanation":"Un habitat fournit des conditions et des ressources à une espèce. Ce peut être une mare, une forêt ou même un morceau de bois mort, selon l’organisme considéré."},{"id":"nat-bi-04","category":"animals","subtheme":"Biodiversité","difficulty":1,"type":"qcm","question":"Dans la chaîne herbe → lapin → renard, quel organisme est un producteur primaire ?","options":["Le renard","Le lapin","L’herbe","Le lapin et le renard"],"correct":2,"explanation":"L’herbe fabrique sa matière organique à partir de matière minérale grâce à l’énergie lumineuse. Le lapin et le renard obtiennent leur matière en consommant d’autres êtres vivants."},{"id":"nat-bi-05","category":"animals","subtheme":"Biodiversité","difficulty":2,"type":"qcm","question":"Que signifie le fait qu’une espèce soit endémique d’une île ?","options":["Elle vit naturellement uniquement dans cette région","Elle arrive chaque année par migration depuis tous les continents","Elle est nécessairement très abondante partout","Elle a été domestiquée sur cette île"],"correct":0,"explanation":"Une espèce endémique possède une aire naturelle restreinte à une région définie. Le terme ne dit pas, à lui seul, combien d’individus existent ni si l’espèce est menacée.","variant":"Une espèce est décrite comme « endémique » d’une île. Que peut-on en déduire sur sa répartition naturelle ?"},{"id":"nat-bi-06","category":"animals","subtheme":"Biodiversité","difficulty":2,"type":"qcm","question":"Qu’appelle-t-on une espèce clé de voûte dans un écosystème ?","options":["L’espèce toujours la plus grosse","Une espèce dont l’effet écologique est important par rapport à son abondance","L’espèce dont le nom scientifique est le plus ancien","Une espèce qui n’a aucune interaction avec les autres"],"correct":1,"explanation":"Une espèce clé de voûte exerce une influence disproportionnée sur la structure du réseau écologique. Son retrait peut donc entraîner des changements importants, même si elle est peu abondante."},{"id":"nat-bi-07","category":"animals","subtheme":"Biodiversité","difficulty":2,"type":"qcm","question":"Quelle affirmation décrit correctement une espèce exotique envahissante ?","options":["Toute espèce observée pour la première fois par quelqu’un","Toute espèce originaire d’un autre pays, même sans impact","Une espèce introduite hors de son aire naturelle dont l’expansion entraîne des effets négatifs sur la biodiversité","Une espèce indigène qui produit beaucoup de graines"],"correct":2,"explanation":"L’origine extérieure ne suffit pas : le caractère envahissant renvoie à l’expansion et à ses impacts. Une plante introduite qui reste localisée sans effet négatif démontré n’est pas automatiquement une espèce exotique envahissante."},{"id":"nat-bi-08","category":"animals","subtheme":"Biodiversité","difficulty":2,"type":"qcm","question":"Deux espèces retirent chacune un bénéfice de leur interaction. Comment qualifie-t-on cette relation ?","options":["Une compétition","Un mutualisme","Une prédation","Un parasitisme"],"correct":1,"explanation":"Dans un mutualisme, les deux partenaires bénéficient de l’interaction. Ce bénéfice peut dépendre du contexte et n’implique pas nécessairement qu’ils vivent en permanence associés."},{"id":"nat-bi-09","category":"animals","subtheme":"Biodiversité","difficulty":3,"type":"qcm","question":"Pourquoi un corridor écologique peut-il être utile entre deux habitats séparés ?","options":["Il augmente l’isolement reproducteur entre toutes les populations","Il facilite les déplacements et parfois les échanges génétiques","Il remplace tous les habitats de reproduction par une zone de passage","Il empêche nécessairement la dispersion des espèces exotiques"],"correct":1,"explanation":"Un corridor adapté peut relier des populations et faciliter la recolonisation de milieux. Son efficacité dépend des espèces et du paysage : une bande de végétation n’est pas une solution universelle."},{"id":"nat-bi-10","category":"animals","subtheme":"Biodiversité","difficulty":3,"type":"qcm","question":"Comment un excès de nutriments peut-il conduire à un manque de dioxygène dans un lac ?","options":["Les nutriments empêchent physiquement toute dissolution de gaz","La prolifération puis la décomposition d’organismes accroissent la consommation de dioxygène","La photosynthèse consomme directement le dioxygène pendant le jour","Les poissons produisent davantage de dioxygène quand les algues prolifèrent"],"correct":1,"explanation":"Des apports excessifs d’azote ou de phosphore peuvent stimuler des proliférations. La respiration et la décomposition de cette biomasse consomment du dioxygène, parfois plus vite qu’il n’est renouvelé."},{"id":"nat-bi-11","category":"animals","subtheme":"Biodiversité","difficulty":3,"type":"qcm","question":"La capacité d’accueil d’un milieu pour une population est-elle nécessairement fixe ?","options":["Oui, elle dépend uniquement de la surface","Oui, elle reste identique quelle que soit la saison","Non, les ressources et les conditions peuvent la faire varier","Non, elle augmente automatiquement à chaque naissance"],"correct":2,"explanation":"La capacité d’accueil dépend de ressources et de contraintes qui peuvent changer. Une sécheresse peut par exemple réduire la nourriture disponible, même si la surface du milieu reste identique."},{"id":"nat-bi-12","category":"animals","subtheme":"Biodiversité","difficulty":3,"type":"boolean","question":"Dans la sélection naturelle, la fréquence d’un caractère héréditaire peut changer dans une population au fil des générations.","options":["Vrai","Faux"],"correct":0,"explanation":"Si certains variants influencent la survie et surtout le succès reproducteur, leur fréquence peut évoluer. Ce sont les populations qui évoluent ainsi ; un individu ne transforme pas volontairement ses gènes pour répondre à un besoin."},{"id":"nat-bi-13","category":"animals","subtheme":"Biodiversité","difficulty":4,"type":"qcm","question":"Quatre communautés comptent chacune quatre espèces et cent individus. Quelle répartition possède la plus grande équitabilité des abondances ?","options":["90, 4, 3 et 3 individus","70, 10, 10 et 10 individus","25, 25, 25 et 25 individus","97, 1, 1 et 1 individus"],"correct":2,"explanation":"L’équitabilité est maximale lorsque les espèces ont des abondances identiques. La richesse spécifique vaut quatre dans les quatre cas : compter les espèces et décrire leur répartition sont deux mesures distinctes."},{"id":"nat-bi-14","category":"animals","subtheme":"Biodiversité","difficulty":4,"type":"qcm","question":"On marque 40 poissons, puis une nouvelle capture aléatoire en contient 60, dont 8 marqués. Quelle estimation simple donne la méthode capture-marquage-recapture ?","options":["68 poissons","120 poissons","240 poissons","300 poissons"],"correct":3,"explanation":"On suppose que la proportion de marqués dans l’échantillon représente celle de la population : 8/60 ≈ 40/N, donc N ≈ 300. Cela exige notamment un bon mélange, la conservation des marques et une population approximativement fermée."},{"id":"nat-bi-15","category":"animals","subtheme":"Biodiversité","difficulty":4,"type":"qcm","question":"Quelques individus fondent une population isolée avec une diversité génétique différente de celle de départ. Quel phénomène est en jeu ?","options":["Un effet fondateur","Une sélection stabilisante nécessairement déterministe","Une mutation de tous les génomes vers le même variant","Un brassage qui conserve forcément toutes les fréquences initiales"],"correct":0,"explanation":"Les fondateurs emportent un échantillon parfois peu représentatif des variants de la population d’origine. C’est une manifestation de la dérive génétique ; elle ne suppose pas que les variants retenus soient les plus avantageux.","source":"https://planet-vie.ens.fr/thematiques/evolution/mecanismes-theories-et-concepts-de-l-evolution/la-derive-genetique"},{"id":"nat-bi-16","category":"animals","subtheme":"Biodiversité","difficulty":4,"type":"qcm","question":"Un prédateur réduit des herbivores, ce qui permet à la végétation d’augmenter. Quel concept décrit cet effet indirect ?","options":["Une cascade trophique","Une bioaccumulation de polluants","Une compétition directe entre le prédateur et la végétation","Un mutualisme obligatoire entre les trois populations"],"correct":0,"explanation":"Une cascade trophique se propage entre plusieurs niveaux du réseau alimentaire. Cet exemple montre qu’un prédateur peut influencer indirectement des plantes ; l’intensité de cet effet dépend du contexte écologique."},{"id":"nat-pl-01","category":"nature","subtheme":"Plantes","difficulty":1,"type":"qcm","question":"Quelle partie d’une plante terrestre absorbe principalement l’eau et les éléments minéraux du sol ?","options":["Les pétales","Les racines","Les fruits","Les graines sèches"],"correct":1,"explanation":"Les racines, notamment leurs zones absorbantes, prélèvent l’eau et des éléments minéraux. Les feuilles sont surtout les lieux de la photosynthèse et d’importants échanges gazeux."},{"id":"nat-pl-02","category":"nature","subtheme":"Plantes","difficulty":1,"type":"qcm","question":"Quel pigment donne leur couleur verte à beaucoup de feuilles et participe à la capture de lumière ?","options":["La chlorophylle","L’hémoglobine","La mélanine","La kératine"],"correct":0,"explanation":"La chlorophylle absorbe notamment des lumières rouges et bleues, utilisées pour la photosynthèse. Une partie de la lumière verte est réfléchie ou transmise, ce qui contribue à la couleur perçue."},{"id":"nat-pl-03","category":"nature","subtheme":"Plantes","difficulty":1,"type":"qcm","question":"Que contient une graine viable de plante à fleurs ?","options":["Uniquement de l’eau","Un embryon de plante et des réserves, sous une enveloppe","Une fleur adulte déjà entièrement déployée","Un morceau de racine sans embryon"],"correct":1,"explanation":"Une graine protège un embryon et lui fournit des réserves pour le début du développement. Une graine n’est pas une petite fleur : les organes se développeront au cours de la germination et de la croissance."},{"id":"nat-pl-04","category":"nature","subtheme":"Plantes","difficulty":1,"type":"boolean","question":"Une plante verte cesse toute respiration cellulaire pendant la nuit.","options":["Vrai","Faux"],"correct":1,"explanation":"Les cellules vivantes d’une plante respirent le jour et la nuit pour obtenir de l’énergie utilisable. La photosynthèse dépend de la lumière, mais elle ne remplace pas la respiration."},{"id":"nat-pl-05","category":"nature","subtheme":"Plantes","difficulty":2,"type":"qcm","question":"Après fécondation, quelle structure d’une fleur devient généralement une graine ?","options":["Un pétale","Un grain de pollen","Un ovule","Une étamine entière"],"correct":2,"explanation":"L’ovule fécondé se transforme en graine. L’ovaire de la fleur participe quant à lui à la formation du fruit : graine et fruit ne désignent donc pas la même structure.","variant":"On suit le développement d’une fleur après la fécondation. À partir de quelle structure une graine se forme-t-elle généralement ?"},{"id":"nat-pl-06","category":"nature","subtheme":"Plantes","difficulty":2,"type":"qcm","question":"Quel compromis est lié à l’ouverture des stomates d’une feuille ?","options":["Faire entrer du CO₂ tout en risquant de perdre de l’eau","Absorber des racines tout en perdant des graines","Faire entrer du sable tout en perdant des minéraux solides","Produire du pollen tout en supprimant la respiration"],"correct":0,"explanation":"Les stomates permettent l’entrée du CO₂ nécessaire à la photosynthèse, mais la vapeur d’eau peut aussi s’en échapper. La plante ajuste leur ouverture selon ses conditions internes et l’environnement.","source":"https://www.inrae.fr/approchez-vous/plantes-resistance-secheresse"},{"id":"nat-pl-07","category":"nature","subtheme":"Plantes","difficulty":2,"type":"qcm","question":"Un tubercule de pomme de terre est principalement quelle sorte d’organe ?","options":["Une racine pivotante","Une tige souterraine renflée","Une graine très grosse","Un fruit enfoui"],"correct":1,"explanation":"La pomme de terre stocke des réserves dans des tubercules issus de tiges souterraines. Leurs « yeux » sont des bourgeons capables de former de nouvelles pousses, ce qui aide à reconnaître leur nature."},{"id":"nat-pl-08","category":"nature","subtheme":"Plantes","difficulty":2,"type":"qcm","question":"Quelles conditions sont généralement indispensables pour qu’une graine non dormante germe ?","options":["De l’eau, du dioxygène et une température adaptée","Une lumière intense et un sol riche pour toutes les espèces","Une absence de dioxygène et un excès permanent d’eau","Une terre fortement fertilisée, même sans eau"],"correct":0,"explanation":"L’eau réactive le fonctionnement de la graine, et la respiration réclame du dioxygène. Les exigences de lumière diffèrent selon les espèces ; elles ne constituent donc pas une règle identique pour toutes."},{"id":"nat-pl-09","category":"nature","subtheme":"Plantes","difficulty":3,"type":"qcm","question":"Dans une jeune tige qui se courbe vers une lumière latérale, quelle différence de croissance contribue à la courbure ?","options":["Le côté ombragé s’allonge davantage","Le côté éclairé s’allonge davantage","Les deux côtés s’allongent exactement à la même vitesse","Le côté ombragé se raccourcit sans croissance du côté éclairé"],"correct":0,"explanation":"Une redistribution de l’auxine favorise souvent l’allongement du côté ombragé de la jeune tige. Le côté qui grandit davantage pousse ainsi la tige à se courber vers la lumière."},{"id":"nat-pl-10","category":"nature","subtheme":"Plantes","difficulty":3,"type":"qcm","question":"Quel phénomène contribue fortement à faire monter la sève brute dans une plante qui transpire ?","options":["La traction liée à l’évaporation de l’eau dans les feuilles","Des contractions rythmiques des vaisseaux du xylème","Une circulation des sucres exclusivement dans le xylème","La seule flottabilité du bois dans la sève"],"correct":0,"explanation":"L’évaporation au niveau des feuilles crée une tension transmise à la colonne d’eau du xylème. La cohésion de l’eau participe à ce mécanisme ; les racines ne jouent pas le rôle d’un cœur qui pomperait toute cette eau."},{"id":"nat-pl-11","category":"nature","subtheme":"Plantes","difficulty":3,"type":"qcm","question":"Dans une mycorhize fonctionnelle, que fournit généralement la plante au champignon partenaire ?","options":["Des composés carbonés issus de la photosynthèse","Principalement les phosphates que le champignon ne peut absorber lui-même","De la chlorophylle qui rend systématiquement le champignon photosynthétique","De l’azote atmosphérique fixé directement par toutes ses feuilles"],"correct":0,"explanation":"La plante cède notamment des composés carbonés, tandis que le réseau fongique peut améliorer l’accès à des ressources minérales. Le bénéfice et son importance varient selon les partenaires et les conditions du sol.","source":"https://www.inrae.fr/actualites/interactions-au-coeur-guilde-champignons"},{"id":"nat-pl-12","category":"nature","subtheme":"Plantes","difficulty":3,"type":"qcm","question":"Qu’est-ce que la vernalisation chez certaines plantes ?","options":["Une réponse de courbure vers la lumière","L’effet d’une période de froid qui permet ou favorise ensuite la floraison","Une germination déclenchée uniquement par une hausse du CO₂","L’induction de la floraison par la seule longueur du jour, sans effet du froid"],"correct":1,"explanation":"Une exposition prolongée au froid peut modifier l’état de régulation de la floraison. Ce mécanisme aide certaines plantes à fleurir après l’hiver ; il ne faut pas le confondre avec une simple croissance plus rapide à la chaleur.","source":"https://planet-vie.ens.fr/media/3012"},{"id":"nat-pl-13","category":"nature","subtheme":"Plantes","difficulty":4,"type":"qcm","question":"Chez le maïs, plante en C4, quelle organisation aide à concentrer le CO₂ autour de la Rubisco ?","options":["Une séparation entre fixation initiale dans le mésophylle et cycle de Calvin dans la gaine périvasculaire","Une fixation initiale uniquement nocturne, dans les mêmes cellules que le cycle de Calvin","Une absence de toute fixation initiale du CO₂ avant le cycle de Calvin","Une séparation entre capture du CO₂ par les racines et capture de lumière par les feuilles"],"correct":0,"explanation":"Le maïs utilise deux types de cellules pour les étapes de capture et d’utilisation du carbone. Cette organisation limite la photorespiration dans certaines conditions, mais demande une dépense énergétique supplémentaire.","source":"https://www.snv.jussieu.fr/bmedia/Chloroplaste/mais.htm"},{"id":"nat-pl-14","category":"nature","subtheme":"Plantes","difficulty":4,"type":"qcm","question":"Quel décalage caractérise le métabolisme CAM de nombreux cactus ?","options":["Capture du CO₂ surtout la nuit, puis utilisation du carbone stocké pendant le jour","Capture du CO₂ surtout le jour, puis cycle de Calvin uniquement la nuit","Capture nocturne de la lumière, puis respiration exclusivement diurne","Fixation du carbone répartie entre deux types de cellules uniquement pendant le jour"],"correct":0,"explanation":"Le CO₂ est stocké sous forme de composés organiques pendant la nuit. Il peut être libéré le jour alors que les stomates restent davantage fermés, ce qui limite les pertes d’eau.","source":"https://www.inrae.fr/approchez-vous/plantes-resistance-secheresse"},{"id":"nat-pl-15","category":"nature","subtheme":"Plantes","difficulty":4,"type":"qcm","question":"Deux solutions sont séparées par une membrane perméable à l’eau mais pas au soluté. À pression initiale égale, vers où se fait le flux net d’eau osmotique ?","options":["Vers la solution la moins concentrée en soluté","Vers la solution la plus concentrée en soluté","Aucun flux net ne peut apparaître tant que la pression initiale est égale","Le flux est imposé uniquement par la taille des molécules de soluté"],"correct":1,"explanation":"Dans ces conditions simplifiées, l’eau se déplace vers la solution où son potentiel chimique est le plus faible, généralement la plus concentrée en soluté. Les différences de pression peuvent ensuite modifier ou équilibrer ce mouvement."},{"id":"nat-pl-16","category":"nature","subtheme":"Plantes","difficulty":4,"type":"qcm","question":"Chez une fougère, que produit directement la méiose dans les sporanges ?","options":["Des spores diploïdes","Des spores haploïdes","Des gamètes haploïdes directement","Des zygotes diploïdes"],"correct":1,"explanation":"La méiose produit des spores haploïdes qui peuvent donner un gamétophyte. Celui-ci fabrique les gamètes par mitose : il faut distinguer spores et gamètes dans l’alternance des générations."},{"id":"nat-ar-01","category":"nature","subtheme":"Arbres","difficulty":1,"type":"qcm","question":"Quel arbre produit des glands ?","options":["Le hêtre","Le chêne","L’érable","Le bouleau"],"correct":1,"explanation":"Le gland est le fruit du chêne, contenant normalement une graine. Le hêtre produit des faînes et l’érable des fruits ailés appelés samares."},{"id":"nat-ar-02","category":"nature","subtheme":"Arbres","difficulty":1,"type":"qcm","question":"Que signifie « arbre à feuillage caduc » ?","options":["Un arbre qui ne produit jamais de feuilles","Un arbre qui perd ses feuilles à une saison donnée","Un arbre dont chaque feuille reste toute la vie","Un arbre qui pousse uniquement sous l’eau"],"correct":1,"explanation":"Un feuillage caduc est renouvelé après une chute saisonnière, souvent en automne dans les régions tempérées. Un feuillage persistant est lui aussi renouvelé, mais sans perdre habituellement toutes ses feuilles en même temps."},{"id":"nat-ar-03","category":"nature","subtheme":"Arbres","difficulty":1,"type":"qcm","question":"Sur quelle structure un pin porte-t-il ses graines ?","options":["Sur les écailles d’un cône femelle","Dans une pomme charnue","À l’intérieur de ses racines","Sur les seules pointes de ses aiguilles"],"correct":0,"explanation":"Chez le pin, les graines se développent sur les écailles des cônes femelles. Un cône n’est pas un fruit au sens botanique, car il ne provient pas d’un ovaire."},{"id":"nat-ar-04","category":"nature","subtheme":"Arbres","difficulty":1,"type":"qcm","question":"Que représentent généralement les cernes d’un tronc d’arbre de région tempérée à croissance saisonnière ?","options":["Les traces de chaque pluie","Les couches de croissance successives du bois","Les emplacements des racines mortes","Des réserves de pollen"],"correct":1,"explanation":"Les variations saisonnières de production du bois forment souvent un cerne par an. Compter des cernes demande cependant de la prudence : certains peuvent manquer ou être difficiles à distinguer."},{"id":"nat-ar-05","category":"nature","subtheme":"Arbres","difficulty":2,"type":"boolean","question":"Tous les conifères gardent leurs aiguilles pendant l’hiver.","options":["Vrai","Faux"],"correct":1,"explanation":"Le mélèze est un conifère à feuillage caduc : il perd ses aiguilles en automne. Le groupe des conifères et la persistance du feuillage ne sont donc pas des notions équivalentes.","variant":"Les conifères ont tous un feuillage persistant, qu’ils conservent pendant l’hiver."},{"id":"nat-ar-06","category":"nature","subtheme":"Arbres","difficulty":2,"type":"qcm","question":"Pourquoi des couleurs jaunes deviennent-elles visibles dans de nombreuses feuilles en automne ?","options":["La chlorophylle se dégrade et laisse mieux voir d’autres pigments","La chlorophylle verte se transforme directement en caroténoïdes jaunes dans tous les cas","La couleur jaune apparaît uniquement par manque de dioxygène dans l’air","Les pigments jaunes arrivent des racines seulement après la première gelée"],"correct":0,"explanation":"Des pigments jaunes, notamment des caroténoïdes, sont souvent présents mais masqués par la chlorophylle. Les rouges ont parfois une autre origine, avec la production d’anthocyanes : toutes les couleurs ne suivent pas exactement le même mécanisme."},{"id":"nat-ar-07","category":"nature","subtheme":"Arbres","difficulty":2,"type":"qcm","question":"Quel est le rôle des écailles de nombreux bourgeons d’arbres en hiver ?","options":["Remplacer les racines","Protéger les jeunes tissus en développement","Fabriquer directement les graines","Transporter la sève dans les fleurs"],"correct":1,"explanation":"Les écailles protègent les tissus fragiles du bourgeon contre diverses contraintes, notamment la dessiccation. Le bourgeon peut déjà contenir les ébauches des feuilles ou des fleurs de la saison suivante."},{"id":"nat-ar-08","category":"nature","subtheme":"Arbres","difficulty":2,"type":"qcm","question":"Quelle est une fonction importante de l’écorce externe d’un arbre ?","options":["Transporter principalement la sève brute dans ses cellules mortes externes","Constituer une protection contre les agressions extérieures","Absorber la majeure partie des minéraux directement depuis l’air","Assurer à elle seule toute la croissance en hauteur"],"correct":1,"explanation":"L’écorce externe forme une barrière contre des dommages mécaniques et limite les pertes d’eau des tissus sous-jacents. Sa texture et son épaisseur diffèrent selon les espèces et l’âge de l’arbre."},{"id":"nat-ar-09","category":"nature","subtheme":"Arbres","difficulty":3,"type":"qcm","question":"Dans quel tissu circule principalement la sève brute, riche en eau et en éléments minéraux ?","options":["Le xylème","Le phloème","Le liège externe","Le méristème apical uniquement"],"correct":0,"explanation":"Le xylème assure principalement le transport de l’eau absorbée par les racines. Le phloème transporte notamment des composés organiques depuis les organes sources vers les organes qui les utilisent ou les stockent.","source":"https://www.snv.jussieu.fr/bmedia/bois/bois-tronc.htm"},{"id":"nat-ar-10","category":"nature","subtheme":"Arbres","difficulty":3,"type":"qcm","question":"Quel énoncé décrit le mieux le transport dans le phloème ?","options":["Il va toujours des racines vers les feuilles","Il va des organes sources vers les organes consommateurs ou de réserve","Il descend toujours, indépendamment des besoins des organes","Il transporte les éléments minéraux sans aucun composé organique"],"correct":1,"explanation":"Une feuille mature peut exporter des sucres vers un fruit, une racine ou un jeune bourgeon. Les sources et les puits changent au cours du développement : il ne s’agit pas simplement d’une sève qui descend toujours."},{"id":"nat-ar-11","category":"nature","subtheme":"Arbres","difficulty":3,"type":"qcm","question":"Quel tissu produit le bois secondaire vers l’intérieur et le liber vers l’extérieur ?","options":["Le cambium vasculaire","Le liège mort uniquement","La moelle uniquement","La cuticule des feuilles"],"correct":0,"explanation":"Le cambium vasculaire est une fine zone de cellules qui se divisent et contribuent à la croissance en épaisseur. Le bois est du xylème secondaire et le liber du phloème secondaire.","source":"https://www.snv.jussieu.fr/bmedia/bois/bois-tronc.htm"},{"id":"nat-ar-12","category":"nature","subtheme":"Arbres","difficulty":3,"type":"qcm","question":"Dans une ectomycorhize, où le champignon forme-t-il notamment son réseau d’échanges dans la racine ?","options":["Entre des cellules racinaires, avec un manteau autour de la racine","Uniquement sous forme d’arbuscules dans les cellules de la racine","Dans la lumière des vaisseaux du xylème, sans contact avec les tissus périphériques","Uniquement à la surface des feuilles, sans association racinaire"],"correct":0,"explanation":"Les ectomycorhizes présentent typiquement un manteau fongique et un réseau entre les cellules racinaires. Elles se distinguent ainsi des mycorhizes arbusculaires, qui forment des structures d’échange à l’intérieur de cellules racinaires.","source":"https://mycor.iam.inrae.fr/IAM/?page_id=4555"},{"id":"nat-ar-13","category":"nature","subtheme":"Arbres","difficulty":4,"type":"qcm","question":"En dendrochronologie, pourquoi compare-t-on les séquences de largeur des cernes entre plusieurs arbres ?","options":["Pour attribuer automatiquement une espèce à chaque cerne","Pour repérer des motifs communs et mieux dater des cernes éventuellement manquants","Pour supposer que tous les arbres d’un lieu ont exactement le même âge","Pour convertir directement la largeur d’un cerne en température exacte sans autre information"],"correct":1,"explanation":"L’interdatation utilise des variations communes de croissance pour aligner des séries de cernes. Elle aide à éviter l’erreur qui consisterait à supposer que chaque anneau visible correspond toujours parfaitement à une année distincte.","source":"https://archeologie.culture.gouv.fr/palafittes/fr/la-dendrochronologie"},{"id":"nat-ar-14","category":"nature","subtheme":"Arbres","difficulty":4,"type":"qcm","question":"Pourquoi une embolie du xylème peut-elle être dangereuse pendant une forte sécheresse ?","options":["Des gaz interrompent la continuité de l’eau dans des conduits","Les conduits se remplissent exclusivement de sucres solides transportés par le phloème","Tous les stomates restent automatiquement ouverts malgré la sécheresse","La cavitation augmente nécessairement le débit d’eau vers les feuilles"],"correct":0,"explanation":"La cavitation peut provoquer l’apparition ou l’expansion de gaz dans les conduits du xylème. Ces conduits perdent alors une partie de leur capacité à transporter l’eau, ce qui peut aggraver le stress hydrique.","source":"https://www.inrae.fr/actualites/secheresse-embolie-gazeuse-arbres"},{"id":"nat-ar-15","category":"nature","subtheme":"Arbres","difficulty":4,"type":"qcm","question":"Pourquoi la lignification est-elle importante dans le bois ?","options":["Elle rend les parois de certains tissus plus rigides et contribue au soutien","Elle supprime toutes les autres molécules des parois cellulaires","Elle est le mécanisme principal de stockage de l’amidon dans les racines","Elle rend les parois plus extensibles et entièrement solubles dans l’eau"],"correct":0,"explanation":"La lignine renforce certaines parois cellulaires et contribue aux propriétés mécaniques du bois. Elle participe aussi au fonctionnement de tissus conducteurs ; le bois n’est pas constitué uniquement de cellulose."},{"id":"nat-ar-16","category":"nature","subtheme":"Arbres","difficulty":4,"type":"qcm","question":"Après une blessure du tronc, quel mécanisme aide un arbre à limiter la propagation d’une dégradation ?","options":["Une compartimentation des tissus atteints, puis un recouvrement depuis la périphérie","Une régénération du bois ancien exactement à l’identique depuis le centre de la blessure","Une élimination de tous les champignons présents dans l’ensemble du sol","Un transport du bois endommagé vers les feuilles pour son élimination"],"correct":0,"explanation":"L’arbre peut isoler des zones lésées par des barrières et produire progressivement des tissus de recouvrement. Le bois abîmé ne redevient pas simplement du bois intact : limiter la taille des blessures reste important.","source":"https://pro.tourisme-occitanie.com/uploads/sites/10/2024/12/SUPPORT-PRESENTATION-ONF-Vegetis_CRTL_VVF_2024_compressed.pdf"},{"id":"nat-ja-01","category":"nature","subtheme":"Jardinage","difficulty":1,"type":"qcm","question":"Quel est un effet habituel d’un paillage couvrant le sol autour d’une plante ?","options":["Réduire l’évaporation de l’eau du sol","Augmenter directement la quantité de pluie reçue","Empêcher toute absorption d’eau par les racines","Remplacer tous les besoins de la plante en eau"],"correct":0,"explanation":"Le paillage limite l’exposition directe du sol au soleil et au vent, ce qui réduit souvent l’évaporation. Il faut néanmoins vérifier l’humidité : les besoins d’arrosage dépendent toujours de la plante, du sol et du climat."},{"id":"nat-ja-02","category":"nature","subtheme":"Jardinage","difficulty":1,"type":"qcm","question":"Que devient principalement un mélange bien géré de déchets végétaux pendant le compostage ?","options":["Un matériau organique transformé par des organismes décomposeurs","Une matière qui garde exactement sa structure initiale","Un engrais minéral pur sans matière organique","Une tourbe formée en quelques jours sans organisme vivant"],"correct":0,"explanation":"Des micro-organismes et d’autres décomposeurs transforment la matière organique. Le compost mûr peut améliorer le sol, mais ce n’est ni un produit stérile ni une solution universelle à tous les besoins nutritifs."},{"id":"nat-ja-03","category":"nature","subtheme":"Jardinage","difficulty":1,"type":"boolean","question":"Un pot percé évacue généralement mieux l’eau en excès qu’un contenant étanche rempli du même substrat.","options":["Vrai","Faux"],"correct":0,"explanation":"Les trous permettent à l’eau excédentaire de s’écouler, ce qui limite l’engorgement du substrat. Il faut également éviter de laisser les racines longtemps dans une soucoupe pleine d’eau lorsque la plante ne le tolère pas."},{"id":"nat-ja-04","category":"nature","subtheme":"Jardinage","difficulty":1,"type":"qcm","question":"Pour arroser efficacement une plante en pot, quelle zone faut-il surtout humidifier ?","options":["Uniquement les pétales","La motte où se trouvent les racines","Seulement la surface de deux ou trois feuilles","Uniquement le bord extérieur du pot, sans mouiller la motte"],"correct":1,"explanation":"L’eau doit atteindre les racines réparties dans la motte, avec une quantité adaptée au substrat et à la plante. Mouiller quelques feuilles ne remplace pas un arrosage du substrat."},{"id":"nat-ja-05","category":"nature","subtheme":"Jardinage","difficulty":2,"type":"qcm","question":"Pourquoi alterner les familles de légumes sur une parcelle peut-il être utile ?","options":["Cela peut perturber les cycles de certains bioagresseurs liés à leurs plantes hôtes","Cela élimine tous les agents pathogènes dès la première rotation","Cela garantit que toutes les cultures ont exactement les mêmes besoins","Cela remplace nécessairement tous les apports de matière organique"],"correct":0,"explanation":"Une rotation bien choisie réduit la répétition d’hôtes pour certains ravageurs ou maladies. Ses bénéfices dépendent des organismes et des cultures : changer uniquement la variété d’un même légume ne suffit pas toujours.","variant":"Quelle raison peut justifier de ne pas cultiver chaque année des légumes de la même famille sur une même parcelle ?"},{"id":"nat-ja-06","category":"nature","subtheme":"Jardinage","difficulty":2,"type":"qcm","question":"Pourquoi retirer certaines fleurs fanées peut-il prolonger la floraison de plantes ornementales ?","options":["Cela réduit obligatoirement les besoins de la plante en lumière","Cela limite l’investissement dans les graines et peut favoriser de nouveaux boutons","Cela augmente directement l’absorption de pollen par les racines","Cela rend toutes les plantes annuelles vivaces"],"correct":1,"explanation":"Chez certaines plantes, enlever les fleurs fanées réduit la mise à graines et peut encourager une nouvelle floraison. L’effet dépend de l’espèce ; conserver des graines ou des fruits peut aussi être souhaitable."},{"id":"nat-ja-07","category":"nature","subtheme":"Jardinage","difficulty":2,"type":"boolean","question":"Ajouter davantage d’engrais améliore toujours la croissance d’une plante, quelle que soit la dose.","options":["Vrai","Faux"],"correct":1,"explanation":"Un excès peut déséquilibrer la nutrition, accroître la salinité du substrat ou endommager les racines. Une plante limitée par le manque de lumière ou un sol détrempé ne sera pas nécessairement aidée par un engrais."},{"id":"nat-ja-08","category":"nature","subtheme":"Jardinage","difficulty":2,"type":"qcm","question":"Pourquoi acclimater progressivement des jeunes plants élevés à l’intérieur avant de les installer dehors ?","options":["Pour les habituer au soleil, au vent et aux variations de température","Pour provoquer obligatoirement une floraison immédiate","Pour rendre insensible au gel toute espèce tropicale","Pour supprimer tous les besoins d’arrosage pendant la reprise"],"correct":0,"explanation":"Un passage brutal peut provoquer des brûlures ou un stress important sur des tissus peu habitués. L’endurcissement consiste à augmenter progressivement l’exposition, sans placer des espèces sensibles au gel dans le froid."},{"id":"nat-ja-09","category":"nature","subtheme":"Jardinage","difficulty":3,"type":"qcm","question":"Pourquoi mesurer le pH d’un sol peut-il aider à comprendre une carence apparente ?","options":["Le pH modifie la disponibilité de certains éléments minéraux","Le pH indique directement la quantité totale de tous les éléments minéraux","Un pH de 7 signifie que le sol ne contient aucun nutriment","Un pH élevé garantit que toutes les plantes absorbent mieux tous les éléments"],"correct":0,"explanation":"Un élément peut être présent dans le sol tout en étant difficilement accessible à une plante dans certaines conditions de pH. Il faut donc distinguer quantité totale et disponibilité, avant d’ajouter un produit au hasard."},{"id":"nat-ja-10","category":"nature","subtheme":"Jardinage","difficulty":3,"type":"qcm","question":"Un engrais indique N-P-K : 8-4-6. Quelle lecture du premier nombre est correcte dans cette notation de teneurs massiques ?","options":["8 % d’azote, soit 8 g d’azote pour 100 g de produit","8 % de phosphore et aucun azote","8 g d’azote par kilogramme, soit 0,8 %","8 % d’azote uniquement dans l’eau d’arrosage finale, quelle que soit la dilution"],"correct":0,"explanation":"Le premier nombre indique la teneur massique en azote N du produit : 8 % donne 8 g pour 100 g. Attention, les nombres du phosphore et du potassium sont généralement exprimés en équivalents oxydes P₂O₅ et K₂O : les trois nombres ne se lisent pas comme trois masses d’éléments purs.","source":"https://www.notre-environnement.gouv.fr/themes/sante/la-pollution-des-sols-ressources/article/qu-est-ce-que-la-fertilisation-des-terres-agricoles"},{"id":"nat-ja-11","category":"nature","subtheme":"Jardinage","difficulty":3,"type":"qcm","question":"Dans un sol argileux qui infiltre lentement, que risque un arrosage apporté très vite en grande quantité ?","options":["Un ruissellement avant que l’eau pénètre suffisamment","Une infiltration nécessairement instantanée jusqu’aux racines profondes","Une aération durable de tous les pores par l’eau","Une diminution immédiate de la teneur en argile"],"correct":0,"explanation":"Lorsque le débit dépasse la capacité d’infiltration, une partie de l’eau peut partir en surface. Apporter l’eau plus lentement ou par étapes peut améliorer son entrée, en tenant compte de l’humidité déjà présente."},{"id":"nat-ja-12","category":"nature","subtheme":"Jardinage","difficulty":3,"type":"qcm","question":"Un semis reste très humide, mal aéré et des plantules s’affaissent au collet. Quel problème ces conditions peuvent-elles favoriser ?","options":["Une fonte des semis due à des agents pathogènes du substrat","Une simple dormance normale après la germination","Une lignification du collet qui fait normalement tomber la tige","Une vernalisation indispensable à tous les jeunes légumes"],"correct":0,"explanation":"La fonte des semis peut impliquer différents champignons ou organismes apparentés qui attaquent les jeunes plants. Une humidité excessive et une mauvaise aération peuvent favoriser le problème, sans permettre à elles seules d’identifier l’agent exact."},{"id":"nat-ja-13","category":"nature","subtheme":"Jardinage","difficulty":4,"type":"qcm","question":"Pourquoi apporter beaucoup de nitrates avant une période pluvieuse et sans culture en croissance peut-il être peu efficace ?","options":["Les nitrates sont toujours insolubles et restent fixés dans les pores superficiels","Les nitrates peuvent être entraînés avec l’eau au-delà des racines","La pluie empêche toute activité des micro-organismes du sol","Les plantes ne peuvent absorber l’azote que pendant une période sans pluie"],"correct":1,"explanation":"Les nitrates sont solubles et peuvent être lessivés quand l’eau traverse le sol. Synchroniser les apports avec les besoins et limiter les surplus aide à réduire ces pertes, selon les conditions du sol."},{"id":"nat-ja-14","category":"nature","subtheme":"Jardinage","difficulty":4,"type":"qcm","question":"Pourquoi incorporer une matière très riche en carbone et pauvre en azote peut-il provoquer une faim d’azote temporaire ?","options":["Les décomposeurs utilisent de l’azote minéral pour dégrader cette matière","Les plantes doivent absorber simultanément autant de carbone minéral que d’azote par leurs racines","Tout l’azote du sol est immédiatement volatilisé sous l’effet du carbone","La décomposition libère forcément tout l’azote organique dès le premier jour"],"correct":0,"explanation":"Les micro-organismes ont besoin d’azote pour se multiplier pendant la décomposition. Une partie de l’azote disponible peut être immobilisée dans leur biomasse, puis redevenir accessible plus tard.","source":"https://gard.chambres-agriculture.fr/fileadmin/user_upload/235_chambre_dagriculture_du_gard/Documents/Dechets_effluents_et_Sols_matieres_organique/guideMAFOR-vol1-crao2021.pdf"},{"id":"nat-ja-15","category":"nature","subtheme":"Jardinage","difficulty":4,"type":"qcm","question":"Sur un pommier greffé, quelle partie détermine principalement l’identité variétale des pommes portées par les branches greffées ?","options":["Le greffon","Le porte-greffe uniquement, quelle que soit la variété greffée","Un mélange génétique à parts égales entre greffon et porte-greffe","Le pollen reçu lors de la première année, qui transforme ensuite toutes les branches"],"correct":0,"explanation":"Les branches issues du greffon conservent l’identité génétique de cette variété. Le porte-greffe influence notamment la vigueur ou l’adaptation au sol, sans transformer le greffon en sa propre variété."},{"id":"nat-ja-16","category":"nature","subtheme":"Jardinage","difficulty":4,"type":"qcm","question":"Quelle démarche correspond le mieux à la protection intégrée des cultures ?","options":["Traiter systématiquement avant toute observation pour éviter tout seuil de nuisance","Observer, prévenir et combiner des moyens adaptés avant de décider d’une intervention","Utiliser exclusivement des produits naturels sans tenir compte de leur effet sur les auxiliaires","Intervenir avec la même méthode dès la présence d’un seul insecte, quelle que soit l’espèce"],"correct":1,"explanation":"La protection intégrée associe prévention, surveillance et moyens de gestion adaptés au problème observé. Elle cherche à limiter les interventions inutiles et à préserver les auxiliaires, plutôt qu’à rendre le jardin dépourvu d’organismes."},{"id":"nat-nu-01","category":"tech","subtheme":"Numérique","difficulty":1,"type":"qcm","question":"Combien de valeurs distinctes un bit peut-il représenter ?","options":["Deux","Huit","Dix","Deux cent cinquante-six"],"correct":0,"explanation":"Un bit représente deux états, conventionnellement notés 0 et 1. Plusieurs bits permettent de coder davantage de combinaisons : deux bits en donnent quatre."},{"id":"nat-nu-02","category":"tech","subtheme":"Numérique","difficulty":1,"type":"qcm","question":"Combien de bits contient un octet ?","options":["Deux","Quatre","Huit","Seize"],"correct":2,"explanation":"Un octet contient huit bits. Il peut donc représenter 2 puissance 8, soit 256 combinaisons différentes ; le nombre 8 ne désigne pas le nombre de valeurs possibles."},{"id":"nat-nu-03","category":"tech","subtheme":"Numérique","difficulty":1,"type":"qcm","question":"Renommer « photo.jpg » en « photo.png » suffit-il à convertir réellement son contenu au format PNG ?","options":["Oui, l’extension réécrit tous les pixels","Non, il faut une véritable opération de conversion","Oui, à condition de conserver le même dossier","Oui, mais seulement hors connexion"],"correct":1,"explanation":"L’extension aide les logiciels à reconnaître un fichier, mais la changer ne réencode pas ses données. Une conversion doit lire le format initial puis écrire un fichier conforme au format choisi."},{"id":"nat-nu-04","category":"tech","subtheme":"Numérique","difficulty":1,"type":"boolean","question":"Un logiciel peut fonctionner sans Internet si toutes ses fonctions et données nécessaires sont disponibles sur l’appareil.","options":["Vrai","Faux"],"correct":0,"explanation":"Un programme local peut utiliser directement les ressources présentes sur l’appareil. Les fonctions qui dépendent d’un serveur distant exigent en revanche une connexion ou une alternative locale prévue à cet effet."},{"id":"nat-nu-05","category":"tech","subtheme":"Numérique","difficulty":2,"type":"qcm","question":"Une image matricielle de 1 200 pixels sur 800 contient combien de pixels ?","options":["2 000","96 000","960 000","9 600 000"],"correct":2,"explanation":"On multiplie la largeur par la hauteur : 1 200 × 800 = 960 000 pixels. Cette quantité ne suffit pas à déterminer le poids du fichier, qui dépend aussi du codage et de la compression.","variant":"Une image possède 1 200 colonnes et 800 lignes de pixels. Quel est son nombre total de pixels ?"},{"id":"nat-nu-06","category":"tech","subtheme":"Numérique","difficulty":2,"type":"qcm","question":"Pourquoi un dessin vectoriel simple peut-il être agrandi sans présenter les mêmes blocs qu’une petite image matricielle ?","options":["Il décrit des formes géométriques recalculables à la taille souhaitée","Il stocke forcément davantage de pixels qu’une photographie","Il ajoute automatiquement des détails photographiques absents","Il conserve uniquement une miniature et la répète à l’infini"],"correct":0,"explanation":"Un format vectoriel décrit notamment des courbes et des formes que le moteur de rendu redessine. Cela conserve des contours nets, mais ne crée pas de nouveaux détails dans une photographie incorporée au dessin."},{"id":"nat-nu-07","category":"tech","subtheme":"Numérique","difficulty":2,"type":"qcm","question":"Que garantit une compression sans perte correctement décompressée ?","options":["Le fichier devient toujours dix fois plus petit","Les données originales sont retrouvées exactement","Tous les fichiers obtiennent la même taille","La qualité est améliorée au-delà de l’original"],"correct":1,"explanation":"Une compression sans perte permet de reconstruire les données initiales à l’identique. Son efficacité dépend du contenu ; des données déjà très comprimées peuvent gagner très peu de place."},{"id":"nat-nu-08","category":"tech","subtheme":"Numérique","difficulty":2,"type":"qcm","question":"Quel problème un encodage de caractères commun comme UTF-8 aide-t-il à résoudre ?","options":["Associer de façon cohérente des suites d’octets à des caractères","Donner obligatoirement la même police et la même taille à tous les textes","Chiffrer tous les messages sans clé","Traduire automatiquement toutes les langues vers le français"],"correct":0,"explanation":"Un encodage indique comment représenter les caractères par des octets. Lire un texte avec le mauvais encodage peut produire des caractères déformés, même si le fichier n’a pas été effacé."},{"id":"nat-nu-09","category":"tech","subtheme":"Numérique","difficulty":3,"type":"qcm","question":"Quel exemple combine deux facteurs d’authentification de natures différentes ?","options":["Un mot de passe et une seconde question secrète","Un mot de passe et la preuve de possession d’une clé de sécurité","Deux mots de passe mémorisés","Le même mot de passe saisi deux fois"],"correct":1,"explanation":"Un mot de passe relève de ce que l’on sait ; une clé de sécurité de ce que l’on possède. Ajouter un autre secret mémorisé ne crée pas, à lui seul, un facteur de nature différente.","source":"https://www.cnil.fr/fr/securite-utilisez-lauthentification-multifacteur-pour-vos-comptes-en-ligne"},{"id":"nat-nu-10","category":"tech","subtheme":"Numérique","difficulty":3,"type":"qcm","question":"Quelle information peut être présente dans les métadonnées d’une photo, même sans apparaître dans l’image ?","options":["Une date de prise de vue ou des coordonnées GPS si elles ont été enregistrées","Une certification automatique et infalsifiable du lieu de prise de vue","Une résolution toujours identique à la taille d’affichage choisie","La totalité des images précédentes simplement parce que le fichier est au format JPEG"],"correct":0,"explanation":"Des métadonnées peuvent décrire l’appareil, les réglages, la date ou parfois la position. Leur présence dépend de l’appareil et du traitement du fichier ; elles peuvent aussi être modifiées ou supprimées."},{"id":"nat-nu-11","category":"tech","subtheme":"Numérique","difficulty":3,"type":"qcm","question":"Pourquoi une simple synchronisation de dossier ne remplace-t-elle pas toujours une sauvegarde avec historique ?","options":["Une suppression ou une corruption peut être synchronisée sur les autres copies","La synchronisation conserve toujours un historique illimité","Une sauvegarde et une synchronisation sont nécessairement identiques dans tous les logiciels","Une copie distante empêche toute propagation des modifications locales"],"correct":0,"explanation":"La synchronisation vise à rapprocher les états des dossiers et peut donc propager une erreur. Une sauvegarde conservant des versions antérieures permet de revenir à un état connu, dans les limites de sa rétention.","source":"https://www.cnil.fr/fr/securite-sauvegarder"},{"id":"nat-nu-12","category":"tech","subtheme":"Numérique","difficulty":3,"type":"qcm","question":"Dans un enregistrement sonore numérique, que mesure la fréquence d’échantillonnage ?","options":["Le nombre de mesures du signal prises chaque seconde","Le nombre de haut-parleurs branchés","Le volume sonore maximal dans la pièce","La durée totale du fichier en secondes"],"correct":0,"explanation":"Une fréquence de 48 kHz correspond à 48 000 échantillons par seconde et par canal. Elle ne doit pas être confondue avec la profondeur en bits, qui concerne la précision de représentation de chaque échantillon."},{"id":"nat-nu-13","category":"tech","subtheme":"Numérique","difficulty":4,"type":"qcm","question":"Quelle différence sépare principalement un hachage cryptographique d’un chiffrement réversible ?","options":["Le chiffrement vise une restitution avec une clé, le hachage ne prévoit pas d’opération de déchiffrement","Le hachage est une compression sans perte qu’un décodeur peut toujours inverser","Le chiffrement garantit uniquement l’intégrité mais jamais la confidentialité","Le hachage permet une restitution directe du message dès que le sel est connu"],"correct":0,"explanation":"Le chiffrement sert notamment à protéger la confidentialité tout en permettant une restitution autorisée. Une empreinte de hachage sert à vérifier ou comparer des données ; on ne la « déchiffre » pas pour obtenir le message.","source":"https://www.cnil.fr/fr/securite-chiffrement-hachage-signature"},{"id":"nat-nu-14","category":"tech","subtheme":"Numérique","difficulty":4,"type":"qcm","question":"En UTF-8, combien d’octets encodent une valeur scalaire Unicode valide ?","options":["Toujours un","Toujours deux","De un à quatre","De huit à seize"],"correct":2,"explanation":"UTF-8 est de longueur variable : les valeurs ASCII occupent un octet et d’autres valeurs jusqu’à quatre. Un caractère perçu à l’écran, comme certains emoji combinés, peut toutefois comporter plusieurs valeurs Unicode.","source":"https://www.unicode.org/faq/utf_bom.html"},{"id":"nat-nu-15","category":"tech","subtheme":"Numérique","difficulty":4,"type":"qcm","question":"Un pixel RVB utilise 8 bits pour le rouge, 8 pour le vert et 8 pour le bleu, sans transparence. Combien de combinaisons numériques peut-il coder ?","options":["768","65 536","16 777 216","24 000 000"],"correct":2,"explanation":"Chaque composante possède 256 valeurs, donc 256 × 256 × 256 = 16 777 216 combinaisons. Le nombre de couleurs effectivement distinguées ou affichées dépend aussi de l’écran et de la perception."},{"id":"nat-nu-16","category":"tech","subtheme":"Numérique","difficulty":4,"type":"qcm","question":"Pourquoi ajouter un sel aléatoire propre à chaque mot de passe avant un hachage adapté au stockage de mots de passe ?","options":["Pour que des mots de passe identiques ne donnent pas systématiquement la même empreinte stockée","Pour permettre de déchiffrer le hachage sans clé","Pour remplacer le mot de passe par le nom public du site","Pour rendre un mot de passe court impossible à deviner"],"correct":0,"explanation":"Un sel distinct empêche notamment la réutilisation directe d’une même table précalculée contre de nombreux comptes. Il n’a pas besoin d’être secret et ne compense pas à lui seul un mot de passe faible ou un algorithme trop rapide.","source":"https://linc.cnil.fr/un-mot-de-passe-pour-les-gouverner-tous"},{"id":"sci-001","category":"math","subtheme":"Calcul","difficulty":1,"type":"qcm","question":"Combien vaut 15 % de 80 ?","options":["12","15","8","20"],"correct":0,"explanation":"Un pourcentage est une fraction sur cent : 80 × 15 / 100 = 12. On peut aussi additionner 10 % de 80, soit 8, et 5 %, soit 4."},{"id":"sci-002","category":"math","subtheme":"Calcul","difficulty":1,"type":"qcm","question":"Quelle fraction est égale à 0,75 ?","options":["3/4","1/4","2/3","3/5"],"correct":0,"explanation":"0,75 correspond à 75/100. En divisant le numérateur et le dénominateur par 25, on obtient 3/4."},{"id":"sci-003","category":"math","subtheme":"Calcul","difficulty":1,"type":"qcm","question":"Une recette pour 4 personnes demande 300 g de farine. Combien en faut-il pour 6 personnes, en conservant les proportions ?","options":["450 g","400 g","600 g","350 g"],"correct":0,"explanation":"Le nombre de personnes est multiplié par 6/4, soit 1,5. La farine suit le même facteur : 300 × 1,5 = 450 g."},{"id":"sci-004","category":"math","subtheme":"Calcul","difficulty":1,"type":"qcm","question":"Combien vaut 6 + 3 × 4 ?","options":["18","36","24","30"],"correct":0,"explanation":"On effectue la multiplication avant l’addition : 3 × 4 = 12, puis 6 + 12 = 18. Avec des parenthèses, (6 + 3) × 4 donnerait 36."},{"id":"sci-005","category":"math","subtheme":"Calcul","difficulty":2,"type":"qcm","question":"Un article à 50 € augmente de 20 %, puis baisse de 20 %. Quel est son prix final ?","options":["48 €","50 €","52 €","40 €"],"correct":0,"explanation":"Après l’augmentation, il coûte 60 €. La baisse s’applique à ce nouveau prix : 60 × 0,8 = 48 €. Deux variations opposées en pourcentage ne s’annulent donc pas en général.","variant":"Un magasin relève de 20 % le prix d’un produit vendu 50 €, puis applique une remise de 20 % sur ce nouveau prix. Combien le produit coûte-t-il finalement ?"},{"id":"sci-006","category":"math","subtheme":"Calcul","difficulty":2,"type":"qcm","question":"Quelle est la moyenne des nombres 4, 8, 9 et 11 ?","options":["8","8,5","7","9"],"correct":0,"explanation":"On additionne les quatre valeurs : 4 + 8 + 9 + 11 = 32. La moyenne est la somme divisée par l’effectif : 32/4 = 8."},{"id":"sci-007","category":"math","subtheme":"Calcul","difficulty":2,"type":"qcm","question":"Quelle est la solution de 3x + 5 = 20 ?","options":["5","15","25/3","3"],"correct":0,"explanation":"On soustrait 5 des deux côtés, puis on divise par 3 : 3x = 15, donc x = 5. La vérification donne 3 × 5 + 5 = 20."},{"id":"sci-008","category":"math","subtheme":"Calcul","difficulty":2,"type":"boolean","question":"Le carré de −3 vaut −9.","options":["Vrai","Faux"],"correct":1,"explanation":"Le carré de −3 est (−3) × (−3) = 9 : le produit de deux nombres négatifs est positif. En revanche, l’écriture −3² sans parenthèses signifie habituellement −(3²), soit −9."},{"id":"sci-009","category":"math","subtheme":"Calcul","difficulty":3,"type":"qcm","question":"Quel est le plus grand diviseur commun de 84 et 126 ?","options":["42","21","14","63"],"correct":0,"explanation":"126 = 84 + 42 et 84 = 2 × 42. Ainsi 42 divise les deux nombres et l’algorithme d’Euclide confirme que c’est leur plus grand diviseur commun."},{"id":"sci-010","category":"math","subtheme":"Calcul","difficulty":3,"type":"qcm","question":"Un capital de 1 000 € gagne 10 % par an, intérêts capitalisés. Quelle somme obtient-on après 2 ans ?","options":["1 210 €","1 200 €","1 100 €","1 220 €"],"correct":0,"explanation":"La première année donne 1 000 × 1,1 = 1 100 €. La seconde donne 1 100 × 1,1 = 1 210 €, car les premiers intérêts produisent aussi des intérêts."},{"id":"sci-011","category":"math","subtheme":"Calcul","difficulty":3,"type":"qcm","question":"Pour x non nul, quelle expression est égale à x³ × x⁻¹ ?","options":["x²","x⁻³","x⁴","1"],"correct":0,"explanation":"Pour un produit de puissances de même base, on additionne les exposants : 3 + (−1) = 2. La condition x ≠ 0 est nécessaire pour définir x⁻¹ = 1/x."},{"id":"sci-012","category":"math","subtheme":"Calcul","difficulty":3,"type":"qcm","question":"La médiane de 2, 3, 7, 10 et 100 est…","options":["7","24,4","10","3"],"correct":0,"explanation":"Une fois les cinq valeurs classées, la médiane est la troisième, donc 7. Contrairement à la moyenne, elle est peu sensible à la grandeur de la valeur extrême 100."},{"id":"sci-013","category":"math","subtheme":"Calcul","difficulty":4,"type":"qcm","question":"Quelle est la dérivée de f(x) = x³ − 2x ?","options":["3x² − 2","3x − 2","x² − 2","3x²"],"correct":0,"explanation":"La règle de dérivation de xⁿ donne n × xⁿ⁻¹. On dérive chaque terme : la dérivée de x³ est 3x² et celle de −2x est −2."},{"id":"sci-014","category":"math","subtheme":"Calcul","difficulty":4,"type":"qcm","question":"Quelle est la valeur de l’intégrale de 0 à 1 de 2x dx ?","options":["1","2","1/2","0"],"correct":0,"explanation":"Une primitive de 2x est x². On calcule sa valeur aux bornes : 1² − 0² = 1 ; géométriquement, c’est aussi l’aire d’un triangle de base 1 et de hauteur 2."},{"id":"sci-015","category":"math","subtheme":"Calcul","difficulty":4,"type":"qcm","question":"Combien de façons différentes peut-on choisir 2 personnes parmi 6, sans tenir compte de l’ordre ?","options":["15","30","12","36"],"correct":0,"explanation":"On compte 6 × 5 couples ordonnés, mais chaque paire a été comptée deux fois. Il reste donc 6 × 5 / 2 = 15 choix, soit le coefficient binomial « 6 parmi 2 »."},{"id":"sci-016","category":"math","subtheme":"Calcul","difficulty":4,"type":"qcm","question":"Quelle est la somme infinie 1 + 1/2 + 1/4 + 1/8 + … ?","options":["2","1,5","3","Elle diverge vers l’infini"],"correct":0,"explanation":"C’est une série géométrique de premier terme 1 et de raison 1/2. Comme la raison est de valeur absolue inférieure à 1, la somme vaut 1/(1 − 1/2) = 2."},{"id":"sci-017","category":"math","subtheme":"Logique","difficulty":1,"type":"qcm","question":"Tous les chats sont des mammifères. Mina est un chat. Que peut-on conclure avec certitude ?","options":["Mina est un mammifère","Tous les mammifères sont des chats","Mina est le seul chat","Mina est un chien"],"correct":0,"explanation":"La propriété « être un mammifère » s’applique à tous les chats, donc à Mina. On ne peut pas inverser la proposition : les chiens sont aussi des mammifères, sans être des chats."},{"id":"sci-018","category":"math","subtheme":"Logique","difficulty":1,"type":"qcm","question":"Une boîte contient 3 billes rouges et 2 bleues. Quelle est la probabilité de tirer une bleue au hasard ?","options":["2/5","3/5","1/2","2/3"],"correct":0,"explanation":"Il y a deux issues favorables parmi cinq billes équiprobables. La probabilité est donc 2/5, soit 40 %."},{"id":"sci-019","category":"math","subtheme":"Logique","difficulty":1,"type":"qcm","question":"Dans une file, Léa est devant Sami, et Sami est devant Inès. Qui est nécessairement devant Inès ?","options":["Léa et Sami","Seulement Sami","Seulement Léa","On ne peut pas le savoir"],"correct":0,"explanation":"L’ordre dans une file est transitif : si Léa précède Sami et que Sami précède Inès, Léa précède aussi Inès. Les deux personnes sont donc devant elle."},{"id":"sci-020","category":"math","subtheme":"Logique","difficulty":1,"type":"qcm","question":"Si une suite commence à 3 et ajoute toujours 4, quel est son cinquième terme ?","options":["19","15","20","23"],"correct":0,"explanation":"Les termes sont 3, 7, 11, 15 puis 19. Pour atteindre le cinquième terme, on ajoute quatre fois 4 au premier terme."},{"id":"sci-021","category":"math","subtheme":"Logique","difficulty":2,"type":"qcm","question":"On lance deux fois une pièce équilibrée, de façon indépendante. Quelle est la probabilité d’obtenir deux piles ?","options":["1/4","1/2","1/3","3/4"],"correct":0,"explanation":"Les quatre suites PP, PF, FP et FF ont la même probabilité. Une seule contient deux piles : sa probabilité est donc 1/4.","variant":"Une pièce équilibrée est lancée deux fois, les lancers étant indépendants. Avec quelle probabilité les deux résultats sont-ils « pile » ?"},{"id":"sci-022","category":"math","subtheme":"Logique","difficulty":2,"type":"qcm","question":"Quelle est la négation de « Tous les livres de cette étagère sont rouges » ?","options":["Au moins un livre de cette étagère n’est pas rouge","Aucun livre de cette étagère n’est rouge","Tous ces livres sont bleus","La moitié de ces livres est rouge"],"correct":0,"explanation":"Pour réfuter « tous », un seul contre-exemple suffit. Affirmer « aucun » serait plus fort et n’est pas la simple négation de la phrase."},{"id":"sci-023","category":"math","subtheme":"Logique","difficulty":2,"type":"boolean","question":"Un dé équilibré a donné six fois 6. Au prochain lancer indépendant, la probabilité d’un 6 reste 1/6.","options":["Vrai","Faux"],"correct":0,"explanation":"L’indépendance signifie que les résultats passés ne changent pas les probabilités du lancer suivant. L’idée qu’un autre résultat serait désormais « dû » est l’erreur du joueur."},{"id":"sci-024","category":"math","subtheme":"Logique","difficulty":2,"type":"qcm","question":"Si « P implique Q » est vraie et que Q est fausse, que peut-on déduire ?","options":["P est fausse","P est vraie","Q devient vraie","P et Q sont équivalentes"],"correct":0,"explanation":"C’est le raisonnement par contraposée : P entraînerait Q, donc l’absence de Q exclut P. En revanche, constater Q ne suffirait pas à prouver P."},{"id":"sci-025","category":"math","subtheme":"Logique","difficulty":3,"type":"qcm","question":"Une urne contient 3 boules rouges et 2 bleues. On tire deux boules sans remise. Quelle est la probabilité qu’elles soient toutes deux rouges ?","options":["3/10","9/25","1/2","3/5"],"correct":0,"explanation":"Le premier tirage rouge a une probabilité de 3/5. Il reste alors 2 rouges sur 4 boules : (3/5) × (2/4) = 3/10 ; le second tirage n’est pas indépendant du premier."},{"id":"sci-026","category":"math","subtheme":"Logique","difficulty":3,"type":"qcm","question":"Dans un groupe de 30 personnes, 18 aiment le thé, 16 le café et 8 les deux. Combien n’aiment ni thé ni café ?","options":["4","0","8","12"],"correct":0,"explanation":"L’union contient 18 + 16 − 8 = 26 personnes ; on retire l’intersection comptée deux fois. Il reste 30 − 26 = 4 personnes en dehors des deux ensembles."},{"id":"sci-027","category":"math","subtheme":"Logique","difficulty":3,"type":"qcm","question":"Dans un sac de chaussettes rouges, bleues ou noires, combien faut-il en prendre au minimum, sans regarder, pour garantir deux chaussettes de même couleur ?","options":["4","3","5","6"],"correct":0,"explanation":"Avec trois prises, on peut encore avoir une chaussette de chaque couleur. La quatrième doit partager la couleur d’une des trois : c’est le principe des tiroirs."},{"id":"sci-028","category":"math","subtheme":"Logique","difficulty":3,"type":"qcm","question":"Un test théorique est positif pour 90 % des cas d’une propriété présente chez 1 % des objets ; il est aussi positif pour 10 % des objets sans cette propriété. Parmi les positifs, quelle proportion possède la propriété ?","options":["Environ 8,3 %","90 %","50 %","Environ 99 %"],"correct":0,"explanation":"Sur 10 000 objets, 90 vrais positifs viennent des 100 objets concernés et 990 faux positifs des 9 900 autres. La proportion cherchée est 90/(90 + 990), soit environ 8,3 % : la fréquence de départ compte."},{"id":"sci-029","category":"math","subtheme":"Logique","difficulty":4,"type":"qcm","question":"Deux événements indépendants A et B ont chacun une probabilité de 1/2. Quelle est la probabilité de A ou B, au sens inclusif ?","options":["3/4","1","1/4","1/2"],"correct":0,"explanation":"On additionne P(A) et P(B), puis on retire l’intersection comptée deux fois. L’indépendance donne P(A et B) = 1/4, donc P(A ou B) = 1/2 + 1/2 − 1/4 = 3/4."},{"id":"sci-030","category":"math","subtheme":"Logique","difficulty":4,"type":"qcm","question":"Une proposition « P ou Q » est fausse exactement quand…","options":["P et Q sont toutes deux fausses","P et Q sont toutes deux vraies","P est vraie et Q est fausse","Au moins une des deux est vraie"],"correct":0,"explanation":"Le « ou » logique inclusif accepte une ou deux propositions vraies. Sa négation est donc « non P et non Q », conformément à une loi de De Morgan."},{"id":"sci-031","category":"math","subtheme":"Logique","difficulty":4,"type":"qcm","question":"On choisit au hasard une famille parmi celles ayant exactement deux enfants, chaque naissance étant modélisée par fille/garçon équiprobables et indépendants. Sachant qu’au moins un enfant est une fille, quelle est la probabilité de deux filles ?","options":["1/3","1/2","1/4","2/3"],"correct":0,"explanation":"Les couples ordonnés FF, FG et GF restent possibles après exclusion de GG, et ils sont équiprobables dans ce modèle. Un seul sur trois contient deux filles ; une autre procédure de sélection pourrait donner un autre résultat."},{"id":"sci-032","category":"math","subtheme":"Logique","difficulty":4,"type":"qcm","question":"Quel énoncé est équivalent à « Il existe un entier n tel que P(n) est fausse » ?","options":["Il n’est pas vrai que P(n) soit vraie pour tout entier n","P(n) est fausse pour tout entier n","P(n) est vraie pour un seul entier n","Aucun entier ne permet d’évaluer P(n)"],"correct":0,"explanation":"Nier une affirmation universelle produit une affirmation existentielle portant sur sa négation. Un seul entier contre-exemple suffit ; cela ne dit pas que tous les entiers sont des contre-exemples."},{"id":"sci-033","category":"math","subtheme":"Géométrie","difficulty":1,"type":"qcm","question":"Quelle est la somme des angles intérieurs d’un triangle dans le plan euclidien ?","options":["180°","90°","270°","360°"],"correct":0,"explanation":"Les trois angles intérieurs d’un triangle euclidien totalisent 180°. Cette propriété n’est pas universelle sur les surfaces courbes, comme une sphère."},{"id":"sci-034","category":"math","subtheme":"Géométrie","difficulty":1,"type":"qcm","question":"Quel est le périmètre d’un rectangle de longueur 8 cm et de largeur 3 cm ?","options":["22 cm","24 cm","11 cm","16 cm"],"correct":0,"explanation":"Le périmètre additionne les quatre côtés : 8 + 3 + 8 + 3 = 22 cm. Le produit 8 × 3 donne son aire, exprimée en cm²."},{"id":"sci-035","category":"math","subtheme":"Géométrie","difficulty":1,"type":"qcm","question":"Quelle est l’aire d’un carré de côté 5 cm ?","options":["25 cm²","20 cm²","10 cm²","125 cm²"],"correct":0,"explanation":"L’aire d’un carré est le côté multiplié par lui-même : 5 × 5 = 25 cm². Son périmètre, lui, serait 4 × 5 = 20 cm."},{"id":"sci-036","category":"math","subtheme":"Géométrie","difficulty":1,"type":"boolean","question":"Tout carré est aussi un rectangle.","options":["Vrai","Faux"],"correct":0,"explanation":"Un rectangle est un quadrilatère ayant quatre angles droits. Un carré satisfait cette définition et possède en plus quatre côtés de même longueur ; tout rectangle n’est donc pas un carré."},{"id":"sci-037","category":"math","subtheme":"Géométrie","difficulty":2,"type":"qcm","question":"Un triangle rectangle a des côtés perpendiculaires de 3 cm et 4 cm. Quelle est la longueur de son hypoténuse ?","options":["5 cm","7 cm","√7 cm","6 cm"],"correct":0,"explanation":"Le théorème de Pythagore donne c² = 3² + 4² = 25, donc c = 5 cm. L’hypoténuse est le côté opposé à l’angle droit.","variant":"Les deux côtés qui forment l’angle droit d’un triangle mesurent 3 cm et 4 cm. Combien mesure le côté opposé à cet angle droit ?"},{"id":"sci-038","category":"math","subtheme":"Géométrie","difficulty":2,"type":"qcm","question":"Quelle est l’aire d’un disque de rayon 3 cm ?","options":["9π cm²","6π cm²","3π cm²","18π cm²"],"correct":0,"explanation":"L’aire du disque vaut πr² : avec r = 3, cela donne 9π cm². L’expression 2πr = 6π cm correspond au périmètre de son cercle."},{"id":"sci-039","category":"math","subtheme":"Géométrie","difficulty":2,"type":"qcm","question":"Un cube a une arête de 4 cm. Quel est son volume ?","options":["64 cm³","16 cm³","48 cm³","96 cm³"],"correct":0,"explanation":"Le volume d’un cube est le cube de son arête : 4 × 4 × 4 = 64 cm³. Les 96 cm² que donnerait 6 × 4² représentent son aire totale."},{"id":"sci-040","category":"math","subtheme":"Géométrie","difficulty":2,"type":"qcm","question":"Sur une carte au 1:25 000, une distance de 4 cm correspond à…","options":["1 km sur le terrain","100 m sur le terrain","10 km sur le terrain","250 m sur le terrain"],"correct":0,"explanation":"Chaque centimètre représente 25 000 cm, soit 250 m. Quatre centimètres représentent donc 1 000 m, autrement dit 1 km."},{"id":"sci-041","category":"math","subtheme":"Géométrie","difficulty":3,"type":"qcm","question":"Un agrandissement multiplie toutes les longueurs d’une figure par 3. Par combien son aire est-elle multipliée ?","options":["9","3","6","27"],"correct":0,"explanation":"Une aire dépend du produit de deux longueurs, chacune multipliée par 3 : le facteur est donc 3² = 9. Pour le volume d’un solide, le facteur serait 3³ = 27."},{"id":"sci-042","category":"math","subtheme":"Géométrie","difficulty":3,"type":"qcm","question":"Quelle est la distance entre A(1 ; 2) et B(4 ; 6) dans un repère orthonormé ?","options":["5","7","√7","25"],"correct":0,"explanation":"Les écarts de coordonnées sont 3 et 4. Pythagore donne une distance √(3² + 4²) = √25 = 5."},{"id":"sci-043","category":"math","subtheme":"Géométrie","difficulty":3,"type":"qcm","question":"Quelle est la somme des angles intérieurs d’un hexagone convexe ?","options":["720°","540°","900°","1 080°"],"correct":0,"explanation":"Un polygone convexe à n côtés se découpe en n − 2 triangles depuis un sommet. Pour n = 6, la somme est (6 − 2) × 180° = 720°."},{"id":"sci-044","category":"math","subtheme":"Géométrie","difficulty":3,"type":"qcm","question":"Deux vecteurs non nuls ont un produit scalaire nul. Dans un plan euclidien, ils sont…","options":["Perpendiculaires","De même sens","De sens opposés","De même longueur"],"correct":0,"explanation":"Le produit scalaire vaut le produit des normes multiplié par le cosinus de l’angle. S’il est nul avec des normes non nulles, le cosinus vaut zéro et l’angle est droit."},{"id":"sci-045","category":"math","subtheme":"Géométrie","difficulty":4,"type":"qcm","question":"Quelle est l’aire d’un triangle dont les côtés mesurent 13, 14 et 15 unités ?","options":["84 unités²","91 unités²","105 unités²","42 unités²"],"correct":0,"explanation":"La formule de Héron utilise le demi-périmètre s = 21. L’aire vaut √[21 × (21 − 13) × (21 − 14) × (21 − 15)] = √7056 = 84."},{"id":"sci-046","category":"math","subtheme":"Géométrie","difficulty":4,"type":"qcm","question":"Quel est le volume d’une sphère de rayon r ?","options":["4πr³/3","4πr²","πr³","2πr³/3"],"correct":0,"explanation":"Le volume d’une sphère est 4πr³/3. L’expression 4πr² est son aire de surface ; l’exposant 3 signale une grandeur de volume."},{"id":"sci-047","category":"math","subtheme":"Géométrie","difficulty":4,"type":"qcm","question":"Dans le plan, une rotation de 90° autour de l’origine transforme (x ; y) en (−y ; x). Quel est le sens de cette rotation ?","options":["Antihoraire","Horaire","Elle dépend du point","Ce n’est pas une rotation"],"correct":0,"explanation":"Le point (1 ; 0) devient (0 ; 1), ce qui est un quart de tour dans le sens antihoraire du repère usuel. Le quart de tour horaire donnerait (y ; −x)."},{"id":"sci-048","category":"math","subtheme":"Géométrie","difficulty":4,"type":"qcm","question":"Une transformation linéaire du plan a pour matrice diagonale diag(2, 3). Par quel facteur multiplie-t-elle les aires ?","options":["6","5","√13","9"],"correct":0,"explanation":"Elle multiplie une direction par 2 et l’autre par 3 : l’aire d’un rectangle devient donc six fois plus grande. En général, le facteur d’aire est la valeur absolue du déterminant, ici |2 × 3| = 6."},{"id":"sci-049","category":"science","subtheme":"Corps humain","difficulty":1,"type":"qcm","question":"Quel organe propulse le sang dans les vaisseaux ?","options":["Le cœur","Le foie","Le pancréas","La rate"],"correct":0,"explanation":"Le cœur est un muscle qui agit comme une pompe et entretient la circulation sanguine. Le foie transforme et stocke diverses substances, mais il ne remplit pas cette fonction de propulsion."},{"id":"sci-050","category":"science","subtheme":"Corps humain","difficulty":1,"type":"qcm","question":"Où se font principalement les échanges d’oxygène et de dioxyde de carbone dans les poumons ?","options":["Dans les alvéoles","Dans la trachée","Dans le larynx","Dans les bronches principales"],"correct":0,"explanation":"Les alvéoles offrent une grande surface au contact de capillaires aux parois fines. L’oxygène diffuse vers le sang et le dioxyde de carbone vers l’air alvéolaire ; les grosses voies respiratoires transportent surtout l’air."},{"id":"sci-051","category":"science","subtheme":"Corps humain","difficulty":1,"type":"qcm","question":"Quelle structure protège principalement le cerveau contre les chocs directs ?","options":["Le crâne","Le sternum","Le bassin","Les omoplates"],"correct":0,"explanation":"Les os du crâne forment une enveloppe rigide autour du cerveau. Les méninges et le liquide cérébrospinal contribuent aussi à sa protection."},{"id":"sci-052","category":"science","subtheme":"Corps humain","difficulty":1,"type":"qcm","question":"Quel est le rôle principal de l’hémoglobine des globules rouges ?","options":["Transporter l’oxygène","Fabriquer des anticorps","Digérer les protéines","Former les os"],"correct":0,"explanation":"L’hémoglobine peut fixer de l’oxygène au niveau des poumons puis en libérer dans les tissus. Sa présence explique en grande partie la couleur rouge du sang."},{"id":"sci-053","category":"science","subtheme":"Corps humain","difficulty":2,"type":"qcm","question":"Dans quelle partie du tube digestif la plupart des nutriments sont-ils absorbés ?","options":["L’intestin grêle","L’œsophage","L’estomac","Le rectum"],"correct":0,"explanation":"L’intestin grêle possède de nombreux replis et villosités qui augmentent sa surface d’absorption. L’estomac contribue à la digestion, mais n’assure pas l’essentiel de l’absorption des nutriments.","variant":"Après leur digestion, dans quelle région du tube digestif la majorité des nutriments passe-t-elle dans le milieu intérieur de l’organisme ?"},{"id":"sci-054","category":"science","subtheme":"Corps humain","difficulty":2,"type":"qcm","question":"Quel organe produit l’insuline ?","options":["Le pancréas","La thyroïde","La rate","La vésicule biliaire"],"correct":0,"explanation":"Les cellules bêta des îlots du pancréas sécrètent l’insuline. Cette hormone aide à réguler la concentration de glucose sanguin, notamment en favorisant son utilisation et son stockage."},{"id":"sci-055","category":"science","subtheme":"Corps humain","difficulty":2,"type":"boolean","question":"Une artère est définie comme un vaisseau qui transporte toujours du sang riche en oxygène.","options":["Vrai","Faux"],"correct":1,"explanation":"Une artère conduit le sang depuis le cœur, quelle que soit sa teneur en oxygène. Les artères pulmonaires transportent ainsi vers les poumons un sang relativement pauvre en oxygène."},{"id":"sci-056","category":"science","subtheme":"Corps humain","difficulty":2,"type":"qcm","question":"Quel rôle les reins assurent-ils notamment ?","options":["Éliminer des déchets et régler l’équilibre en eau et sels","Produire la bile nécessaire à la digestion","Pomper le sang vers les poumons","Absorber la majeure partie des nutriments"],"correct":0,"explanation":"Les reins filtrent le sang puis ajustent ce qui est réabsorbé ou éliminé dans l’urine. Ils contribuent ainsi à maintenir l’équilibre de l’eau et de divers sels minéraux.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidneys-how-they-work"},{"id":"sci-057","category":"science","subtheme":"Corps humain","difficulty":3,"type":"qcm","question":"Quelle molécule est l’intermédiaire énergétique directement utilisé dans de nombreuses réactions cellulaires ?","options":["L’ATP","L’ADN","Le collagène","La cellulose"],"correct":0,"explanation":"L’adénosine triphosphate, ou ATP, couple des réactions libérant de l’énergie à des processus qui en consomment. Ce n’est pas une réserve à long terme comparable aux graisses : l’ATP est continuellement renouvelé."},{"id":"sci-058","category":"science","subtheme":"Corps humain","difficulty":3,"type":"qcm","question":"Quelle association entre une base de l’ADN et sa base complémentaire est correcte ?","options":["Adénine — thymine","Adénine — cytosine","Guanine — thymine","Cytosine — thymine"],"correct":0,"explanation":"Dans l’ADN double brin, l’adénine s’apparie à la thymine et la guanine à la cytosine. Ces appariements permettent à chaque brin de servir de modèle lors de la copie."},{"id":"sci-059","category":"science","subtheme":"Corps humain","difficulty":3,"type":"qcm","question":"Quel élément caractérise l’immunité adaptative ?","options":["Une reconnaissance spécifique pouvant laisser une mémoire","L’absence de cellules spécialisées","Une action limitée à la peau","L’impossibilité de distinguer des antigènes"],"correct":0,"explanation":"Les lymphocytes B et T possèdent des récepteurs spécifiques et peuvent former des populations mémoire après une réponse. L’immunité innée utilise d’autres mécanismes de reconnaissance, plus généraux."},{"id":"sci-060","category":"science","subtheme":"Corps humain","difficulty":3,"type":"qcm","question":"Dans un néphron, quelle structure réalise la première filtration du sang ?","options":["Le glomérule","L’uretère","La vessie","L’urètre"],"correct":0,"explanation":"Le glomérule est un bouquet de capillaires dont une partie du plasma est filtrée vers la capsule qui l’entoure. Le tubule modifie ensuite ce filtrat ; les uretères et la vessie transportent ou stockent l’urine.","source":"https://www.niddk.nih.gov/health-information/kidney-disease/kidneys-how-they-work"},{"id":"sci-061","category":"science","subtheme":"Corps humain","difficulty":4,"type":"qcm","question":"Dans un axone myélinisé, pourquoi parle-t-on de conduction saltatoire ?","options":["Le potentiel d’action est régénéré surtout aux nœuds de Ranvier","Des neurotransmetteurs sont libérés à chaque nœud entre deux neurones","Les échanges ioniques sont uniformes sur toute la membrane myélinisée","Le potentiel d’action est régénéré uniquement dans le corps cellulaire"],"correct":0,"explanation":"La myéline isole des portions de l’axone, tandis que les nœuds de Ranvier concentrent les échanges ioniques nécessaires à la régénération du potentiel d’action. Cette organisation accélère sa propagation sans qu’un objet matériel « saute » le long du nerf.","source":"https://www.ncbi.nlm.nih.gov/books/NBK538143/"},{"id":"sci-062","category":"science","subtheme":"Corps humain","difficulty":4,"type":"qcm","question":"Au début de la phase ascendante d’un potentiel d’action neuronal typique, quel mouvement ionique domine ?","options":["L’entrée de sodium dans la cellule","La sortie de potassium de la cellule","L’entrée de chlorure dans la cellule","La sortie de sodium de la cellule"],"correct":0,"explanation":"L’ouverture de canaux sodiques dépendants du voltage permet une entrée rapide de Na⁺ et dépolarise la membrane. La sortie de potassium contribue ensuite à la repolarisation.","source":"https://www.ncbi.nlm.nih.gov/books/NBK538143/"},{"id":"sci-063","category":"science","subtheme":"Corps humain","difficulty":4,"type":"boolean","question":"Lors de la contraction d’un muscle squelettique, les filaments d’actine et de myosine raccourcissent eux-mêmes.","options":["Vrai","Faux"],"correct":1,"explanation":"Les filaments glissent les uns par rapport aux autres grâce aux interactions entre actine et myosine. Le sarcomère se raccourcit, tandis que la longueur des filaments reste approximativement constante."},{"id":"sci-064","category":"science","subtheme":"Corps humain","difficulty":4,"type":"qcm","question":"Quelle action déclenche généralement l’exocytose des neurotransmetteurs dans une terminaison présynaptique chimique ?","options":["L’entrée de calcium après l’arrivée du potentiel d’action","La fixation préalable du neurotransmetteur sur la cellule postsynaptique","La dégradation de toutes les vésicules par le noyau","La seule ouverture des canaux de fuite du potassium"],"correct":0,"explanation":"L’arrivée du potentiel d’action ouvre des canaux calciques dépendants du voltage. L’augmentation locale de Ca²⁺ active la fusion de vésicules avec la membrane et la libération de neurotransmetteurs."},{"id":"sci-065","category":"science","subtheme":"Physique et chimie","difficulty":1,"type":"qcm","question":"Quel changement d’état transforme un liquide en gaz ?","options":["La vaporisation","La fusion","La solidification","La condensation liquide"],"correct":0,"explanation":"La vaporisation comprend l’évaporation en surface et l’ébullition dans le liquide. La fusion transforme au contraire un solide en liquide."},{"id":"sci-066","category":"science","subtheme":"Physique et chimie","difficulty":1,"type":"qcm","question":"Quel symbole chimique désigne l’oxygène ?","options":["O","Ox","Og","Au"],"correct":0,"explanation":"Le symbole de l’élément oxygène est O. O₂ désigne la molécule de dioxygène, tandis que Au est le symbole de l’or et Og celui de l’oganesson."},{"id":"sci-067","category":"science","subtheme":"Physique et chimie","difficulty":1,"type":"qcm","question":"Quelle grandeur se mesure en newtons ?","options":["La force","L’énergie","La puissance","La température"],"correct":0,"explanation":"Le newton est l’unité de force du Système international. Le joule mesure une énergie, le watt une puissance et le kelvin une température."},{"id":"sci-068","category":"science","subtheme":"Physique et chimie","difficulty":1,"type":"boolean","question":"Un aimant attire tous les métaux de la même façon.","options":["Vrai","Faux"],"correct":1,"explanation":"Le fer, le nickel et le cobalt présentent notamment un fort comportement ferromagnétique dans des conditions usuelles. Le cuivre ou l’aluminium ne sont pas attirés comme un clou en fer par un aimant ordinaire."},{"id":"sci-069","category":"science","subtheme":"Physique et chimie","difficulty":2,"type":"qcm","question":"Deux objets ont le même volume. Celui qui a la plus grande masse a aussi…","options":["La plus grande masse volumique","La plus petite masse volumique","La même masse volumique","Nécessairement la plus haute température"],"correct":0,"explanation":"La masse volumique est la masse divisée par le volume. À volume égal, augmenter la masse augmente donc la masse volumique ; cela ne permet pas de déduire la température.","variant":"On compare deux échantillons de volume identique. Quelle propriété possède celui dont la masse est la plus élevée ?"},{"id":"sci-070","category":"science","subtheme":"Physique et chimie","difficulty":2,"type":"qcm","question":"Dans un circuit, quelle relation exprime la loi d’Ohm pour une résistance ohmique ?","options":["U = R × I","U = R / I","I = R × U","R = U × I"],"correct":0,"explanation":"La tension U aux bornes d’une résistance ohmique est proportionnelle au courant I qui la traverse : U = RI. Les unités correspondantes sont le volt, l’ohm et l’ampère."},{"id":"sci-071","category":"science","subtheme":"Physique et chimie","difficulty":2,"type":"qcm","question":"Quel est le numéro atomique d’un élément ?","options":["Son nombre de protons","Son nombre de neutrons","Sa masse en grammes","Son nombre de liaisons possibles"],"correct":0,"explanation":"Le nombre de protons du noyau définit l’élément chimique. Des isotopes d’un même élément ont le même numéro atomique mais des nombres de neutrons différents."},{"id":"sci-072","category":"science","subtheme":"Physique et chimie","difficulty":2,"type":"qcm","question":"Pourquoi un son ne se propage-t-il pas dans un vide parfait ?","options":["Il a besoin d’un milieu matériel pour transmettre des vibrations","Il manque nécessairement de lumière","Le vide est toujours trop froid","La gravité y est toujours nulle"],"correct":0,"explanation":"Le son est une onde mécanique qui se transmet par les interactions entre les constituants d’un milieu. La lumière est une onde électromagnétique et peut, elle, se propager dans le vide."},{"id":"sci-073","category":"science","subtheme":"Physique et chimie","difficulty":3,"type":"qcm","question":"Dans un gaz parfait à température constante, que devient la pression si l’on divise le volume par deux, à quantité de gaz constante ?","options":["Elle double","Elle est divisée par deux","Elle reste constante","Elle quadruple"],"correct":0,"explanation":"La loi de Boyle-Mariotte donne PV = constante lorsque la température et la quantité de matière restent fixes. Si le volume est divisé par deux, la pression doit être multipliée par deux."},{"id":"sci-074","category":"science","subtheme":"Physique et chimie","difficulty":3,"type":"qcm","question":"Deux isotopes du carbone se distinguent principalement par leur nombre…","options":["De neutrons","De protons","De couches électroniques obligatoires","De symboles chimiques"],"correct":0,"explanation":"Tous les atomes de carbone ont six protons. Le carbone 12 et le carbone 14 possèdent respectivement six et huit neutrons, ce qui change leur masse et peut changer leur stabilité nucléaire."},{"id":"sci-075","category":"science","subtheme":"Physique et chimie","difficulty":3,"type":"qcm","question":"Dans une solution aqueuse diluée, passer de pH 3 à pH 2 correspond approximativement à une concentration en ions hydronium…","options":["Dix fois plus grande","Deux fois plus grande","Dix fois plus petite","Inchangée"],"correct":0,"explanation":"L’échelle de pH est logarithmique : une diminution d’une unité correspond approximativement à une multiplication par dix de la concentration en H₃O⁺ en solution diluée. Un écart de pH ne s’interprète donc pas comme une simple différence linéaire."},{"id":"sci-076","category":"science","subtheme":"Physique et chimie","difficulty":3,"type":"boolean","question":"Dans un système isolé, l’énergie totale se conserve, même si elle change de forme.","options":["Vrai","Faux"],"correct":0,"explanation":"La conservation de l’énergie porte sur son total. De l’énergie mécanique peut devenir de l’énergie interne par frottement sans disparaître ; sa disponibilité pour produire du travail peut cependant diminuer."},{"id":"sci-077","category":"science","subtheme":"Physique et chimie","difficulty":4,"type":"qcm","question":"Pour une onde lumineuse dans le vide, si la fréquence double, que devient la longueur d’onde ?","options":["Elle est divisée par deux","Elle double","Elle quadruple","Elle reste constante"],"correct":0,"explanation":"Dans le vide, c = λf et la vitesse c est constante. Doubler la fréquence f impose donc de diviser la longueur d’onde λ par deux."},{"id":"sci-078","category":"science","subtheme":"Physique et chimie","difficulty":4,"type":"qcm","question":"Quel phénomène explique qu’un photon puisse arracher un électron à un métal seulement au-delà d’une fréquence seuil ?","options":["L’effet photoélectrique","La diffraction purement géométrique","La poussée d’Archimède","La convection thermique"],"correct":0,"explanation":"Un photon porte une énergie E = hf qui doit atteindre le travail d’extraction du métal. Augmenter seulement l’intensité d’une lumière de fréquence trop basse ne remplace pas cette énergie minimale par photon dans ce modèle."},{"id":"sci-079","category":"science","subtheme":"Physique et chimie","difficulty":4,"type":"qcm","question":"Une désintégration bêta moins transforme, dans le noyau…","options":["Un neutron en proton, avec émission d’un électron et d’un antineutrino","Un proton en neutron, sans autre particule","Deux protons en un photon","Un électron en neutron"],"correct":0,"explanation":"Lors d’une désintégration β⁻, un neutron devient un proton et émet un électron ainsi qu’un antineutrino électronique. Le nombre de nucléons reste constant et le numéro atomique augmente de un."},{"id":"sci-080","category":"science","subtheme":"Physique et chimie","difficulty":4,"type":"qcm","question":"Pour un mouvement circulaire uniforme de rayon r et de vitesse v, quelle est la norme de l’accélération ?","options":["v²/r","v/r²","v × r","Zéro"],"correct":0,"explanation":"Même si la norme de la vitesse reste constante, sa direction change : il existe une accélération centripète de norme v²/r. Elle est dirigée vers le centre de la trajectoire."},{"id":"sci-081","category":"science","subtheme":"Astronomie","difficulty":1,"type":"qcm","question":"Quelle étoile est au centre du Système solaire ?","options":["Le Soleil","Sirius","Polaris","Véga"],"correct":0,"explanation":"La Terre et les autres planètes du Système solaire gravitent autour du Soleil. Sirius, Polaris et Véga sont d’autres étoiles, beaucoup plus éloignées."},{"id":"sci-082","category":"science","subtheme":"Astronomie","difficulty":1,"type":"qcm","question":"Pourquoi voit-on la Lune briller ?","options":["Elle réfléchit une partie de la lumière du Soleil","Elle produit principalement sa propre lumière visible","Elle reflète seulement la lumière des villes","Son atmosphère brûle en permanence"],"correct":0,"explanation":"La surface lunaire diffuse vers nous une partie de la lumière solaire qu’elle reçoit. Les phases correspondent à la portion éclairée que nous voyons, et non à une extinction périodique de la Lune."},{"id":"sci-083","category":"science","subtheme":"Astronomie","difficulty":1,"type":"qcm","question":"Quelle planète est célèbre pour son vaste système d’anneaux facilement visible au télescope ?","options":["Saturne","Mars","Vénus","Mercure"],"correct":0,"explanation":"Saturne possède un système d’anneaux particulièrement étendu et lumineux. D’autres planètes géantes ont aussi des anneaux, mais beaucoup plus difficiles à observer."},{"id":"sci-084","category":"science","subtheme":"Astronomie","difficulty":1,"type":"boolean","question":"Une année-lumière est une unité de durée.","options":["Vrai","Faux"],"correct":1,"explanation":"Une année-lumière mesure une distance : celle parcourue par la lumière dans le vide en une année. Son nom contient une durée, mais cette durée sert à définir la distance."},{"id":"sci-085","category":"science","subtheme":"Astronomie","difficulty":2,"type":"qcm","question":"Quelle est la cause principale des saisons sur Terre ?","options":["L’inclinaison de l’axe terrestre au cours de l’orbite","La variation quotidienne de la taille du Soleil","L’ombre de la Lune sur les continents","L’arrêt de la rotation terrestre en hiver"],"correct":0,"explanation":"L’axe terrestre est incliné par rapport au plan de l’orbite. Chaque hémisphère reçoit ainsi au fil de l’année un éclairage plus ou moins direct et des journées plus ou moins longues ; la distance au Soleil n’explique pas l’opposition des saisons entre hémisphères.","variant":"Quel mécanisme explique principalement l’alternance de l’été et de l’hiver au cours d’une année terrestre ?"},{"id":"sci-086","category":"science","subtheme":"Astronomie","difficulty":2,"type":"qcm","question":"Lors d’une éclipse solaire observée depuis la Terre, quel objet se trouve entre nous et le Soleil ?","options":["La Lune","Mars","La Terre","Jupiter"],"correct":0,"explanation":"La Lune passe devant le Soleil et projette son ombre sur une partie de la Terre. Lors d’une éclipse lunaire, c’est la Terre qui s’interpose entre le Soleil et la Lune."},{"id":"sci-087","category":"science","subtheme":"Astronomie","difficulty":2,"type":"qcm","question":"Dans quelle galaxie se trouve le Système solaire ?","options":["La Voie lactée","Andromède","Le Grand Nuage de Magellan","La galaxie du Triangle"],"correct":0,"explanation":"Le Système solaire appartient à la Voie lactée, une galaxie contenant un très grand nombre d’étoiles. Andromède et la galaxie du Triangle sont d’autres galaxies du Groupe local."},{"id":"sci-088","category":"science","subtheme":"Astronomie","difficulty":2,"type":"qcm","question":"Quelle source d’énergie alimente principalement le Soleil actuellement ?","options":["La fusion de noyaux d’hydrogène en hélium","La combustion de charbon","La fission d’uranium principalement","Le frottement des planètes sur sa surface"],"correct":0,"explanation":"Dans le cœur solaire, des réactions de fusion convertissent globalement de l’hydrogène en hélium. Une petite différence de masse est libérée sous forme d’énergie selon E = mc²."},{"id":"sci-089","category":"science","subtheme":"Astronomie","difficulty":3,"type":"qcm","question":"Quelle interprétation planétaire cherche-t-on à confirmer avec des baisses périodiques de luminosité stellaire dans la méthode des transits ?","options":["Le passage d’une planète devant son étoile","Le déplacement radial de l’étoile mesuré directement par effet Doppler","L’émission thermique de la planète mesurée sans lumière stellaire","La déformation de l’image d’une galaxie derrière la planète"],"correct":0,"explanation":"Une planète passant devant son étoile peut en masquer une petite partie à intervalles réguliers. D’autres causes de variation existent : la répétition et des contrôles supplémentaires aident à confirmer l’interprétation.","source":"https://science.nasa.gov/exoplanets/whats-a-transit/"},{"id":"sci-090","category":"science","subtheme":"Astronomie","difficulty":3,"type":"qcm","question":"Dans une orbite elliptique autour du Soleil, comment varie la vitesse d’une planète ?","options":["Elle est plus grande près du Soleil","Elle est plus faible près du Soleil","Elle est exactement constante","Elle est nulle à chaque extrémité"],"correct":0,"explanation":"La deuxième loi de Kepler indique que le rayon Soleil-planète balaie des aires égales en des temps égaux. La planète doit donc se déplacer plus vite près du périhélie que près de l’aphélie."},{"id":"sci-091","category":"science","subtheme":"Astronomie","difficulty":3,"type":"qcm","question":"Quelle est la nature d’une naine blanche ?","options":["Un reste stellaire dense soutenu notamment par la dégénérescence des électrons","Une planète composée de glace","Une jeune étoile qui vient toujours de naître","Un nuage diffus formant seulement de nouvelles étoiles"],"correct":0,"explanation":"Une naine blanche est le cœur résiduel d’une étoile ayant perdu ses couches externes. Elle ne maintient plus une fusion centrale comme le Soleil et se refroidit progressivement.","source":"https://science.nasa.gov/universe/stars/types/"},{"id":"sci-092","category":"science","subtheme":"Astronomie","difficulty":3,"type":"boolean","question":"Le décalage cosmologique vers le rouge correspond à un allongement des longueurs d’onde lié à l’expansion de l’Univers.","options":["Vrai","Faux"],"correct":0,"explanation":"Pendant que la lumière voyage, l’expansion de l’espace allonge ses longueurs d’onde. Il existe aussi des décalages vers le rouge dus au mouvement relatif ou à la gravitation, qu’il faut distinguer selon le contexte.","source":"https://science.nasa.gov/universe/glossary/"},{"id":"sci-093","category":"science","subtheme":"Astronomie","difficulty":4,"type":"qcm","question":"La parallaxe annuelle d’une étoile est de 0,1 seconde d’arc. À quelle distance se trouve-t-elle approximativement ?","options":["10 parsecs","0,1 parsec","1 parsec","100 parsecs"],"correct":0,"explanation":"La distance en parsecs est l’inverse de la parallaxe en secondes d’arc : d = 1/p. Avec p = 0,1, on obtient 10 parsecs, soit environ 32,6 années-lumière."},{"id":"sci-094","category":"science","subtheme":"Astronomie","difficulty":4,"type":"qcm","question":"Pourquoi les pulsars présentent-ils souvent des impulsions radio périodiques ?","options":["La rotation d’une étoile à neutrons fait balayer un faisceau vers nous","Les pulsations radiales d’une géante rouge changent sa taille","Des éclipses par un compagnon coupent une émission autrement constante","Les oscillations thermiques d’un disque protoplanétaire créent ces impulsions"],"correct":0,"explanation":"Un pulsar est une étoile à neutrons dont des émissions sont concentrées selon certaines directions. Si la rotation fait passer le faisceau dans notre ligne de visée, on observe des impulsions, comme avec un phare.","source":"https://science.nasa.gov/universe/stars/types/"},{"id":"sci-095","category":"science","subtheme":"Astronomie","difficulty":4,"type":"qcm","question":"Pour une planète de masse négligeable autour d’une même étoile, que dit la troisième loi de Kepler ?","options":["T² est proportionnel à a³","T est proportionnel à a³","T³ est proportionnel à a²","T² est inversement proportionnel à a"],"correct":0,"explanation":"Le carré de la période orbitale T est proportionnel au cube du demi-grand axe a. Une orbite de demi-grand axe quatre fois plus grand a donc une période huit fois plus longue dans ce cadre."},{"id":"sci-096","category":"science","subtheme":"Astronomie","difficulty":4,"type":"qcm","question":"À rayon stellaire connu et en négligeant l’assombrissement du bord, qu’estime la profondeur relative d’un transit planétaire ?","options":["Le carré du rapport rayon de la planète / rayon de l’étoile","Directement la masse exacte de la planète","Directement la température du noyau planétaire","Le nombre exact de lunes de la planète"],"correct":0,"explanation":"La diminution relative du flux est approximativement le rapport des surfaces apparentes, soit (Rp/Rétoile)². La masse nécessite d’autres informations ; une planète deux fois plus grande masque environ quatre fois plus de lumière.","source":"https://www.herts.ac.uk/h2h/exoplanet-discover/methods-of-detection/transits"},{"id":"sci-097","category":"tech","subtheme":"Programmation","difficulty":1,"type":"qcm","question":"À quoi sert principalement une variable dans un programme ?","options":["À nommer une valeur utilisable par le programme","À dessiner obligatoirement une fenêtre","À supprimer le besoin de mémoire","À garantir qu’un programme est correct"],"correct":0,"explanation":"Une variable permet de retrouver une valeur au moyen d’un nom et, selon les règles du langage, de la remplacer. Le nom facilite la lecture du programme, sans garantir que son algorithme soit correct."},{"id":"sci-098","category":"tech","subtheme":"Programmation","difficulty":1,"type":"qcm","question":"Quelle structure répète une action tant qu’une condition le permet ?","options":["Une boucle","Un commentaire","Une constante numérique","Une chaîne de caractères"],"correct":0,"explanation":"Une boucle répète un bloc selon une condition ou une collection à parcourir. Un commentaire sert à documenter le code et n’exécute aucune répétition par lui-même."},{"id":"sci-099","category":"tech","subtheme":"Programmation","difficulty":1,"type":"qcm","question":"Quel est le rôle principal du CSS dans une page web ?","options":["Définir sa présentation visuelle","Décrire exclusivement ses données métier","Chiffrer toutes les connexions","Remplacer automatiquement le navigateur"],"correct":0,"explanation":"Le CSS définit des styles comme les couleurs, l’espacement et la disposition. Le HTML structure le contenu et JavaScript peut apporter des comportements interactifs."},{"id":"sci-100","category":"tech","subtheme":"Programmation","difficulty":1,"type":"boolean","question":"Un commentaire dans le code est généralement destiné à être exécuté comme une instruction.","options":["Vrai","Faux"],"correct":1,"explanation":"Un commentaire explique ou annote le programme pour les lecteurs et les outils. Il est normalement ignoré lors de l’exécution des instructions du langage."},{"id":"sci-101","category":"tech","subtheme":"Programmation","difficulty":2,"type":"qcm","question":"Dans un tableau indexé à partir de zéro, quel est l’indice du troisième élément ?","options":["2","3","1","0"],"correct":0,"explanation":"Les indices du premier, du deuxième et du troisième élément sont respectivement 0, 1 et 2. Cet écart entre position ordinaire et indice explique de nombreuses erreurs de décalage.","variant":"Les éléments d’un tableau sont numérotés à partir de l’indice 0. Quel indice faut-il utiliser pour accéder à l’élément situé en troisième position ?"},{"id":"sci-102","category":"tech","subtheme":"Programmation","difficulty":2,"type":"qcm","question":"À quoi sert un test unitaire ?","options":["À vérifier un comportement délimité du code","À prouver l’absence de tout défaut possible","À remplacer toutes les sauvegardes","À accélérer automatiquement chaque calcul"],"correct":0,"explanation":"Un test unitaire exerce une petite unité de comportement et compare le résultat à une attente. Il aide à détecter des régressions, mais les seuls cas testés ne constituent pas une preuve générale de correction."},{"id":"sci-103","category":"tech","subtheme":"Programmation","difficulty":2,"type":"qcm","question":"Que fait généralement une condition « si … sinon … » ?","options":["Elle choisit entre deux chemins d’exécution","Elle exécute toujours les deux branches","Elle répète forcément la branche mille fois","Elle transforme tous les nombres en texte"],"correct":0,"explanation":"La condition est évaluée, puis une branche est choisie selon son résultat. Le bloc « sinon » sert de solution alternative lorsque la condition n’est pas satisfaite."},{"id":"sci-104","category":"tech","subtheme":"Programmation","difficulty":2,"type":"qcm","question":"Pourquoi séparer une tâche répétée dans une fonction ?","options":["Pour réutiliser et nommer un comportement","Pour interdire toute erreur de logique","Pour éviter obligatoirement toute mémoire","Pour rendre les résultats aléatoires"],"correct":0,"explanation":"Une fonction rassemble un comportement et peut recevoir des paramètres puis produire un résultat. Cette séparation limite la duplication et facilite la compréhension, sans supprimer le besoin de tests."},{"id":"sci-105","category":"tech","subtheme":"Programmation","difficulty":3,"type":"qcm","question":"Dans un tableau trié, quelle complexité en nombre de comparaisons caractérise une recherche binaire au pire cas ?","options":["O(log n)","O(n²)","O(n!)","O(n² log n)"],"correct":0,"explanation":"Chaque comparaison élimine environ la moitié de la zone restante. Après k étapes, sa taille est de l’ordre de n/2ᵏ, d’où un nombre d’étapes proportionnel à log₂(n)."},{"id":"sci-106","category":"tech","subtheme":"Programmation","difficulty":3,"type":"qcm","question":"Quel problème peut provoquer une fonction récursive sans cas d’arrêt atteignable ?","options":["Une récursion non terminante pouvant épuiser la pile","Une correction automatique du résultat","Un tri garanti des entrées","La suppression des appels déjà exécutés"],"correct":0,"explanation":"Une fonction récursive se rappelle elle-même ; il faut un cas d’arrêt et un chemin qui s’en rapproche. Sans cela, les appels peuvent s’accumuler jusqu’à une erreur de pile, selon l’environnement."},{"id":"sci-107","category":"tech","subtheme":"Programmation","difficulty":3,"type":"qcm","question":"En JavaScript, que renvoie [1, 30, 4, 21].sort() sans comparateur numérique ?","options":["[1, 21, 30, 4]","[1, 4, 21, 30]","[30, 21, 4, 1]","[4, 30, 21, 1]"],"correct":0,"explanation":"Le tri par défaut compare les représentations textuelles selon leurs unités de code UTF-16. Pour trier ces nombres en ordre croissant, on peut fournir (a, b) => a − b.","source":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/sort"},{"id":"sci-108","category":"tech","subtheme":"Programmation","difficulty":3,"type":"boolean","question":"Une opération de tri « en place » peut modifier le tableau reçu.","options":["Vrai","Faux"],"correct":0,"explanation":"Un algorithme en place réorganise la structure existante en utilisant peu de mémoire supplémentaire. En JavaScript, Array.prototype.sort modifie ainsi le tableau d’origine ; une copie peut être nécessaire si l’on veut le préserver.","source":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/sort"},{"id":"sci-109","category":"tech","subtheme":"Programmation","difficulty":4,"type":"qcm","question":"Qu’est-ce qu’une fermeture, ou « closure », en programmation ?","options":["Une fonction associée à l’environnement lexical auquel elle accède","Une boucle qui ne termine jamais","Un fichier dont l’accès Internet est coupé","Une variable forcément globale"],"correct":0,"explanation":"Une fermeture permet à une fonction de conserver l’accès à des liaisons de son environnement lexical, même après la fin de l’appel qui les a créées. Elle sert notamment à encapsuler un état sans le rendre global.","source":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Closures"},{"id":"sci-110","category":"tech","subtheme":"Programmation","difficulty":4,"type":"qcm","question":"Dans le modèle d’exécution JavaScript, une longue tâche synchrone sur le fil principal du navigateur peut-elle retarder l’interface ?","options":["Oui, elle occupe le fil qui traite aussi de nombreuses interactions","Non, chaque instruction possède automatiquement un fil séparé","Non, le navigateur interrompt chaque fonction après une instruction","Oui, mais seulement si le réseau est déconnecté"],"correct":0,"explanation":"Une tâche JavaScript s’exécute jusqu’à rendre le contrôle : un calcul synchrone trop long peut donc retarder des événements et le rendu. Découper le travail ou utiliser un Worker pour des calculs adaptés aide à garder une interface réactive.","source":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Execution_model"},{"id":"sci-111","category":"tech","subtheme":"Programmation","difficulty":4,"type":"qcm","question":"Quel invariant rend correcte une recherche binaire classique dans un tableau trié ?","options":["Si la cible existe, elle reste dans l’intervalle de recherche courant","La cible est toujours au milieu exact du tableau","Tous les éléments hors intervalle ont été lus un par un","La taille de l’intervalle augmente à chaque étape"],"correct":0,"explanation":"Après chaque comparaison, la partie éliminée ne peut pas contenir la cible grâce à l’ordre du tableau. L’intervalle restant conserve donc les candidats et rétrécit jusqu’à trouver la valeur ou devenir vide."},{"id":"sci-112","category":"tech","subtheme":"Programmation","difficulty":4,"type":"qcm","question":"Dans une fonction pure, pour des entrées identiques et des valeurs immuables, quel comportement attend-on ?","options":["Le même résultat, sans effet de bord observable","Un résultat différent à chaque appel","La modification systématique d’une variable globale","L’ouverture obligatoire d’une connexion réseau"],"correct":0,"explanation":"Une fonction pure dépend de ses entrées et ne modifie pas l’état extérieur observable. Cette propriété facilite le raisonnement, la réutilisation et la mise en cache des résultats."},{"id":"cul-001","category":"mind","subtheme":"Mémoire","difficulty":1,"type":"qcm","question":"Quelle mémoire permet de garder un numéro en tête le temps de le composer ?","options":["La mémoire de travail","La mémoire procédurale","La mémoire autobiographique","La mémoire sémantique"],"correct":0,"explanation":"La mémoire de travail maintient et manipule temporairement des informations utiles à une tâche. Retenir brièvement un numéro ne revient pas encore à le mémoriser durablement."},{"id":"cul-002","category":"mind","subtheme":"Mémoire","difficulty":1,"type":"qcm","question":"Le souvenir d’un anniversaire vécu personnellement relève surtout de quelle mémoire ?","options":["La mémoire épisodique","La mémoire procédurale","La mémoire sensorielle","La mémoire sémantique"],"correct":0,"explanation":"La mémoire épisodique concerne les événements vécus, avec leur contexte. Savoir ce que signifie le mot anniversaire relève plutôt de la mémoire sémantique."},{"id":"cul-003","category":"mind","subtheme":"Mémoire","difficulty":1,"type":"qcm","question":"Savoir que Paris est la capitale de la France est un exemple de…","options":["mémoire sémantique","mémoire procédurale","mémoire échoïque","mémoire de travail uniquement"],"correct":0,"explanation":"La mémoire sémantique rassemble des connaissances générales et des significations. On peut connaître ce fait sans se rappeler précisément le moment où on l’a appris."},{"id":"cul-004","category":"mind","subtheme":"Mémoire","difficulty":1,"type":"qcm","question":"Quel apprentissage illustre le mieux la mémoire procédurale ?","options":["Savoir faire du vélo","Se souvenir de son dernier anniversaire","Connaître la capitale du Japon","Garder deux nombres quelques secondes"],"correct":0,"explanation":"La mémoire procédurale contribue aux savoir-faire acquis par la pratique. Un geste peut devenir fluide même lorsque décrire chacune de ses étapes reste difficile."},{"id":"cul-005","category":"mind","subtheme":"Mémoire","difficulty":2,"type":"qcm","question":"Pour préparer un contrôle dans une semaine, quelle activité entraîne directement le rappel ?","options":["Fermer le cours et essayer de l’expliquer","Relire uniquement les passages surlignés","Compter les pages déjà lues","Recopier le texte sans chercher son sens"],"correct":0,"explanation":"Essayer de retrouver une information entraîne sa récupération en mémoire. Vérifier ensuite la réponse aide à corriger les erreurs ; la difficulté ressentie ne signifie pas nécessairement que l’exercice est inutile.","source":"https://www.sciencedirect.com/science/article/pii/S0749596X06001367","variant":"Tu prépares un contrôle prévu dans une semaine. Laquelle de ces activités te fait directement exercer la récupération d’informations en mémoire ?"},{"id":"cul-006","category":"mind","subtheme":"Mémoire","difficulty":2,"type":"boolean","question":"À durée totale comparable, espacer des séances peut améliorer la rétention à long terme par rapport à tout concentrer en une seule séance.","options":["Vrai","Faux"],"correct":0,"explanation":"L’effet d’espacement est observé dans de nombreuses tâches d’apprentissage. L’intervalle utile dépend toutefois du contenu, du niveau acquis et du délai avant de devoir s’en souvenir.","source":"https://eric.ed.gov/?id=EJ1310148"},{"id":"cul-007","category":"mind","subtheme":"Mémoire","difficulty":2,"type":"qcm","question":"Une personne reconnaît un visage sans pouvoir retrouver son nom. Que montre cet exemple ?","options":["Reconnaissance et rappel peuvent différer","Reconnaître exige toujours de nommer","La mémoire est forcément effacée","Un souvenir reconnu est nécessairement exact"],"correct":0,"explanation":"Reconnaître consiste à identifier une information présentée ; rappeler consiste à la retrouver sans cette présentation directe. Les indices disponibles peuvent donc changer la réussite."},{"id":"cul-008","category":"mind","subtheme":"Mémoire","difficulty":2,"type":"qcm","question":"Quelle stratégie ajoute du sens à une nouvelle notion ?","options":["La relier à un exemple que l’on comprend","Répéter ses lettres sans réfléchir","La lire plus vite à chaque passage","Éviter toute comparaison avec ce que l’on sait"],"correct":0,"explanation":"Relier une notion à des connaissances et à des exemples favorise un traitement élaboré. Il faut vérifier que le rapprochement est juste, car une association trompeuse peut aussi être mémorisée."},{"id":"cul-009","category":"mind","subtheme":"Mémoire","difficulty":3,"type":"qcm","question":"Votre ancien code gêne l’apprentissage du nouveau. De quelle interférence s’agit-il ?","options":["Proactive","Rétroactive","Sensorielle","Procédurale exclusivement"],"correct":0,"explanation":"L’interférence proactive va de l’ancien apprentissage vers le nouveau. L’interférence rétroactive décrit l’effet inverse : du nouveau qui gêne la récupération de l’ancien.","tip":"Proactive : le passé agit vers l’avant."},{"id":"cul-010","category":"mind","subtheme":"Mémoire","difficulty":3,"type":"qcm","question":"Une question orientée après un événement peut-elle modifier le souvenir rapporté ?","options":["Oui, une information ultérieure peut influencer le souvenir","Non, le souvenir fonctionne comme une vidéo intacte","Oui, mais seulement si la personne ment","Non, dès lors que la personne est certaine"],"correct":0,"explanation":"La mémoire est reconstructive : des informations reçues après un événement peuvent influencer certains souvenirs rapportés. Cela n’implique ni mensonge ni modification automatique de chaque détail."},{"id":"cul-011","category":"mind","subtheme":"Mémoire","difficulty":3,"type":"qcm","question":"Pourquoi regrouper 1-9-4-5 en « 1945 » peut-il faciliter sa rétention pour quelqu’un qui connaît cette date ?","options":["Les éléments deviennent un groupe porteur de sens","La capacité de mémoire devient illimitée","Les chiffres passent directement dans les réflexes","Les interférences cessent définitivement"],"correct":0,"explanation":"Le regroupement, ou chunking, utilise des connaissances déjà présentes pour organiser plusieurs éléments. Il facilite certaines tâches sans supprimer les limites de la mémoire de travail."},{"id":"cul-012","category":"mind","subtheme":"Mémoire","difficulty":3,"type":"qcm","question":"Un indice de rappel est souvent utile lorsqu’il…","options":["correspond à une caractéristique encodée pendant l’apprentissage","est aussi long que le cours entier","n’a aucun rapport avec l’information apprise","remplace systématiquement tout apprentissage"],"correct":0,"explanation":"L’efficacité d’un indice dépend notamment de son lien avec l’encodage initial. Un indice très général peut aider moins qu’un indice lié au contexte ou au sens précis de ce qui a été appris."},{"id":"cul-013","category":"mind","subtheme":"Mémoire","difficulty":4,"type":"qcm","question":"Dans une expérience sur le rappel, pourquoi comparer des groupes ayant étudié pendant une durée totale équivalente ?","options":["Pour limiter une explication par le seul temps passé","Pour garantir que tous obtiennent le même score","Pour supprimer tout effet du hasard","Pour éviter de mesurer la mémoire"],"correct":0,"explanation":"Égaliser la durée rend moins plausible l’idée que la différence vient simplement de minutes supplémentaires. Cela ne suffit pas à contrôler toutes les différences : le matériel et les consignes comptent aussi."},{"id":"cul-014","category":"mind","subtheme":"Mémoire","difficulty":4,"type":"qcm","question":"Dans une tâche « ancien ou nouveau », une consigne pousse à répondre plus souvent « ancien ». Quel résultat peut augmenter sans meilleure discrimination ?","options":["Les reconnaissances correctes et les fausses alarmes","Uniquement les reconnaissances correctes","Uniquement les rejets corrects","La séparation entre les distributions, nécessairement"],"correct":0,"explanation":"Abaisser le critère de réponse peut accroître à la fois les détections correctes et les fausses alarmes. La théorie de la détection du signal distingue ce critère de la sensibilité à la différence entre éléments anciens et nouveaux."},{"id":"cul-015","category":"mind","subtheme":"Mémoire","difficulty":4,"type":"qcm","question":"Se rappeler une affirmation mais attribuer à tort son origine à un journal plutôt qu’à une rumeur correspond à…","options":["une erreur de mémoire de la source","une preuve de mensonge intentionnel","une perte obligatoire de la mémoire procédurale","une amélioration de la discrimination"],"correct":0,"explanation":"Le contenu et sa provenance ne sont pas toujours récupérés avec la même exactitude. Une attribution erronée de source peut rendre une affirmation plus crédible sans en améliorer la véracité."},{"id":"cul-016","category":"mind","subtheme":"Mémoire","difficulty":4,"type":"boolean","question":"La certitude exprimée par un témoin suffit à garantir l’exactitude de chaque détail de son souvenir.","options":["Vrai","Faux"],"correct":1,"explanation":"La confiance et l’exactitude ne sont pas identiques. Leur relation dépend des conditions de recueil et peut être affectée par des informations ou des retours reçus après l’événement."},{"id":"cul-017","category":"mind","subtheme":"Cognition","difficulty":1,"type":"qcm","question":"Que désigne principalement l’attention sélective ?","options":["Privilégier certaines informations parmi plusieurs","Mémoriser automatiquement tout ce qui est visible","Voir uniquement avec un seul œil","Être incapable de changer de tâche"],"correct":0,"explanation":"L’attention sélective aide à concentrer le traitement sur une partie des informations disponibles. Elle permet de suivre une conversation dans un environnement chargé, avec certaines limites."},{"id":"cul-018","category":"mind","subtheme":"Cognition","difficulty":1,"type":"boolean","question":"Le contexte peut influencer la façon dont on interprète une image ambiguë.","options":["Vrai","Faux"],"correct":0,"explanation":"La perception combine des informations sensorielles et des traitements liés au contexte et aux connaissances. Cela ne signifie pas que toute perception est arbitraire ou que chacun voit toujours une réalité différente."},{"id":"cul-019","category":"mind","subtheme":"Cognition","difficulty":1,"type":"qcm","question":"Quelle formulation distingue une décision d’une simple sensation ?","options":["Choisir entre plusieurs actions possibles","Détecter qu’une lumière s’allume","Entendre une note plus aiguë","Sentir la fraîcheur d’un objet"],"correct":0,"explanation":"Décider implique de sélectionner une option selon des informations, des buts ou des contraintes. Une sensation fournit des informations qui peuvent contribuer ensuite à ce choix."},{"id":"cul-020","category":"mind","subtheme":"Cognition","difficulty":1,"type":"qcm","question":"Quelle démarche aide à vérifier si l’on a compris une explication ?","options":["L’expliquer avec ses propres mots puis la vérifier","Se fier uniquement à son impression de familiarité","Compter le nombre de fois où on l’a vue","Considérer qu’un texte facile est forcément maîtrisé"],"correct":0,"explanation":"Reformuler oblige à organiser ce que l’on pense avoir compris. Comparer ensuite avec une explication fiable révèle des lacunes que la familiarité seule peut masquer."},{"id":"cul-021","category":"mind","subtheme":"Cognition","difficulty":2,"type":"qcm","question":"Chercher surtout les éléments qui soutiennent une idée déjà adoptée illustre quel biais ?","options":["Le biais de confirmation","L’interférence rétroactive","L’habituation sensorielle","La constance de taille"],"correct":0,"explanation":"Le biais de confirmation favorise la recherche ou l’interprétation d’indices conformes à une attente. Chercher activement ce qui pourrait contredire l’idée aide à mieux la tester.","source":"https://dictionary.apa.org/confirmation-bias?campaignid=70161000001Msst&vid=1000013","variant":"Une personne examine surtout les indices favorables à sa conviction initiale. Quel biais décrit le mieux cette manière de sélectionner les informations ?"},{"id":"cul-022","category":"mind","subtheme":"Cognition","difficulty":2,"type":"qcm","question":"Après avoir vu plusieurs accidents aux informations, on surestime leur fréquence. Quel mécanisme peut y contribuer ?","options":["L’heuristique de disponibilité","La mémoire procédurale","La vision binoculaire","Le conditionnement du réflexe pupillaire"],"correct":0,"explanation":"Des exemples faciles à retrouver peuvent peser trop lourd dans une estimation. Pour estimer une fréquence, des données représentatives sont plus utiles que la seule vivacité de quelques souvenirs."},{"id":"cul-023","category":"mind","subtheme":"Cognition","difficulty":2,"type":"qcm","question":"Continuer un projet uniquement parce qu’on y a déjà investi beaucoup, malgré de mauvaises perspectives, illustre…","options":["l’effet des coûts irrécupérables","la répétition espacée","la sensibilité au contraste","l’interférence proactive"],"correct":0,"explanation":"Un coût déjà engagé ne peut plus être récupéré quelle que soit la décision présente. Le choix devrait considérer les coûts et bénéfices à venir, tout en tenant compte des contraintes réelles."},{"id":"cul-024","category":"mind","subtheme":"Cognition","difficulty":2,"type":"qcm","question":"Un premier prix très élevé influence l’estimation suivante d’un objet. Quel effet décrit cette influence ?","options":["L’ancrage","L’extinction","L’oubli dirigé","La constance perceptive"],"correct":0,"explanation":"Un nombre initial peut servir de point de départ et orienter une estimation ultérieure. L’ancrage n’impose pas une réponse précise et son ampleur varie selon les situations."},{"id":"cul-025","category":"mind","subtheme":"Cognition","difficulty":3,"type":"qcm","question":"Dans une tâche de Stroop classique, pourquoi lire « ROUGE » imprimé en bleu peut-il ralentir la réponse « bleu » ?","options":["La lecture du mot entre en conflit avec la couleur à nommer","Le bleu devient physiquement rouge","Le mot efface la perception de la couleur","La personne a forcément un trouble de la lecture"],"correct":0,"explanation":"La lecture automatisée du mot peut interférer avec la consigne de nommer la couleur de l’encre. Ce conflit expérimental ne constitue pas, à lui seul, un diagnostic individuel."},{"id":"cul-026","category":"mind","subtheme":"Cognition","difficulty":3,"type":"boolean","question":"Une heuristique est nécessairement une erreur de raisonnement.","options":["Vrai","Faux"],"correct":1,"explanation":"Une heuristique est une stratégie simplificatrice qui peut être efficace sous certaines contraintes. Elle peut aussi produire des erreurs systématiques lorsque la situation s’y prête mal."},{"id":"cul-027","category":"mind","subtheme":"Cognition","difficulty":3,"type":"qcm","question":"Deux mesures évoluent ensemble. Que permet de conclure leur corrélation, à elle seule ?","options":["Qu’elles présentent une association dans les données","Que la première cause nécessairement la seconde","Que la seconde cause nécessairement la première","Qu’aucune autre variable ne peut intervenir"],"correct":0,"explanation":"Une corrélation décrit une association, sans déterminer à elle seule son origine. Une cause commune, une causalité inverse ou un biais de mesure peuvent notamment contribuer au résultat."},{"id":"cul-028","category":"mind","subtheme":"Cognition","difficulty":3,"type":"qcm","question":"Dans l’expérience du gorille inattendu, manquer un événement visible pendant une tâche de comptage illustre…","options":["la cécité d’inattention","l’amnésie infantile","le réflexe de préhension","la surdité physique"],"correct":0,"explanation":"Une tâche peut mobiliser l’attention au point qu’un événement inattendu passe inaperçu. La probabilité de le remarquer dépend des consignes et des caractéristiques de la scène : ce n’est pas une règle absolue.","source":"https://doi.org/10.1068/P281059"},{"id":"cul-029","category":"mind","subtheme":"Cognition","difficulty":4,"type":"qcm","question":"Sur 1 000 personnes, 10 ont une propriété. Un test détecte les 10 mais est positif pour 99 des 990 autres. Environ quelle part des positifs possède la propriété ?","options":["9 %","50 %","90 %","99 %"],"correct":0,"explanation":"Il y a 109 résultats positifs, dont seulement 10 correspondent à la propriété : 10 ÷ 109, soit environ 9 %. Cet exemple abstrait montre pourquoi le taux de base compte dans l’interprétation d’un test."},{"id":"cul-030","category":"mind","subtheme":"Cognition","difficulty":4,"type":"qcm","question":"Quelle différence sépare tirage aléatoire des participants et affectation aléatoire aux conditions ?","options":["Le premier concerne l’échantillon, la seconde la comparaison expérimentale","Les deux garantissent exactement la même chose","L’affectation aléatoire rend toujours l’échantillon représentatif","Le tirage aléatoire supprime toute erreur de mesure"],"correct":0,"explanation":"Le recrutement aléatoire concerne la façon de sélectionner des personnes dans une population. L’affectation aléatoire répartit les personnes recrutées entre conditions et aide à limiter les facteurs de confusion."},{"id":"cul-031","category":"mind","subtheme":"Cognition","difficulty":4,"type":"qcm","question":"Pourquoi annoncer à l’avance les hypothèses et analyses principales d’une étude ?","options":["Pour distinguer les tests prévus des explorations après observation","Pour empêcher toute découverte imprévue","Pour garantir que l’hypothèse sera confirmée","Pour remplacer le recueil de données"],"correct":0,"explanation":"Le préenregistrement rend plus visible ce qui était prévu avant de voir les résultats. Les analyses exploratoires restent utiles lorsqu’elles sont présentées comme telles et testées ensuite si nécessaire."},{"id":"cul-032","category":"mind","subtheme":"Cognition","difficulty":4,"type":"qcm","question":"Dans un raisonnement bayésien, que devient la plausibilité d’une hypothèse après de nouvelles données ?","options":["Elle combine la plausibilité préalable et la compatibilité des données avec les hypothèses","Elle dépend uniquement du dernier exemple observé","Elle ignore nécessairement les informations antérieures","Elle devient toujours égale à 50 %"],"correct":0,"explanation":"La mise à jour bayésienne combine une information préalable avec la vraisemblance des observations. Des données compatibles avec plusieurs hypothèses ne suffisent pas forcément à les départager fortement."},{"id":"cul-033","category":"mind","subtheme":"Vie sociale","difficulty":1,"type":"qcm","question":"Comprendre le point de vue d’une autre personne signifie-t-il forcément approuver sa position ?","options":["Non, compréhension et accord peuvent être distincts","Oui, comprendre impose d’être d’accord","Oui, sauf si la personne est plus âgée","Non, parce que comprendre interdit de coopérer"],"correct":0,"explanation":"On peut identifier les raisons et les émotions d’autrui tout en gardant un désaccord. Cette distinction facilite une discussion précise sans supposer que toute position se vaut."},{"id":"cul-034","category":"mind","subtheme":"Vie sociale","difficulty":1,"type":"qcm","question":"Qu’est-ce qu’une norme sociale ?","options":["Une attente partagée sur un comportement dans un groupe","Une loi écrite applicable dans tous les pays","Une réaction biologique identique chez tous","Une opinion privée que personne d’autre ne connaît"],"correct":0,"explanation":"Une norme sociale concerne ce qui est attendu ou jugé approprié dans un groupe. Elle peut varier selon le contexte et ne correspond pas nécessairement à une règle de droit."},{"id":"cul-035","category":"mind","subtheme":"Vie sociale","difficulty":1,"type":"qcm","question":"Deux personnes répartissent une tâche et coordonnent leurs efforts pour un but commun. Il s’agit de…","options":["coopération","compétition uniquement","mémoire sensorielle","conditionnement réflexe uniquement"],"correct":0,"explanation":"La coopération implique une coordination au service d’un objectif commun. Elle peut coexister avec des intérêts différents et demande souvent de clarifier les rôles."},{"id":"cul-036","category":"mind","subtheme":"Vie sociale","difficulty":1,"type":"boolean","question":"Éviter le regard suffit à prouver qu’une personne ment.","options":["Vrai","Faux"],"correct":1,"explanation":"Un comportement isolé n’est pas un détecteur fiable de mensonge. Le regard varie notamment avec la situation, les habitudes et les conventions sociales ; il ne permet pas ce diagnostic."},{"id":"cul-037","category":"mind","subtheme":"Vie sociale","difficulty":2,"type":"qcm","question":"Adopter une réponse pour ne pas être rejeté par le groupe relève surtout de quelle influence ?","options":["Normative","Informationnelle","Sensorielle","Rétroactive"],"correct":0,"explanation":"L’influence normative concerne le désir d’être accepté ou d’éviter la désapprobation. L’influence informationnelle repose plutôt sur l’idée que les autres détiennent une information utile.","variant":"Une personne se rallie à la réponse du groupe pour rester acceptée, même sans être convaincue. De quel type d’influence s’agit-il principalement ?"},{"id":"cul-038","category":"mind","subtheme":"Vie sociale","difficulty":2,"type":"qcm","question":"Dans une ville inconnue, suivre les habitants pour trouver une sortie relève surtout de quelle influence ?","options":["Informationnelle","Normative par définition","De la mémoire procédurale uniquement","D’un coût irrécupérable"],"correct":0,"explanation":"On utilise ici le comportement d’autrui comme un indice sur la situation. C’est utile si ces personnes savent réellement où elles vont, mais leur nombre ne garantit pas qu’elles disposent de la bonne information."},{"id":"cul-039","category":"mind","subtheme":"Vie sociale","difficulty":2,"type":"qcm","question":"Quelle réponse illustre une écoute active dans une discussion ?","options":["Reformuler ce qu’on a compris et demander confirmation","Préparer une objection sans écouter la fin","Assurer savoir ce que l’autre pense sans vérifier","Changer aussitôt de sujet pour éviter le silence"],"correct":0,"explanation":"Reformuler permet de vérifier le sens du message au lieu de le présumer. Une question ouverte peut ensuite préciser les besoins ou les faits encore ambigus."},{"id":"cul-040","category":"mind","subtheme":"Vie sociale","difficulty":2,"type":"qcm","question":"Un collègue arrive en retard une fois. Quelle interprétation évite le mieux une conclusion hâtive sur sa personnalité ?","options":["Chercher aussi les circonstances de ce retard","Conclure qu’il manque toujours de respect","Supposer que son groupe entier est ainsi","Considérer que toute circonstance est sans importance"],"correct":0,"explanation":"Un comportement unique peut avoir plusieurs causes. Examiner le contexte et des observations supplémentaires aide à éviter une attribution trop rapide à un trait stable."},{"id":"cul-041","category":"mind","subtheme":"Vie sociale","difficulty":3,"type":"qcm","question":"Dans une classe, beaucoup n’ont pas compris mais chacun croit être seul et n’ose pas poser de question. Quel phénomène cela illustre-t-il ?","options":["L’ignorance pluraliste","L’interférence rétroactive","La mémoire échoïque","La conservation de la masse"],"correct":0,"explanation":"L’ignorance pluraliste apparaît quand des membres d’un groupe se méprennent sur les opinions ou expériences des autres. Le silence de chacun peut alors être interprété à tort comme un signe de compréhension générale."},{"id":"cul-042","category":"mind","subtheme":"Vie sociale","difficulty":3,"type":"qcm","question":"Un questionnaire demande si l’on respecte toujours toutes les règles. Quel biais peut favoriser une réponse socialement valorisée ?","options":["La désirabilité sociale","La constance de couleur","La cécité au changement uniquement","La mémoire iconique"],"correct":0,"explanation":"La désirabilité sociale peut conduire à présenter une image favorable de soi, consciemment ou non. L’anonymat et une formulation moins jugeante peuvent réduire certaines pressions sans les éliminer entièrement."},{"id":"cul-043","category":"mind","subtheme":"Vie sociale","difficulty":3,"type":"qcm","question":"Une étude observe davantage de solitude chez les gros utilisateurs d’un réseau. Quelle conclusion est justifiée sans autre information ?","options":["Une association a été observée, le sens causal reste à établir","Le réseau cause nécessairement toute solitude","La solitude cause nécessairement tout usage","La personnalité des utilisateurs est définitivement déterminée"],"correct":0,"explanation":"Cette observation ne tranche pas entre causalité directe, causalité inverse et facteurs communs. Les effets peuvent aussi varier selon les usages et les personnes."},{"id":"cul-044","category":"mind","subtheme":"Vie sociale","difficulty":3,"type":"qcm","question":"Pourquoi décrire un résultat de groupe comme une tendance plutôt que comme une règle sur chaque individu ?","options":["Parce que les distributions individuelles peuvent se chevaucher","Parce qu’aucune moyenne ne peut être calculée","Parce que tous les individus d’un groupe sont identiques","Parce qu’une tendance interdit les exceptions"],"correct":0,"explanation":"Une différence de moyenne ne décrit pas forcément chaque personne et peut coexister avec un large chevauchement. Passer automatiquement du groupe à un individu favorise des conclusions injustifiées."},{"id":"cul-045","category":"mind","subtheme":"Vie sociale","difficulty":4,"type":"qcm","question":"Une étude de coopération recrute uniquement des étudiants volontaires d’un même établissement. Quelle limite faut-il examiner ?","options":["La généralisation à d’autres populations et contextes","L’impossibilité de calculer toute moyenne","La certitude que les résultats sont faux","L’absence automatique de consentement"],"correct":0,"explanation":"L’échantillon et le contexte peuvent limiter la validité externe du résultat. Une étude peut être informative tout en nécessitant d’autres populations avant de conclure à une généralité."},{"id":"cul-046","category":"mind","subtheme":"Vie sociale","difficulty":4,"type":"qcm","question":"Une chercheuse adapte une échelle de confiance à une autre culture. Pourquoi vérifier l’équivalence de mesure ?","options":["Pour savoir si les items mesurent des construits comparables","Pour imposer les mêmes réponses dans les deux groupes","Pour remplacer la traduction par une moyenne","Pour garantir l’absence de différences culturelles"],"correct":0,"explanation":"Des mots traduits peuvent conserver une signification ou un fonctionnement différent selon le contexte. Vérifier la mesure aide à ne pas confondre une différence d’interprétation avec une différence du construit étudié."},{"id":"cul-047","category":"mind","subtheme":"Vie sociale","difficulty":4,"type":"qcm","question":"Une première étude rapporte un effet social. Que permet surtout une réplication indépendante bien conçue ?","options":["Évaluer la robustesse de l’effet dans de nouvelles données","Démontrer que le contexte n’a jamais d’importance","Transformer automatiquement une corrélation en causalité","Prouver définitivement un trait chez chaque personne"],"correct":0,"explanation":"Une réplication apporte de nouvelles observations sur un résultat et ses conditions d’apparition. Un succès ou un échec doit être interprété avec le protocole, la précision et le contexte."},{"id":"cul-048","category":"mind","subtheme":"Vie sociale","difficulty":4,"type":"boolean","question":"Obtenir un résultat statistiquement significatif dans une étude garantit un effet social important dans la vie quotidienne.","options":["Vrai","Faux"],"correct":1,"explanation":"La significativité statistique ne donne pas directement l’ampleur ni l’utilité pratique d’un effet. Il faut aussi examiner sa taille, son incertitude, la qualité de l’étude et le contexte d’application."},{"id":"cul-049","category":"world","subtheme":"Histoire","difficulty":1,"type":"qcm","question":"En quelle année commence la Révolution française ?","options":["1789","1776","1815","1848"],"correct":0,"explanation":"L’année 1789 marque notamment les États généraux, la prise de la Bastille et la Déclaration des droits de l’homme et du citoyen. 1776 correspond à la Déclaration d’indépendance des États-Unis."},{"id":"cul-050","category":"world","subtheme":"Histoire","difficulty":1,"type":"qcm","question":"À quelle civilisation antique associe-t-on la ville d’Athènes et ses institutions démocratiques ?","options":["La civilisation grecque","La civilisation inca","La civilisation égyptienne","La civilisation chinoise"],"correct":0,"explanation":"Athènes est une cité grecque. Sa démocratie antique excluait notamment les femmes, les esclaves et les étrangers : elle ne se confond pas avec le suffrage universel contemporain."},{"id":"cul-051","category":"world","subtheme":"Histoire","difficulty":1,"type":"qcm","question":"Quel événement est associé au 11 novembre 1918 en France ?","options":["L’armistice avec l’Allemagne pendant la Première Guerre mondiale","La signature du traité de Versailles","Le début de la Seconde Guerre mondiale","La chute du mur de Berlin"],"correct":0,"explanation":"L’armistice du 11 novembre 1918 met fin aux combats sur le front occidental. Le traité de Versailles est signé en 1919 : arrêter les combats et conclure la paix sont deux étapes distinctes."},{"id":"cul-052","category":"world","subtheme":"Histoire","difficulty":1,"type":"boolean","question":"Les pyramides de Gizeh sont antérieures à l’Empire romain.","options":["Vrai","Faux"],"correct":0,"explanation":"Les grandes pyramides de Gizeh datent du IIIe millénaire avant notre ère. L’Empire romain débute traditionnellement en 27 avant notre ère, bien plus tard."},{"id":"cul-053","category":"world","subtheme":"Histoire","difficulty":2,"type":"qcm","question":"Quel rôle associe-t-on à Gutenberg dans l’Europe du XVe siècle ?","options":["Le développement de l’imprimerie à caractères métalliques mobiles","L’invention du papier en Chine","La création de l’alphabet latin","La première transmission radiophonique"],"correct":0,"explanation":"Gutenberg perfectionne un système d’impression utilisant des caractères métalliques mobiles et une presse. Des techniques d’impression existaient auparavant en Asie : il n’a pas inventé toute forme d’imprimerie.","variant":"Dans l’Europe du XVe siècle, à quelle avancée Gutenberg a-t-il contribué ?"},{"id":"cul-054","category":"world","subtheme":"Histoire","difficulty":2,"type":"qcm","question":"Quel souverain français est associé à l’édit de Nantes de 1598 ?","options":["Henri IV","Louis XIV","François Ier","Louis XVI"],"correct":0,"explanation":"Henri IV promulgue cet édit pour organiser une coexistence religieuse après les guerres de Religion. Louis XIV le révoque en 1685 ; ce ne sont pas deux décisions du même règne."},{"id":"cul-055","category":"world","subtheme":"Histoire","difficulty":2,"type":"qcm","question":"En quelle année le mur de Berlin s’ouvre-t-il, événement symbolique de la fin de la guerre froide ?","options":["1989","1961","1945","1991"],"correct":0,"explanation":"L’ouverture du mur intervient le 9 novembre 1989. Le mur avait été construit à partir de 1961 ; l’Allemagne est réunifiée en 1990."},{"id":"cul-056","category":"world","subtheme":"Histoire","difficulty":2,"type":"qcm","question":"Quelle transformation caractérise la révolution néolithique ?","options":["Le développement de l’agriculture et de l’élevage","L’apparition générale de l’écriture alphabétique","L’invention de la machine à vapeur","L’abolition de toutes les sociétés nomades"],"correct":0,"explanation":"Le Néolithique est associé à l’agriculture, à l’élevage et à des transformations des habitats. Cette transition s’est produite à des dates différentes selon les régions et n’a pas supprimé toutes les autres façons de vivre."},{"id":"cul-057","category":"world","subtheme":"Histoire","difficulty":3,"type":"qcm","question":"Quel document anglais de 1215 est connu pour avoir limité certains pouvoirs royaux ?","options":["La Magna Carta","L’Habeas Corpus Act de 1679","La Déclaration des droits de 1689","L’Acte d’Union de 1707"],"correct":0,"explanation":"La Magna Carta est accordée en 1215 sous le roi Jean. Elle protège d’abord des intérêts précis, notamment ceux des barons, et ne constitue pas une démocratie moderne."},{"id":"cul-058","category":"world","subtheme":"Histoire","difficulty":3,"type":"qcm","question":"Le traité de Versailles de 1919 est signé dans quel lieu ?","options":["La galerie des Glaces du château de Versailles","La salle du Jeu de paume","Le palais des Papes à Avignon","Le château de Chambord"],"correct":0,"explanation":"La signature a lieu le 28 juin 1919 dans la galerie des Glaces. Le choix est symbolique : l’Empire allemand y avait été proclamé en 1871.","source":"https://www.chateauversailles.fr/decouvrir/histoire/grandes-dates/traite-versailles"},{"id":"cul-059","category":"world","subtheme":"Histoire","difficulty":3,"type":"qcm","question":"Quelles écritures figurent sur la pierre de Rosette ?","options":["Hiéroglyphes, démotique et grec","Hiéroglyphes, latin et arabe","Cunéiforme, grec et latin","Démotique, hébreu et sanskrit"],"correct":0,"explanation":"La stèle porte un décret dans trois écritures, correspondant à deux langues : l’égyptien et le grec. La comparaison avec le grec a contribué au déchiffrement des écritures égyptiennes.","source":"https://musees-occitanie.fr/oeuvre/pierre-de-rosette/"},{"id":"cul-060","category":"world","subtheme":"Histoire","difficulty":3,"type":"qcm","question":"Quel empire a pour capitale Tenochtitlan avant la conquête espagnole du XVIe siècle ?","options":["L’empire aztèque","L’empire inca","L’empire carolingien","L’empire ottoman"],"correct":0,"explanation":"Tenochtitlan est la capitale mexica, au cœur de l’ensemble souvent appelé empire aztèque. Cuzco est associée à l’empire inca, dans les Andes."},{"id":"cul-061","category":"world","subtheme":"Histoire","difficulty":4,"type":"qcm","question":"Le traité de Tordesillas de 1494 est conclu entre quelles couronnes ?","options":["La Castille et le Portugal","L’Angleterre et la France","Venise et l’Empire ottoman","La Suède et le Danemark"],"correct":0,"explanation":"Ce traité établit une ligne de partage des zones d’expansion revendiquées par les couronnes castillane et portugaise. Les peuples vivant dans les territoires concernés n’ont pas participé à cette décision.","source":"https://pares.cultura.gob.es/ParesBusquedas20/catalogo/description/121027"},{"id":"cul-062","category":"world","subtheme":"Histoire","difficulty":4,"type":"qcm","question":"Quelle distinction sépare une source primaire d’une étude historique secondaire ?","options":["La première est directement liée au contexte étudié, la seconde l’analyse après coup","La première est toujours exacte, la seconde toujours subjective","La première est nécessairement manuscrite","La seconde ne peut jamais citer de documents"],"correct":0,"explanation":"Une lettre d’époque peut constituer une source primaire, tandis qu’un ouvrage d’historien peut l’analyser. Une source primaire doit aussi être critiquée : son auteur, son but et ses omissions comptent."},{"id":"cul-063","category":"world","subtheme":"Histoire","difficulty":4,"type":"qcm","question":"Quelle limite affecte une datation au carbone 14 appliquée directement à une statue en marbre ?","options":["Le marbre n’est pas un vestige organique datable directement par cette méthode","Le carbone 14 ne peut dater que les métaux","La méthode fournit toujours l’année exacte de sculpture","La taille de la statue annule sa radioactivité"],"correct":0,"explanation":"La datation au carbone 14 sert principalement à dater des matières ayant échangé du carbone avec le vivant. Un résidu organique associé peut parfois être daté, mais son âge doit être relié prudemment à celui de l’objet."},{"id":"cul-064","category":"world","subtheme":"Histoire","difficulty":4,"type":"qcm","question":"Pourquoi éviter de lire tous les événements anciens comme des étapes inévitables vers le présent ?","options":["Cela risque d’effacer les incertitudes et possibilités de leur époque","Parce que les acteurs du passé connaissaient tous l’avenir","Parce que toute chronologie est impossible","Parce que les sources écrites sont inutilisables"],"correct":0,"explanation":"Une lecture téléologique présente le résultat final comme s’il avait toujours été prévu. Replacer les décisions dans les informations et options disponibles à l’époque aide à comprendre leur contingence."},{"id":"cul-065","category":"world","subtheme":"Géographie","difficulty":1,"type":"qcm","question":"Quel océan sépare principalement l’Europe de l’Amérique du Nord ?","options":["L’Atlantique","L’Indien","Le Pacifique","L’Austral"],"correct":0,"explanation":"L’océan Atlantique s’étend entre les Amériques et l’Europe ainsi que l’Afrique. Le Pacifique sépare principalement les Amériques de l’Asie et de l’Océanie."},{"id":"cul-066","category":"world","subtheme":"Géographie","difficulty":1,"type":"qcm","question":"Quel pays a pour capitale Tokyo ?","options":["Le Japon","La Corée du Sud","La Chine","La Thaïlande"],"correct":0,"explanation":"Tokyo est la capitale du Japon. Séoul, Pékin et Bangkok sont respectivement les capitales de la Corée du Sud, de la Chine et de la Thaïlande."},{"id":"cul-067","category":"world","subtheme":"Géographie","difficulty":1,"type":"qcm","question":"Que sépare l’équateur terrestre ?","options":["Les hémisphères Nord et Sud","Les hémisphères Est et Ouest","L’Europe et l’Asie","Tous les océans en parts égales"],"correct":0,"explanation":"L’équateur correspond à la latitude 0° et sépare les deux hémisphères. Les longitudes, elles, sont mesurées par rapport à un méridien de référence."},{"id":"cul-068","category":"world","subtheme":"Géographie","difficulty":1,"type":"boolean","question":"L’Australie se trouve entièrement dans l’hémisphère Sud.","options":["Vrai","Faux"],"correct":0,"explanation":"Le continent australien est situé au sud de l’équateur. Il ne faut pas le confondre avec l’ensemble de l’Océanie, dont certains territoires sont au nord de l’équateur."},{"id":"cul-069","category":"world","subtheme":"Géographie","difficulty":2,"type":"qcm","question":"Quel grand fleuve traverse l’Égypte avant de se jeter dans la Méditerranée ?","options":["Le Nil","Le Niger","Le Congo","Le Zambèze"],"correct":0,"explanation":"Le Nil traverse l’Égypte et forme un delta sur la Méditerranée. Les autres fleuves proposés se trouvent aussi en Afrique, mais suivent d’autres bassins versants.","variant":"Quel fleuve africain rejoint la mer Méditerranée après avoir traversé l’Égypte ?"},{"id":"cul-070","category":"world","subtheme":"Géographie","difficulty":2,"type":"qcm","question":"Sur une carte au 1:50 000, à quelle distance réelle correspondent 2 cm ?","options":["1 km","100 m","10 km","25 km"],"correct":0,"explanation":"Chaque centimètre de carte représente 50 000 cm, soit 500 m. Deux centimètres représentent donc 1 000 m, c’est-à-dire 1 km."},{"id":"cul-071","category":"world","subtheme":"Géographie","difficulty":2,"type":"qcm","question":"Que mesure la latitude d’un lieu ?","options":["Son angle au nord ou au sud de l’équateur","Son angle à l’est ou à l’ouest de Greenwich","Sa hauteur au-dessus de la mer","Sa distance au centre de la Terre"],"correct":0,"explanation":"La latitude s’exprime en degrés nord ou sud, entre 0° et 90°. La longitude décrit une position est-ouest par rapport à un méridien de référence."},{"id":"cul-072","category":"world","subtheme":"Géographie","difficulty":2,"type":"qcm","question":"Quel phénomène est à l’origine de nombreuses chaînes comme l’Himalaya ?","options":["La convergence et la collision de plaques tectoniques","L’évaporation de l’océan uniquement","L’augmentation quotidienne de la rotation terrestre","La chute régulière de météorites"],"correct":0,"explanation":"La collision des plaques indienne et eurasienne a épaissi et déformé la croûte à l’origine de l’Himalaya. D’autres reliefs peuvent avoir des histoires différentes, comme le volcanisme ou l’érosion."},{"id":"cul-073","category":"world","subtheme":"Géographie","difficulty":3,"type":"qcm","question":"Dans l’hémisphère Nord, un cours d’eau coule-t-il nécessairement vers le sud ?","options":["Non, son écoulement suit principalement la pente","Oui, car l’équateur attire l’eau","Oui, sauf pendant l’hiver","Non, il coule toujours vers le nord"],"correct":0,"explanation":"L’eau s’écoule sous l’effet de la gravité vers les niveaux plus bas. Un fleuve peut aller vers le nord, comme le Nil, si c’est la direction générale de sa pente."},{"id":"cul-074","category":"world","subtheme":"Géographie","difficulty":3,"type":"qcm","question":"Qu’est-ce qu’un bassin versant ?","options":["Le territoire dont les eaux convergent vers un même exutoire","Une réserve d’eau obligatoirement artificielle","La seule partie marine d’un delta","Une zone recevant toujours la même pluie"],"correct":0,"explanation":"Un bassin versant est délimité par des lignes de partage des eaux. Les écoulements y rejoignent un exutoire commun, même si le réseau comporte de nombreux affluents."},{"id":"cul-075","category":"world","subtheme":"Géographie","difficulty":3,"type":"qcm","question":"Pourquoi les régions polaires paraissent-elles très grandes sur une carte mondiale de Mercator ?","options":["La projection agrandit fortement les surfaces aux hautes latitudes","Les pôles occupent réellement la moitié de la planète","L’échelle est identique en chaque point du planisphère","La Terre s’élargit physiquement près des pôles"],"correct":0,"explanation":"Mercator conserve les angles locaux mais déforme fortement les superficies en s’éloignant de l’équateur. Comparer des tailles de pays sur cette projection sans correction peut donc tromper.","source":"https://www.usgs.gov/faqs/how-are-different-map-projections-used"},{"id":"cul-076","category":"world","subtheme":"Géographie","difficulty":3,"type":"qcm","question":"Qu’est-ce qu’un endoréisme ?","options":["Un drainage des eaux vers un bassin sans écoulement vers l’océan","Un courant marin exclusivement polaire","Une éruption sous un glacier","Une migration saisonnière de dunes uniquement"],"correct":0,"explanation":"Un bassin endoréique retient ses eaux à l’intérieur des terres ; elles peuvent s’évaporer ou s’infiltrer. La mer Caspienne constitue un grand exemple de terminaison de bassin endoréique."},{"id":"cul-077","category":"world","subtheme":"Géographie","difficulty":4,"type":"qcm","question":"Une projection équivalente conserve principalement…","options":["les superficies relatives","tous les angles locaux","toutes les distances","toutes les formes et superficies à la fois"],"correct":0,"explanation":"Une projection équivalente conserve les rapports de superficies. Elle ne peut conserver simultanément toutes les autres propriétés géométriques d’une sphère sur un plan.","source":"https://www.usgs.gov/faqs/how-are-different-map-projections-used"},{"id":"cul-078","category":"world","subtheme":"Géographie","difficulty":4,"type":"qcm","question":"Pour comparer la mortalité de deux populations d’âges très différents, pourquoi standardiser les taux par âge ?","options":["Pour réduire l’effet des différences de structure d’âge","Pour effacer tout décès de la population la plus âgée","Pour imposer le même nombre d’habitants","Pour transformer un taux en nombre de naissances"],"correct":0,"explanation":"Le risque de décès varie fortement avec l’âge. La standardisation facilite une comparaison à structure d’âge commune, sans expliquer à elle seule toutes les causes d’une différence."},{"id":"cul-079","category":"world","subtheme":"Géographie","difficulty":4,"type":"qcm","question":"Pourquoi changer les limites des zones sur une carte statistique peut-il changer les associations observées ?","options":["Parce que l’agrégation spatiale influence les résultats","Parce que les habitants changent instantanément de comportement","Parce que toute donnée géographique est fausse","Parce que les frontières suppriment les variations locales"],"correct":0,"explanation":"Le problème des unités spatiales modifiables désigne cette sensibilité au découpage et à l’échelle d’agrégation. Une association entre moyennes territoriales ne décrit pas automatiquement les relations entre individus."},{"id":"cul-080","category":"world","subtheme":"Géographie","difficulty":4,"type":"qcm","question":"Sur une sphère idéale, quel trajet de surface relie deux points par la distance la plus courte, hors cas antipodal ?","options":["L’arc le plus court d’un grand cercle","Toujours une ligne de latitude","Toujours un cap constant","Le trajet passant obligatoirement par l’équateur"],"correct":0,"explanation":"La géodésique d’une sphère suit un grand cercle. Un trajet à cap constant, appelé loxodromie, n’est généralement pas le plus court ; la Terre réelle demande un modèle plus précis."},{"id":"cul-081","category":"world","subtheme":"Arts et culture","difficulty":1,"type":"qcm","question":"Qui a peint La Joconde ?","options":["Léonard de Vinci","Michel-Ange","Raphaël","Sandro Botticelli"],"correct":0,"explanation":"La Joconde est un portrait peint par Léonard de Vinci à la Renaissance. Les trois autres artistes ont également marqué l’art italien, mais n’en sont pas les auteurs.","variant":"À quel artiste doit-on le portrait connu sous le nom de La Joconde ?"},{"id":"cul-082","category":"world","subtheme":"Arts et culture","difficulty":1,"type":"qcm","question":"Quel instrument possède habituellement des touches et des marteaux frappant des cordes ?","options":["Le piano","L’orgue à tuyaux","L’accordéon","Le clavecin"],"correct":0,"explanation":"Dans un piano acoustique, les touches actionnent des marteaux qui frappent les cordes. Le clavecin possède également un clavier, mais ses cordes sont pincées."},{"id":"cul-083","category":"world","subtheme":"Arts et culture","difficulty":1,"type":"qcm","question":"Qui est l’auteur du roman Les Misérables ?","options":["Victor Hugo","Émile Zola","Gustave Flaubert","Honoré de Balzac"],"correct":0,"explanation":"Victor Hugo publie Les Misérables en 1862. Jean Valjean, Cosette et l’inspecteur Javert en sont des personnages centraux."},{"id":"cul-084","category":"world","subtheme":"Arts et culture","difficulty":1,"type":"qcm","question":"Au théâtre, une didascalie est principalement…","options":["une indication de jeu ou de mise en scène","un personnage qui parle au public","une rime à la fin d’un vers","une musique obligatoirement chantée"],"correct":0,"explanation":"Les didascalies peuvent préciser un geste, un décor, une intonation ou une entrée. Elles se distinguent des paroles prononcées par les personnages."},{"id":"cul-085","category":"world","subtheme":"Arts et culture","difficulty":2,"type":"qcm","question":"Quel mouvement doit son nom au titre Impression, soleil levant de Claude Monet ?","options":["L’impressionnisme","Le cubisme","Le surréalisme","Le néoclassicisme"],"correct":0,"explanation":"Le titre de cette toile exposée en 1874 est à l’origine du terme impressionniste dans la critique. Le mouvement explore notamment les effets de lumière et les impressions fugitives.","source":"https://salons.musee-orsay.fr/Detail/objects/58022"},{"id":"cul-086","category":"world","subtheme":"Arts et culture","difficulty":2,"type":"qcm","question":"Qu’est-ce qu’une métaphore ?","options":["Un rapprochement fondé sur une analogie, sans outil de comparaison explicite","Une répétition obligatoire du même son final","Une exagération toujours numérique","Une liste de synonymes sans image"],"correct":0,"explanation":"Dire « cet enfant est un rayon de soleil » rapproche l’enfant et la lumière par une image. « Cet enfant est comme un rayon de soleil » emploie un outil explicite et relève de la comparaison."},{"id":"cul-087","category":"world","subtheme":"Arts et culture","difficulty":2,"type":"qcm","question":"Dans une partition, que désigne généralement le tempo ?","options":["La vitesse de la pulsation","La hauteur d’une note isolée","Le volume maximal de l’instrument","Le nombre de cordes nécessaires"],"correct":0,"explanation":"Le tempo indique la rapidité de la pulsation, souvent en battements par minute. L’intensité sonore relève plutôt des nuances telles que piano ou forte."},{"id":"cul-088","category":"world","subtheme":"Arts et culture","difficulty":2,"type":"boolean","question":"Un haïku japonais classique est traditionnellement associé à un rythme de 5, 7 puis 5 unités sonores.","options":["Vrai","Faux"],"correct":0,"explanation":"Le modèle japonais repose sur des mores, unités sonores qui ne correspondent pas exactement aux syllabes françaises. Les adaptations dans d’autres langues peuvent suivre des conventions différentes."},{"id":"cul-089","category":"world","subtheme":"Arts et culture","difficulty":3,"type":"qcm","question":"Quel principe caractérise la perspective linéaire en peinture ?","options":["Représenter la profondeur avec des lignes convergeant vers des points de fuite","Utiliser uniquement des couleurs froides","Supprimer toute différence de taille apparente","Peindre chaque objet de face sans profondeur"],"correct":0,"explanation":"La perspective linéaire organise les projections selon une position d’observation. Des lignes parallèles dans l’espace peuvent converger vers un point de fuite dans l’image."},{"id":"cul-090","category":"world","subtheme":"Arts et culture","difficulty":3,"type":"qcm","question":"En musique, que signifie une syncope ?","options":["Un accent déplacé vers une partie faible ou une prolongation sur un temps fort","Une augmentation systématique du volume à chaque mesure","La répétition exacte de la même note à chaque temps","Un silence obligatoire de quatre mesures"],"correct":0,"explanation":"La syncope crée un décalage entre les accents attendus et ceux entendus. Elle est fréquente dans de nombreux styles et ne signifie pas simplement jouer plus vite."},{"id":"cul-091","category":"world","subtheme":"Arts et culture","difficulty":3,"type":"boolean","question":"Dans un récit, un narrateur à la première personne est nécessairement l’auteur réel.","options":["Vrai","Faux"],"correct":1,"explanation":"Le narrateur est une instance du récit, même lorsqu’il dit « je ». L’auteur peut inventer une voix dont les expériences et les opinions ne sont pas les siennes."},{"id":"cul-092","category":"world","subtheme":"Arts et culture","difficulty":3,"type":"qcm","question":"Quel procédé consiste à assembler différents plans filmés pour construire un sens et un rythme ?","options":["Le montage","L’étalonnage uniquement","La prise de son uniquement","Le repérage"],"correct":0,"explanation":"Le montage organise la succession et la durée des plans. L’ordre des images peut modifier la manière dont le public interprète une action ou une expression."},{"id":"cul-093","category":"world","subtheme":"Arts et culture","difficulty":4,"type":"qcm","question":"Qu’appelle-t-on une ekphrasis en littérature ?","options":["La description verbale d’une œuvre d’art ou d’une représentation visuelle","La suppression des verbes dans tout un roman","La répétition d’un mot en début de phrase","Une traduction mot à mot d’un poème"],"correct":0,"explanation":"L’ekphrasis met en mots une œuvre ou une représentation visuelle, réelle ou imaginaire. Elle ne se limite pas nécessairement à un inventaire : elle peut aussi orienter le regard et l’interprétation."},{"id":"cul-094","category":"world","subtheme":"Arts et culture","difficulty":4,"type":"qcm","question":"Dans le tempérament égal à douze demi-tons par octave, quel rapport de fréquences correspond à un demi-ton ?","options":["La racine douzième de 2","Le rapport 3/2","Le rapport 2/1","Le rapport 12/2"],"correct":0,"explanation":"Douze multiplications par le même rapport doivent doubler la fréquence, puisque l’octave correspond au rapport 2/1. Le rapport d’un demi-ton vaut donc 2 puissance 1/12, soit environ 1,05946."},{"id":"cul-095","category":"world","subtheme":"Arts et culture","difficulty":4,"type":"qcm","question":"Quel exemple correspond à un patrimoine culturel immatériel ?","options":["Un savoir-faire artisanal transmis dans une communauté","Le seul mur de pierre d’un château","Une roche choisie uniquement pour sa composition","Un bâtiment considéré uniquement comme bien immobilier"],"correct":0,"explanation":"Le patrimoine immatériel comprend notamment des pratiques, expressions, connaissances et savoir-faire reconnus par les communautés. Les objets et lieux associés peuvent y contribuer, mais ne remplacent pas la pratique vivante.","source":"https://ich.unesco.org/doc/src/52066-EN.pdf"},{"id":"cul-096","category":"world","subtheme":"Arts et culture","difficulty":4,"type":"qcm","question":"Pourquoi distinguer restauration et restitution d’une œuvre ancienne ?","options":["La restauration conserve une œuvre existante ; la restitution propose un état supposé à partir d’indices","Les deux signifient toujours repeindre entièrement l’œuvre","Une restitution est automatiquement un original authentique","La restauration interdit toute documentation"],"correct":0,"explanation":"Une restauration agit sur la conservation et la lisibilité d’un objet existant selon des choix documentés. Une restitution reconstitue un état hypothétique et doit rendre visibles les limites des preuves disponibles."},{"id":"cul-097","category":"tech","subtheme":"Réseaux","difficulty":1,"type":"qcm","question":"Quelle est la fonction principale d’un routeur dans un réseau ?","options":["Acheminer des paquets entre des réseaux","Dessiner les pages web","Créer les mots de passe de tous les comptes","Traduire tous les fichiers en images"],"correct":0,"explanation":"Un routeur choisit des chemins pour transmettre les paquets entre réseaux. Une box domestique regroupe souvent ce rôle avec d’autres fonctions comme le Wi-Fi et le pare-feu."},{"id":"cul-098","category":"tech","subtheme":"Réseaux","difficulty":1,"type":"boolean","question":"Wi-Fi et accès à Internet désignent exactement la même chose.","options":["Vrai","Faux"],"correct":1,"explanation":"Le Wi-Fi est une technologie de connexion sans fil à un réseau local. On peut être connecté en Wi-Fi à une box dont la liaison Internet est interrompue."},{"id":"cul-099","category":"tech","subtheme":"Réseaux","difficulty":1,"type":"qcm","question":"À quoi sert principalement le DNS lors de la visite d’un site ?","options":["Retrouver des informations réseau associées à un nom de domaine","Augmenter la taille de l’écran","Effacer automatiquement tous les cookies","Remplacer le navigateur"],"correct":0,"explanation":"Le DNS permet notamment de retrouver les adresses IP associées à un nom comme example.org. Il existe aussi d’autres types d’enregistrements DNS, par exemple pour le courrier électronique.","source":"https://www.icann.org/resources/pages/dns-2022-09-13-en"},{"id":"cul-100","category":"tech","subtheme":"Réseaux","difficulty":1,"type":"qcm","question":"Quelle unité mesure un débit de transmission plutôt qu’une quantité de données stockées ?","options":["Le mégabit par seconde","Le gigaoctet","L’octet","Le téraoctet"],"correct":0,"explanation":"Un débit exprime une quantité par unité de temps, par exemple des mégabits par seconde. Une capacité de stockage s’exprime en octets et multiples, sans « par seconde »."},{"id":"cul-101","category":"tech","subtheme":"Réseaux","difficulty":2,"type":"qcm","question":"Que protège principalement HTTPS pendant une connexion correctement établie ?","options":["La confidentialité et l’intégrité des échanges entre navigateur et serveur","L’absence de mensonge dans le contenu du site","L’anonymat absolu de toute navigation","La fiabilité de tous les achats proposés"],"correct":0,"explanation":"HTTPS utilise TLS pour protéger le transport et authentifier le serveur selon les mécanismes de certificat. Un site frauduleux peut aussi utiliser HTTPS : le cadenas ne certifie pas l’honnêteté du contenu.","variant":"Un navigateur communique avec un serveur par une connexion HTTPS correctement établie. Quelle protection ce protocole apporte-t-il principalement ?"},{"id":"cul-102","category":"tech","subtheme":"Réseaux","difficulty":2,"type":"qcm","question":"Une latence plus faible signifie généralement…","options":["un délai de réponse plus court","un stockage plus grand","une résolution d’écran supérieure","un nombre illimité de connexions"],"correct":0,"explanation":"La latence est un délai, tandis que le débit mesure une quantité transférée par seconde. Une liaison peut avoir un fort débit et rester peu réactive si sa latence est élevée."},{"id":"cul-103","category":"tech","subtheme":"Réseaux","difficulty":2,"type":"qcm","question":"Combien de bits comporte une adresse IPv4 ?","options":["32","16","64","128"],"correct":0,"explanation":"Une adresse IPv4 comporte 32 bits, généralement écrits sous la forme de quatre nombres décimaux. IPv6 utilise 128 bits, ce qui offre un espace d’adressage beaucoup plus vaste."},{"id":"cul-104","category":"tech","subtheme":"Réseaux","difficulty":2,"type":"qcm","question":"Pourquoi découper les données en paquets pour les transmettre ?","options":["Pour acheminer des unités de données sur une infrastructure partagée","Pour rendre tout retard impossible","Pour garantir qu’aucun paquet ne sera perdu","Pour supprimer le besoin d’adresses"],"correct":0,"explanation":"La commutation de paquets permet à plusieurs communications de partager les liaisons. Des mécanismes complémentaires sont nécessaires pour gérer pertes, ordre et contrôle de congestion selon le protocole."},{"id":"cul-105","category":"tech","subtheme":"Réseaux","difficulty":3,"type":"qcm","question":"Quel service TCP fournit-il aux applications quand une connexion fonctionne ?","options":["Un flux d’octets fiable et ordonné","Des messages toujours indépendants et non ordonnés","Une garantie de délai maximal universel","Un chiffrement obligatoire de tout contenu"],"correct":0,"explanation":"TCP gère notamment les retransmissions et l’ordre des octets reçus. Il ne garantit pas un délai maximal ni le chiffrement ; TLS peut apporter la protection cryptographique au-dessus de TCP.","source":"https://www.rfc-editor.org/rfc/rfc9293.html"},{"id":"cul-106","category":"tech","subtheme":"Réseaux","difficulty":3,"type":"qcm","question":"Quelle propriété distingue UDP de TCP ?","options":["UDP ne fournit pas lui-même un mécanisme de livraison fiable et ordonnée","UDP interdit tout usage en temps réel","UDP chiffre automatiquement chaque paquet","UDP n’utilise jamais de ports"],"correct":0,"explanation":"UDP transmet des datagrammes sans établir le même service de flux fiable que TCP. Une application peut ajouter ses propres mécanismes ; c’est notamment possible pour des protocoles construits au-dessus d’UDP."},{"id":"cul-107","category":"tech","subtheme":"Réseaux","difficulty":3,"type":"qcm","question":"Que représente le TTL d’un enregistrement dans un cache DNS ?","options":["Sa durée de conservation avant qu’une actualisation soit nécessaire","La longueur maximale du nom en lettres","Le nombre de mots de passe du serveur","Le débit minimal de la connexion"],"correct":0,"explanation":"Le TTL indique combien de temps une réponse peut être conservée en cache. Un changement d’adresse DNS peut donc ne pas être visible immédiatement pour tous les utilisateurs."},{"id":"cul-108","category":"tech","subtheme":"Réseaux","difficulty":3,"type":"qcm","question":"Quel rôle joue une traduction d’adresses NAT courante dans une box IPv4 ?","options":["Faire partager une adresse publique à plusieurs équipements privés","Transformer les pages HTTP en images","Remplacer chaque adresse MAC par un mot de passe","Garantir à elle seule la sécurité de tous les logiciels"],"correct":0,"explanation":"La traduction modifie des informations d’adressage, souvent aussi les ports, pour gérer plusieurs flux. Ce mécanisme ne remplace pas les mises à jour, le filtrage ou l’authentification."},{"id":"cul-109","category":"tech","subtheme":"Réseaux","difficulty":4,"type":"qcm","question":"Combien de bits comporte une adresse IPv6 ?","options":["128","32","48","256"],"correct":0,"explanation":"IPv6 utilise des adresses de 128 bits, généralement représentées en hexadécimal avec des deux-points. Une notation abrégée peut masquer des groupes de zéros sans changer la taille de l’adresse.","source":"https://www.rfc-editor.org/info/rfc8200/"},{"id":"cul-110","category":"tech","subtheme":"Réseaux","difficulty":4,"type":"qcm","question":"Pour le sous-réseau IPv4 192.0.2.0/24, combien d’adresses le bloc contient-il au total ?","options":["256","24","254","512"],"correct":0,"explanation":"Un préfixe /24 laisse 8 bits variables sur les 32 bits d’IPv4 : 2 puissance 8 donne 256 adresses. Dans un sous-réseau classique, 254 sont généralement attribuables aux hôtes, mais la question porte sur le total."},{"id":"cul-111","category":"tech","subtheme":"Réseaux","difficulty":4,"type":"qcm","question":"Que peut signer DNSSEC pour permettre une validation ?","options":["Les données DNS, au moyen de signatures numériques","Le contenu complet de chaque page web consultée","Tous les messages envoyés par Wi-Fi","Les mots de passe de chaque internaute"],"correct":0,"explanation":"DNSSEC ajoute des mécanismes d’authentification de l’origine et d’intégrité des données DNS. Il ne chiffre pas les requêtes DNS et ne certifie pas le contenu des sites."},{"id":"cul-112","category":"tech","subtheme":"Réseaux","difficulty":4,"type":"qcm","question":"Un réseau contient deux routes possibles vers une adresse : /16 et /24, toutes deux valides. Quel principe IP guide habituellement le choix de la route la plus précise ?","options":["La correspondance au préfixe le plus long","Le choix systématique du préfixe le plus court","L’ordre alphabétique des noms de routeurs","La taille du navigateur de l’expéditeur"],"correct":0,"explanation":"La correspondance au préfixe le plus long privilégie ici /24, qui décrit un ensemble plus précis d’adresses. D’autres règles interviennent ensuite pour départager des routes de même spécificité."}];
const STORAGE_KEY='curiona.save.v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('fr-FR');
const fmt=n=>nf.format(n);
const paths={
  spark:'<path d="M12 2v20M2 12h20M5 5l14 14M19 5 5 19"/><circle cx="12" cy="12" r="3"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',
  leaf:'<path d="M20 3C6 2 2 8 5 15s15 4 15-12Z"/><path d="M3 22 17 7M9 16l-1-5m5 1 4 1"/>',
  butterfly:'<path d="M12 9C5-2-2 4 4 11c-7 8 2 13 8 3 6 10 15 5 8-3 6-7-1-13-8-2Z"/><path d="M12 8v10m-2-14 2 4 2-4"/>',
  shapes:'<path d="m4 2 5 8H0Zm11 11h8v8h-8Z"/><circle cx="5" cy="18" r="4"/><path d="M15 4h7m-3-3v6"/>',
  mind:'<path d="M8 18H5v-4H2l3-6a8 8 0 1 1 14 6v8H9v-4Z"/><path d="M9 6a2 2 0 0 0-1 4m4-6v10m0-6a3 3 0 0 1 5 2m-6 1a3 3 0 0 0 5 2"/>',
  planet:'<circle cx="12" cy="12" r="7"/><ellipse cx="12" cy="12" rx="12" ry="3" transform="rotate(-30 12 12)"/><path d="M20 2v3m-1.5-1.5h3"/>',
  globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6c4 3 10 3 14 0M5 18c4-3 10-3 14 0"/>',
  chip:'<rect x="5" y="5" width="14" height="14" rx="3"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/><path d="m10 9-2 3 2 3m4-6 2 3-2 3"/>',
  compass:'<circle cx="12" cy="12" r="9"/><path d="m16 7-2 7-7 3 3-7Z"/><path d="m10 10 4 4"/>',
  repeat:'<path d="M20 7H5l4-4M4 17h15l-4 4M4 7a8 8 0 0 0 0 7m16-7a8 8 0 0 1 0 7"/>',
  flag:'<path d="M5 22V3m0 1c5-5 9 5 15 0v11c-6 5-10-5-15 0"/>',
  cup:'<path d="M4 9h13v6a6 6 0 0 1-12 0V9Zm13 1h2a3 3 0 0 1 0 6h-2M2 22h19M8 2v3m5-3v3"/>',
  sliders:'<path d="M3 6h18M3 18h18M8 3v6m8 6v6"/>',
  check:'<path d="m5 12 4 4L19 6"/><circle cx="12" cy="12" r="10"/>',
  sound:'<path d="M3 9v6h4l5 4V5L7 9H3Zm13-1a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
  mute:'<path d="M3 9v6h4l5 4V5L7 9H3Zm13 0 6 6m0-6-6 6"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  lock:'<rect x="5" y="10" width="14" height="12" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 6v2"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  book:'<path d="M12 5C8 2 4 2 2 3v16c3-1 7-1 10 2 3-3 7-3 10-2V3c-2-1-6-1-10 2Zm0 0v16"/>',
  pause:'<path d="M8 5v14m8-14v14"/>'
};
function icon(name,extra=''){return `<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.spark}</svg>`;}
let storageIssue='',loadIssue='';
let state=freshState();
let session=null,view='home',result=null,setup={mode:'general',difficulty:'adaptive',count:12,themes:[]};
let timerHandle=null,lastTick=0,toastHandle=null,audioContext=null;
function restoreSession(raw){
  if(!raw||!MODES.some(m=>m.id===raw.config?.mode)||!['adaptive',1,2,3,4].includes(raw.config?.difficulty)||![8,12,20,50].includes(raw.config?.count)||!Array.isArray(raw.config?.themes))return null;
  if(!Array.isArray(raw.used)||!Array.isArray(raw.answers)||raw.used.length>50||raw.answers.length>50||new Set(raw.used).size!==raw.used.length||!raw.used.every(id=>QUESTIONS.some(q=>q.id===id)))return null;
  if(!raw.current||!raw.used.includes(raw.current.id))return null;
  const q=QUESTIONS.find(q=>q.id===raw.current.id);
  if(!q||!Array.isArray(raw.current.order)||raw.current.order.length!==q.options.length||new Set(raw.current.order).size!==q.options.length||!raw.current.order.every(i=>Number.isInteger(i)&&i>=0&&i<q.options.length))return null;
  if(!raw.answers.every(a=>raw.used.includes(a.id)&&typeof a.correct==='boolean')||new Set(raw.answers.map(a=>a.id)).size!==raw.answers.length)return null;
  if(!['score','xp','streak','limit','target','remaining'].every(k=>Number.isFinite(raw[k])&&raw[k]>=0&&raw[k]<=1e8)||raw.limit>50||raw.remaining>30||raw.limit<raw.used.length)return null;
  if(typeof raw.current.answered!=='boolean'||!Number.isInteger(raw.current.selected)||raw.current.selected< -1||raw.current.selected>=q.options.length)return null;
  if(raw.current.answered!==raw.answers.some(a=>a.id===q.id)||raw.used.length!==raw.answers.length+(raw.current.answered?0:1))return null;
  return {config:{mode:raw.config.mode,difficulty:raw.config.difficulty,count:raw.config.count,themes:raw.config.themes.filter(t=>typeof t==='string').slice(0,30)},used:[...raw.used],answers:raw.answers.map(a=>({id:a.id,correct:a.correct})),score:raw.score,xp:raw.xp,streak:raw.streak,limit:raw.limit,target:raw.target,remaining:raw.remaining,current:{id:q.id,order:[...raw.current.order],answered:raw.current.answered,selected:raw.current.selected,variant:raw.current.variant===true,reward:raw.current.answered?reward(q.difficulty,isCorrect(q,raw.current.selected),raw.streak):null}};
}
try{
  const saved=localStorage.getItem(STORAGE_KEY);
  if(saved){try{const raw=JSON.parse(saved);state=parseSave(raw,QUESTIONS);session=restoreSession(raw.state.active);state.active=session;}catch{loadIssue='La sauvegarde n’a pas pu être lue. Elle est conservée dans le navigateur ; exporte-la avant de repartir.';}}
}catch{storageIssue='Sauvegarde locale indisponible : exporte ton carnet pour le conserver.';}
function save(){
  state.active=session;
  if(loadIssue)return;
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify({app:'curiona',version:1,state}));storageIssue='';}
  catch{storageIssue='Sauvegarde locale indisponible : exporte ton carnet pour le conserver.';}
}
function notify(message){clearTimeout(toastHandle);$('#toast').textContent=message;$('#toast').classList.add('visible');toastHandle=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function playSound(correct){
  if(!state.sound)return;
  try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const t=audioContext.currentTime;[correct?523:330,correct?659:294].forEach((f,i)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=f;gain.gain.setValueAtTime(0,t+i*.11);gain.gain.linearRampToValueAtTime(.065,t+i*.11+.02);gain.gain.exponentialRampToValueAtTime(.001,t+i*.11+.2);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(t+i*.11);oscillator.stop(t+i*.11+.22);});}catch{/* Le jeu reste utilisable sans périphérique audio. */}
}
function levelData(){const level=playerLevel(state.xp),base=(level-1)**2*100,next=level**2*100;return{level,next,progress:100*(state.xp-base)/(next-base)};}
function dueCount(){return QUESTIONS.filter(q=>state.questions[q.id]?.nextDue<=Date.now()).length;}
function mastered(category){return QUESTIONS.filter(q=>(!category||q.category===category)&&(state.questions[q.id]?.box||0)>=2).length;}
function header(){const {level}=levelData();return `<header class="header"><button class="brand" data-action="home" aria-label="Curiona, accueil"><span class="brand-mark">${icon('spark')}</span><span><span class="brand-name">curiona<span style="color:var(--coral)">.</span></span><span class="brand-caption">La curiosité se cultive</span></span></button><nav class="nav" aria-label="Navigation principale"><button class="nav-button ${['home','game','result'].includes(view)?'active':''}" data-action="home">Explorer</button><button class="nav-button ${view==='stats'?'active':''}" data-action="stats">Mes progrès</button><button class="nav-button ${view==='help'?'active':''}" data-action="help">Le carnet de route</button></nav><div class="header-actions"><button class="sound" data-action="sound" aria-label="${state.sound?'Désactiver':'Activer'} les sons" aria-pressed="${state.sound}" title="${state.sound?'Désactiver':'Activer'} les sons">${icon(state.sound?'sound':'mute')}</button><div class="level-pill"><span>Niveau ${level}</span><div class="avatar" aria-label="Niveau ${level}">${icon('leaf')}</div></div></div></header>`;}
function footer(){return `<footer class="footer"><span>${icon('leaf')} Un peu de curiosité, chaque jour.</span><span>${icon('lock')} Ton carnet reste sur cet appareil · ${QUESTIONS.length} questions intégrées</span><div class="footer-actions"><button data-action="export">Exporter ma sauvegarde</button><button data-action="import">Importer</button></div></footer>`;}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 490 335" fill="none"><defs><pattern id="dots" width="17" height="17" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#d3d8c8"/></pattern><clipPath id="earth-clip"><circle cx="250" cy="162" r="88"/></clipPath></defs><ellipse cx="255" cy="165" rx="190" ry="147" fill="url(#dots)"/><circle cx="255" cy="162" r="119" stroke="#d1d7c6" stroke-dasharray="3 8"/><ellipse cx="252" cy="167" rx="174" ry="70" stroke="#c6cbb9" transform="rotate(-25 252 167)"/><circle cx="250" cy="162" r="88" fill="#d6e3d3" stroke="#567561" stroke-width="1.8"/><g clip-path="url(#earth-clip)" fill="#799b78" stroke="#567561" stroke-width="1.2"><path d="m177 93 29-12 19 12 4 16-18 13-5 21-18 9-17-18-11-4Zm49 67 19-8 24 11 5 25-18 13-1 22-17 20-12-17 1-26-11-19Z"/><path d="m283 88 16 12 36 4 17 18-13 14-23-4-11 13-16-2-5 20-16 2-19-20 8-15 18 1 7-16-11-12Z"/><path d="m300 193 20-9 25 10 11 28-35 9-17-11Z"/></g><g stroke="#69826b" opacity=".45"><ellipse cx="250" cy="162" rx="44" ry="88"/><path d="M162 162h176M177 115c43 23 100 23 146 0m-146 94c43-23 100-23 146 0"/></g><path d="M172 271q86 25 166-2" stroke="#9caa92"/><path d="M234 251v21m30-22v23" stroke="#647b64" stroke-width="3"/><path d="M212 275h78" stroke="#647b64" stroke-width="3" stroke-linecap="round"/><g stroke="#566e4b" stroke-width="2"><path d="M112 267q-16-61 13-110M113 242q-35-6-34-34 29 2 34 25M112 222q26-3 29-29-26 2-28 21M117 194q-18-10-15-30 21 9 17 24" fill="#aabd8e"/><path d="M376 265q18-56-5-93m4 69q30-9 26-31-24 4-26 23m4-20q-24-3-25-26 22 1 24 19" fill="#c0cca6"/></g><g transform="translate(79 82) rotate(-17)"><rect width="58" height="44" rx="4" fill="#f9f6e9" stroke="#ae9670" stroke-width="1.5"/><path d="M29 5v34M6 9l17 1m-17 7 17 1m-17 7 17 1m12-15 16-1m-16 9 16-1m-16 9 16-1" stroke="#b0ac8d"/></g><g transform="translate(368 81) rotate(15)"><circle r="27" fill="#f3dec7" stroke="#b17d56"/><path d="m11-12-6 17-17 7 6-17Z" fill="#bf6849" stroke="#9f5138"/><circle r="2" fill="#f9efdf"/></g><g stroke="#b17c4d" stroke-width="1.5"><path d="M306 36v14m-7-7h14M146 55v9m-4.5-4.5h9M416 213v12m-6-6h12"/><path d="m316 284 2 5 5 2-5 2-2 5-2-5-5-2 5-2Z" fill="#d3aa6e"/></g><g transform="translate(131 282) rotate(-13)"><rect width="56" height="7" rx="2" fill="#c76c4c"/><path d="m56 0 11 3.5L56 7Z" fill="#d8bc88"/><path d="m64 2 3 1.5L64 5Z" fill="#324a3c"/></g><circle cx="400" cy="151" r="4" fill="#c97750"/><circle cx="154" cy="245" r="3" fill="#be855e"/></svg><div class="art-label top">${icon('spark')} Chaque erreur est un déclic.</div><div class="art-label bottom">${icon('compass')} Suis ta curiosité.</div></div>`;}
function home(){const ld=levelData(),due=dueCount();return `${session?`<div class="resume-banner"><span><strong>Une exploration t’attend.</strong> ${session.answers.length} réponse(s) sur ${session.limit} · ${MODES.find(m=>m.id===session.config.mode).label}</span><button class="primary" data-action="resume">Reprendre ${icon('arrow')}</button></div>`:''}<section class="hero"><div class="hero-copy"><div class="eyebrow">Bienvenue, esprit curieux</div><h1>Le monde est plein de<br><em>petites découvertes.</em></h1><p class="hero-description">Une question, un déclic, un peu de savoir en plus.<br>Explore, essaie et laisse ta curiosité faire le reste.</p><div class="hero-actions"><button class="primary" data-action="setup" data-mode="general">Partir explorer ${icon('arrow')}</button><button class="text-button" data-action="setup" data-mode="relax">Prendre mon temps ${icon('cup')}</button></div></div>${heroArt()}</section><div class="quick-strip"><span><strong>7</strong> univers à explorer</span><span class="dot"></span><span><strong>${QUESTIONS.length}</strong> questions pour comprendre</span><span class="dot"></span><span><strong>6</strong> façons de jouer</span><span class="last">${icon('leaf')} Sans compte · 100 % hors ligne</span></div><div class="explore-layout"><section aria-labelledby="worlds-title"><div class="section-heading"><div><h2 id="worlds-title">Où t’emmène ta curiosité ?</h2><p>Choisis un univers. Ou laisse-toi surprendre.</p></div></div><div class="world-grid">${CATEGORIES.map(c=>{const count=QUESTIONS.filter(q=>q.category===c.id).length,done=mastered(c.id);return `<button class="world-card" data-action="category" data-category="${c.id}"><span class="world-art" style="background:${c.bg};color:${c.color}">${icon(c.icon)}</span>${icon('arrow','arrow')}<h3>${c.name}</h3><small>${count} questions · 3 sous-thèmes</small><div class="mini-progress" aria-label="${done} notions consolidées sur ${count}"><span style="width:${done/count*100}%"></span></div></button>`;}).join('')}<button class="world-card surprise" data-action="setup" data-mode="general"><span class="world-art">${icon('compass')}</span><h3>Un peu de tout ?</h3><p>Traverse les univers dans un grand mélange de découvertes.</p>${icon('arrow','arrow')}</button></div></section><aside><div class="notebook"><div class="eyebrow">Ton carnet d’explorateur</div><div class="notebook-level"><div class="level-line">${icon('leaf')}<span class="level-number">${ld.level}</span><div><h3>${ld.level<3?'Jeune pousse':ld.level<7?'Esprit curieux':'Grand explorateur'}</h3><small>Niveau d’exploration</small></div></div><div class="xp-progress" role="progressbar" aria-label="Expérience vers le prochain niveau" aria-valuenow="${Math.round(ld.progress)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${ld.progress}%"></span></div><small>${fmt(state.xp)} / ${fmt(ld.next)} XP · prochain niveau</small></div><hr><div class="notebook-review"><div class="review-info">${icon('repeat')}<div><h3>${due?`${due} notion${due>1?'s':''} à retrouver`:'Tout commence ici'}</h3><small>${due?'Un petit rappel fait du bien.':'Tes découvertes prennent racine.'}</small></div></div><button class="secondary" data-action="setup" data-mode="review">${due?'Faire une révision':'Découvrir la révision'} ${icon('arrow')}</button></div></div><div class="did-you-know"><div class="eyebrow">Le petit déclic</div><p>Essayer de retrouver une réponse en mémoire aide à la retenir. Même une erreur peut devenir un bon point de départ, avec une explication.</p></div></aside></div><section class="modes-section"><div class="section-heading"><div><h2>À chaque envie, son exploration.</h2><p>Un défi aujourd’hui, une balade demain.</p></div><span class="pill">À ton rythme</span></div><div class="mode-grid">${MODES.map(m=>`<button class="mode-card" data-action="setup" data-mode="${m.id}">${icon(m.icon)}<div><h3>${m.name} <span class="sr-only">(${m.label})</span></h3><p>${m.description}</p></div></button>`).join('')}</div></section>`;}
function stats(){const explored=Object.keys(state.questions).length;return `<div class="view"><div class="view-header"><div class="eyebrow" style="color:var(--coral)">Chaque découverte compte</div><h1>Ton savoir prend racine.</h1><p>Voici le chemin parcouru. Les erreurs font aussi partie du voyage.</p></div><div class="stats-grid"><div class="stat"><small>Expérience acquise</small><strong>${fmt(state.xp)}</strong><small>Niveau ${playerLevel(state.xp)} · ${fmt(state.points)} points</small></div><div class="stat"><small>Précision globale</small><strong>${state.total?Math.round(state.correct/state.total*100):0}<span style="font-size:20px"> %</span></strong><small>${fmt(state.correct)} réussites / ${fmt(state.total)} réponses</small></div><div class="stat"><small>Notions rencontrées</small><strong>${explored}<span style="font-size:18px"> / ${QUESTIONS.length}</span></strong><small>${mastered()} consolidées · deux rappels réussis</small></div><div class="stat"><small>Meilleure série</small><strong>${state.bestStreak}</strong><small>Bonnes réponses consécutives</small></div></div><section><div class="section-heading"><h2>Un univers après l’autre</h2><span class="sub-label">Consolidation des notions</span></div><div class="progress-grid">${CATEGORIES.map(c=>{const qs=QUESTIONS.filter(q=>q.category===c.id),seen=qs.filter(q=>state.questions[q.id]).length,master=mastered(c.id),t=state.topics[c.id];return `<article class="progress-card"><header style="color:${c.color}">${icon(c.icon)}<div><h3>${c.name}</h3><small>${seen} découvertes · ${master} notions consolidées sur ${qs.length}</small></div></header><div class="mini-progress"><span style="width:${master/qs.length*100}%;background:${c.color}"></span></div><div class="progress-meta"><span>Adaptatif : ${DIFFICULTIES[t?.level||1]}</span><span>${t?.total?Math.round(t.correct/t.total*100)+' % de précision':'À explorer'}</span></div></article>`;}).join('')}</div></section><section class="section-block"><h2>Les petits accomplissements</h2><div class="badge-grid">${BADGES.map(b=>`<article class="badge ${state.badges.includes(b.id)?'unlocked':''}">${icon(b.icon)}<h3>${b.name}${state.badges.includes(b.id)?' ✓':''}</h3><p>${b.description}</p><span class="sr-only">${state.badges.includes(b.id)?'Débloqué':'À débloquer'}</span></article>`).join('')}</div></section><section class="section-block"><h2>Les pages précédentes</h2><div class="history-list">${state.history.length?state.history.map(h=>`<details class="history-item"><summary><span><strong>${MODES.find(m=>m.id===h.mode).name}</strong><br><small>${new Date(h.date).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'})}${h.abandoned?' · interrompue':''}</small></span><span>${fmt(h.score)} points · ${h.correct}/${h.total}<br><small>+ ${h.xp} XP${h.mode==='challenge'?` · cap ${h.target} ${h.score>=h.target&&!h.abandoned?'atteint':'non atteint'}`:''}</small></span></summary><p>${h.answers.some(a=>!a.correct)?'À revoir :':'Toutes les réponses sont correctes. Bravo !'}</p><ul>${h.answers.filter(a=>!a.correct).map(a=>{const q=QUESTIONS.find(q=>q.id===a.id);return `<li>${esc(q.question)}<br><strong>${esc(q.options[q.correct])}.</strong> ${esc(q.explanation)}</li>`;}).join('')}</ul></details>`).join(''):'<p class="empty">Ta première exploration écrira la première page.</p>'}</div><p class="save-note">Les 100 dernières parties sont conservées. Tes statistiques cumulées restent disponibles.</p></section><section class="section-block"><h2>Ton carnet, à emporter</h2><p class="muted" style="font-size:13px">La progression se sauvegarde après chaque réponse, dans ce navigateur. Exporte-la pour la déplacer ou la garder à l’abri.</p><div class="save-actions"><button class="primary" data-action="export">${icon('download')} Exporter ma sauvegarde</button><button class="secondary" data-action="import">Importer une sauvegarde</button></div><p class="save-note">Un import remplace le carnet actuel après confirmation. Il ne reprend pas la partie en cours du fichier.</p></section></div>`;}
function help(){return `<div class="view"><div class="view-header"><div class="eyebrow" style="color:var(--coral)">Le carnet de route</div><h1>Apprendre, simplement.</h1><p>Pas de vie perdue, pas de pression. Chaque explication est une découverte.</p></div><div class="help-grid"><section class="help-card"><h2>Un petit tour de jeu</h2><p>Choisis un mode, un niveau et une longueur de partie. Chaque QCM a une seule bonne réponse. Les questions « Vrai ou faux » ont deux choix. Lis la correction puis avance quand tu le souhaites.</p><p>Au clavier : <strong>1 à 4</strong> (ou <strong>A à D</strong>) pour répondre, <strong>Entrée</strong> pour continuer après correction, <strong>Échap</strong> pour mettre de côté une exploration. Tabulation permet de parcourir toutes les commandes.</p></section><section class="help-card"><h2>Six chemins possibles</h2><ul>${MODES.map(m=>`<li><strong>${m.label}</strong> — ${m.description}</li>`).join('')}</ul><p>Le Défi vise 100 points par question prévue au total. Son chrono s’arrête pendant les explications, hors de l’onglet et lorsque tu retournes à l’accueil. Aucun autre mode n’a de chrono.</p></section><section class="help-card"><h2>Les points, sans course</h2><p>Une bonne réponse vaut <strong>100, 125, 150 ou 175 points</strong> selon la difficulté. Une série ajoute 10 points par réponse supplémentaire, jusqu’à 50 de bonus. La vitesse ne rapporte rien de plus.</p><p>Une réussite donne de 30 à 45 XP, une erreur 8 XP pour l’apprentissage. Le niveau du joueur dépend de l’expérience : 100 XP pour le niveau 2, 400 pour le niveau 3, 900 pour le niveau 4.</p></section><section class="help-card"><h2>Un rythme qui s’adapte</h2><p>En adaptatif, chaque univers commence au niveau débutant. Trois réussites consécutives dans cet univers font monter d’un cran ; deux erreurs consécutives font redescendre d’un cran. Le tirage privilégie ce niveau, avec quelques variations.</p><p>Les questions jamais vues sont favorisées. Une question ne revient jamais deux fois dans la même partie. Si un filtre contient moins de questions que prévu, la partie se raccourcit et l’indique avant le départ.</p></section><section class="help-card"><h2>Les rappels qui font du bien</h2><p>Après une erreur, la notion revient en Révision au bout de <strong>10 minutes</strong>. Après une réussite, les rappels s’espacent : 1, 3, 7, 14 puis 30 jours. Deux réussites successives consolident la notion. Une erreur réinitialise cet intervalle.</p><p>La révision ne propose que les rappels arrivés à échéance. Chaque notion n’y apparaît qu’une fois par partie. Elle peut revenir avec la même formulation ; l’objectif est d’en retrouver le raisonnement.</p></section><section class="help-card"><h2>Un carnet sur cet appareil</h2><p>Le jeu et ses ${QUESTIONS.length} questions sont intégrés aux fichiers : aucune IA, publicité ou inscription. Le son est facultatif. Tout fonctionne hors ligne dès que tu possèdes le dossier.</p><p>Utilise toujours le même raccourci et le même profil Chrome pour retrouver ton carnet. La navigation privée, l’effacement des données ou un déplacement du jeu peuvent changer l’accès à la sauvegarde. L’export JSON permet de la transférer.</p></section><section class="help-card wide"><h2>Comprendre plutôt que piéger</h2><p>Les sept univers proposent chacun 48 questions, réparties entre quatre difficultés. Les explications en psychologie décrivent des résultats et des limites, jamais des diagnostics. Certains effets dépendent du contexte et ne prédisent pas le comportement d’une personne.</p><p>Des sources primaires ou institutionnelles sont liées à certaines corrections. Les notes éditoriales se trouvent dans le dossier <strong>docs</strong> du projet. Cette banque est rédigée avec soin et vérifiée par échantillons ; elle ne constitue pas un programme scolaire exhaustif.</p></section></div></div>`;}
function stopTimer(){if(timerHandle)clearInterval(timerHandle);timerHandle=null;}
function startTimer(){
  stopTimer();if(!session||session.config.mode!=='challenge'||session.current.answered||view!=='game')return;
  lastTick=performance.now();let savedAt=lastTick;
  timerHandle=setInterval(()=>{const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;if(document.hidden)return;session.remaining=Math.max(0,session.remaining-delta);const timer=$('#timer-value');if(timer){timer.textContent=Math.ceil(session.remaining)+' s';timer.closest('.timer').classList.toggle('urgent',session.remaining<8);}if(now-savedAt>5000){save();savedAt=now;}if(session.remaining<=0)answer(-1);},150);
}
function currentQuestion(){return QUESTIONS.find(q=>q.id===session?.current.id);}
function game(){const q=currentQuestion(),c=CATEGORIES.find(c=>c.id===q.category),answered=session.current.answered,correct=answered&&isCorrect(q,session.current.selected),progress=session.answers.length/session.limit*100;return `<div class="game-wrap"><div class="game-toolbar"><button class="text-button" data-action="pause">${icon('pause')} Mettre de côté</button><div class="game-status"><span><strong>${session.used.length}</strong> / ${session.limit}</span><span><strong>${fmt(session.score)}</strong> pts</span>${session.streak>1?`<span>${session.streak} de suite ✦</span>`:''}${session.config.mode==='challenge'?`<span class="timer">${icon('clock')} <span id="timer-value">${answered?'En pause':Math.ceil(session.remaining)+' s'}</span></span>`:''}</div></div><div class="game-progress" role="progressbar" aria-label="Progression dans la partie" aria-valuenow="${session.answers.length}" aria-valuemin="0" aria-valuemax="${session.limit}"><span style="width:${progress}%"></span></div><article class="question-card"><div class="question-top"><div class="question-tags"><span class="pill" style="color:${c.color};background:${c.bg}">${icon(c.icon)} ${c.name}</span><span class="pill">${esc(q.subtheme)}</span></div><span class="tag muted">${DIFFICULTIES[q.difficulty]}</span></div><h1 id="question-title" tabindex="-1">${esc(session.current.variant&&q.variant?q.variant:q.question)}</h1><p class="question-note">${q.options.length===2?'Vrai ou faux ?':'Une seule bonne réponse.'} ${session.config.mode==='challenge'?`Objectif : ${fmt(session.target)} points.`:'Prends le temps de réfléchir.'}</p><div class="answers">${session.current.order.map((id,index)=>{const isRight=answered&&id===q.correct,isWrong=answered&&id===session.current.selected&&!correct;return `<button class="answer ${isRight?'correct':isWrong?'wrong':''}" data-answer="${id}" ${answered?'disabled':''}><span class="answer-key">${String.fromCharCode(65+index)}</span><span>${esc(q.options[id])}${isRight?'<span class="answer-status">✓ Bonne réponse</span>':isWrong?'<span class="answer-status">× Ta réponse</span>':''}</span></button>`;}).join('')}</div></article>${answered?`<section class="correction ${correct?'':'incorrect'}" aria-labelledby="correction-title"><div id="correction-title" class="correction-title" tabindex="-1">${icon(correct?'check':'book')} ${correct?'Bien vu ! Une découverte de plus.':session.current.selected===-1?'Le temps est écoulé. Prenons le temps de comprendre.':'Pas tout à fait. Voici le déclic.'}</div><p><strong>La bonne réponse : ${esc(q.options[q.correct])}.</strong></p><p class="explain">${esc(q.explanation)}</p>${q.tip?`<p class="tip"><strong>Pour retenir.</strong> ${esc(q.tip)}</p>`:''}<div class="correction-footer"><span class="reward-label">+ ${session.current.reward.xp} XP${correct?` · + ${session.current.reward.points} points`:' · chaque essai fait avancer'}</span>${q.source?`<a class="source" href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">Consulter la source ↗</a>`:''}</div></section><div class="game-next"><small>La correction reste aussi longtemps que tu veux.<span class="desktop-key"> <span class="keycap">Entrée</span> pour continuer.</span></small><button class="primary" data-action="next">${session.answers.length>=session.limit?'Voir mon bilan':'La prochaine découverte'} ${icon('arrow')}</button></div>`:`<div class="game-next"><small>Clavier : <span class="keycap">1</span> à <span class="keycap">${q.options.length}</span>, ou A à ${String.fromCharCode(64+q.options.length)}.</small><small>${session.config.mode==='challenge'?'Le chrono s’arrête pendant les corrections.':'Ici, la vitesse ne compte pas.'}</small></div>`}</div>`;}
function results(){const wrong=result.answers.filter(a=>!a.correct),groups=CATEGORIES.map(c=>({c,total:result.answers.filter(a=>QUESTIONS.find(q=>q.id===a.id).category===c.id).length,correct:result.answers.filter(a=>a.correct&&QUESTIONS.find(q=>q.id===a.id).category===c.id).length})).filter(g=>g.total>0),strong=[...groups].sort((a,b)=>b.correct/b.total-a.correct/a.total).filter(g=>g.correct>0).slice(0,3);return `<div class="view"><div class="result-head">${icon(result.mode==='challenge'&&result.score>=result.target?'flag':'leaf')}<div class="eyebrow" style="color:var(--coral);margin-bottom:16px">Une page de plus dans ton carnet</div><h1>${result.mode==='challenge'?(result.score>=result.target?'Cap atteint, belle exploration !':'Un défi, de nouveaux repères.'):wrong.length===0?'Une belle récolte de déclics !':'Ta curiosité a fait du chemin.'}</h1><p>${wrong.length?'Ce que tu as découvert compte autant que le score. Les notions à revoir reviendront au bon moment.':'Prends un instant pour savourer. Les rappels t’aideront à garder ces notions en mémoire.'}${result.mode==='challenge'?`<br>Objectif : ${fmt(result.target)} points · ${fmt(result.score)} points obtenus.`:''}</p></div><div class="stats-grid"><div class="stat"><small>Points gagnés</small><strong>${fmt(result.score)}</strong><small>Sans bonus de vitesse</small></div><div class="stat"><small>Précision</small><strong>${Math.round(result.correct/result.total*100)} %</strong><small>${result.correct} / ${result.total} réponses</small></div><div class="stat"><small>Expérience</small><strong>+ ${result.xp}</strong><small>Niveau ${playerLevel(state.xp)}</small></div><div class="stat"><small>À consolider</small><strong>${wrong.length}</strong><small>${wrong.length?'Rappel dans 10 minutes':'De belles racines'}</small></div></div><div class="result-actions"><button class="primary" data-action="replay">Une nouvelle exploration ${icon('arrow')}</button><button class="secondary" data-action="home">Retour aux univers</button></div><div class="result-concepts"><section><h2>Tes points forts</h2>${strong.length?strong.map(g=>`<p><strong>${g.c.name}</strong> · ${g.correct} / ${g.total} réussites</p>`).join(''):'<p>Tu as rencontré de nouvelles notions. Leur compréhension se construit aussi en lisant les explications et en réessayant.</p>'}<p style="margin-top:16px">Une partie donne un aperçu, pas une mesure définitive de tes connaissances.</p></section><section><h2>Les prochains déclics</h2>${wrong.length?wrong.map(a=>{const q=QUESTIONS.find(q=>q.id===a.id);return `<details class="result-answer"><summary>${esc(q.question)}</summary><p><strong>${esc(q.options[q.correct])}.</strong> ${esc(q.explanation)}</p></details>`;}).join(''):'<p>Tout est juste aujourd’hui. Les rappels reviendront à partir de demain, pour laisser le temps à la mémoire de travailler.</p>'}</section></div></div>`;}
function render(focus=false){stopTimer();$('#app').innerHTML=`<div class="shell">${header()}<main id="main">${loadIssue?`<div class="warning">${esc(loadIssue)} <button class="text-button" data-action="recover">Repartir avec un nouveau carnet</button></div>`:storageIssue?`<div class="warning" role="alert">${esc(storageIssue)}</div>`:''}${view==='home'?home():view==='stats'?stats():view==='help'?help():view==='game'?game():results()}</main>${footer()}</div>`;if(focus){window.scrollTo({top:0,behavior:'instant'});const title=view==='game'?$('#question-title'):$('main h1');if(title){title.setAttribute('tabindex','-1');title.focus({preventScroll:true});}}if(view==='game')startTimer();}
function navigate(destination){save();view=destination;render(true);}
function setupAvailability(){return filterQuestions(QUESTIONS,setup,state).length;}
function setupDialog(){const m=MODES.find(m=>m.id===setup.mode),c=CATEGORIES.find(c=>c.id===setup.themes[0]?.split('::')[0])||CATEGORIES[0],sub=setup.themes[0]?.split('::')[1]||'',available=setupAvailability(),count=Math.min(setup.count,available);const dlg=$('#setup-dialog');dlg.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow" style="color:var(--coral)">Ton prochain départ</span><h2 id="setup-title">${m.name}</h2><p>${m.description}</p></div><button class="close" data-action="close-setup" aria-label="Fermer les réglages">${icon('close')}</button></div><div class="setup-modes" role="group" aria-label="Mode de jeu">${MODES.map(mode=>`<button class="setup-mode ${mode.id===setup.mode?'selected':''}" aria-pressed="${mode.id===setup.mode}" data-action="switch-mode" data-mode="${mode.id}">${icon(mode.icon)} ${mode.label}</button>`).join('')}</div><div class="form-row"><div class="form-field"><label for="difficulty">Difficulté</label><select id="difficulty"><option value="adaptive" ${setup.difficulty==='adaptive'?'selected':''}>Progression adaptative</option>${DIFFICULTIES.slice(1).map((d,i)=>`<option value="${i+1}" ${setup.difficulty===i+1?'selected':''}>${d}</option>`).join('')}</select></div><div class="form-field"><label for="question-count">Longueur de l’exploration</label><select id="question-count">${[8,12,20,50].map(n=>`<option value="${n}" ${setup.count===n?'selected':''}>${n} questions${n===8?' · petite balade':n===12?' · le juste milieu':n===50?' · grand voyage':''}</option>`).join('')}</select></div></div>${setup.mode==='specific'?`<div class="form-row"><div class="form-field"><label for="category-select">Univers</label><select id="category-select">${CATEGORIES.map(cat=>`<option value="${cat.id}" ${cat.id===c.id?'selected':''}>${cat.name}</option>`).join('')}</select></div><div class="form-field"><label for="subtheme-select">Sous-thème</label><select id="subtheme-select"><option value="">Tout l’univers</option>${c.subs.map(s=>`<option value="${esc(s)}" ${s===sub?'selected':''}>${s}</option>`).join('')}</select></div></div>`:''}${setup.mode==='custom'?`<fieldset class="custom-themes"><legend>Les thèmes de ton mélange</legend><div class="theme-choices">${CATEGORIES.map(cat=>{const all=setup.themes.includes(cat.id);return `<div><label class="theme-check"><input type="checkbox" data-theme="${cat.id}" ${all?'checked':''}>${cat.name}</label><details class="theme-detail" ${setup.themes.some(t=>t.startsWith(cat.id+'::'))?'open':''}><summary>Choisir les sous-thèmes</summary><div class="theme-sub">${cat.subs.map(s=>`<label class="theme-check"><input type="checkbox" data-theme="${cat.id}::${esc(s)}" ${all||setup.themes.includes(cat.id+'::'+s)?'checked':''} ${all?'disabled':''}>${s}</label>`).join('')}</div></details></div>`;}).join('')}</div></fieldset>`:''}<p class="form-hint">${setup.mode==='review'?'Seules les notions dont le rappel est arrivé sont proposées. Après une erreur : 10 minutes ; après une réussite : de 1 à 30 jours.':setup.difficulty==='adaptive'?'Le jeu s’adapte séparément dans chaque univers. Trois réussites de suite font progresser ; deux erreurs font ralentir.':'Le filtre de difficulté est strict : seules les questions de ce niveau seront proposées.'} ${setup.mode==='challenge'?`<strong>30 secondes par question · objectif ${count*100} points.</strong>`:'Aucun chronomètre.'}</p><div class="setup-bottom"><small id="availability">${available?`<strong>${available} questions disponibles.</strong> ${count} dans cette partie, sans doublon.${count<setup.count?' Le filtre est plus court : la partie s’arrêtera après ces '+count+' questions.':''}`:setup.mode==='review'?`<strong>Aucun rappel disponible à ce niveau.</strong> ${Object.keys(state.questions).length?'Reviens après le prochain délai, ou choisis une autre difficulté.':'Commence par explorer : tes rappels apparaîtront ici.'}`:'<strong>Aucune question sélectionnée.</strong> Choisis au moins un thème.'}</small><button class="primary" data-action="start" ${available?'':'disabled'}>C’est parti ${icon('arrow')}</button></div>`;}
function openSetup(mode='general',category){setup={...setup,mode,themes:category?[category]:(mode==='specific'?[setup.themes[0]||'animals']:mode==='custom'?(setup.themes.length?setup.themes:CATEGORIES.map(c=>c.id)):[])};setupDialog();$('#setup-dialog').showModal();}
function askConfirmation(title,body,label,onConfirm){const dlg=$('#confirm-dialog');dlg.innerHTML=`<h2 id="confirm-title">${esc(title)}</h2><p>${esc(body)}</p><div class="confirm-actions"><button class="secondary" id="cancel-confirm">Annuler</button><button class="primary" id="accept-confirm">${esc(label)}</button></div>`;$('#cancel-confirm').onclick=()=>dlg.close();$('#accept-confirm').onclick=()=>{dlg.close();onConfirm();};dlg.showModal();}
function addBadges(){const ids=earnedBadges(state);state.badges.push(...ids);if(ids.length)notify('Réussite débloquée : '+ids.map(id=>BADGES.find(b=>b.id===id).name).join(', '));}
function historyRecord(abandoned=false){return{mode:session.config.mode,score:session.score,correct:session.answers.filter(a=>a.correct).length,total:session.answers.length,xp:session.xp,date:Date.now(),target:session.target,abandoned,answers:[...session.answers]};}
function startSession(){
  if(session){askConfirmation('Ouvrir une nouvelle page ?','Ta progression est déjà sauvegardée. L’exploration en cours sera classée comme interrompue dans l’historique.','Commencer',()=>{if(session.answers.length)state.history.unshift(historyRecord(true));state.history=state.history.slice(0,100);session=null;startSession();});return;}
  const available=setupAvailability();if(!available)return;const limit=Math.min(setup.count,available);
  session={config:structuredClone(setup),used:[],answers:[],score:0,xp:0,streak:0,limit,target:setup.mode==='challenge'?limit*100:0,remaining:30,current:null};
  $('#setup-dialog').close();nextQuestion();
}
function nextQuestion(){
  if(session.answers.length>=session.limit){finishSession();return;}
  const q=pickQuestion(QUESTIONS,state,session.config,session.used);
  if(!q){finishSession();return;}
  session.used.push(q.id);session.current={id:q.id,order:shuffledOptions(q).map(o=>o.id),answered:false,selected:-1,variant:!!(q.variant&&state.questions[q.id]?.seen%2===1),reward:null};session.remaining=30;view='game';save();render(true);
}
function answer(id){if(!session||view!=='game'||session.current.answered)return;stopTimer();const q=currentQuestion(),correct=isCorrect(q,id);session.streak=correct?session.streak+1:0;const r=recordAnswer(state,q,correct,session.streak,session.config.mode);session.score+=r.points;session.xp+=r.xp;session.answers.push({id:q.id,correct});session.current.answered=true;session.current.selected=id;session.current.reward=r;addBadges();save();playSound(correct);render();$('#correction-title')?.focus({preventScroll:true});$('.correction')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}
function finishSession(){stopTimer();if(!session?.answers.length){session=null;view='home';save();render();return;}result=historyRecord();state.history.unshift(result);state.history=state.history.slice(0,100);session=null;addBadges();save();view='result';render(true);}
function download(data,name){const blob=new Blob([data],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportSave(){save();if(loadIssue){download(localStorage.getItem(STORAGE_KEY)||'{}','curiona-sauvegarde-a-recuperer.json');notify('Sauvegarde brute exportée pour récupération.');return;}download(JSON.stringify({app:'curiona',version:1,exportedAt:new Date().toISOString(),state},null,2),`curiona-carnet-${new Date().toLocaleDateString('en-CA')}.json`);notify('Ton carnet a été exporté.');}
document.addEventListener('click',event=>{
  const option=event.target.closest('[data-answer]');if(option){answer(Number(option.dataset.answer));return;}
  const el=event.target.closest('[data-action]');if(!el)return;
  switch(el.dataset.action){
    case 'home':navigate('home');break;case 'stats':navigate('stats');break;case 'help':navigate('help');break;
    case 'sound':state.sound=!state.sound;save();render();if(state.sound)playSound(true);notify(state.sound?'Sons activés':'Sons désactivés');break;
    case 'setup':openSetup(el.dataset.mode);break;case 'category':openSetup('specific',el.dataset.category);break;
    case 'close-setup':$('#setup-dialog').close();break;
    case 'switch-mode':setup.mode=el.dataset.mode;if(setup.mode==='specific')setup.themes=[setup.themes[0]||'animals'];else if(setup.mode==='custom'&&!setup.themes.length)setup.themes=CATEGORIES.map(c=>c.id);setupDialog();break;
    case 'start':startSession();break;case 'next':if(session?.current.answered)nextQuestion();break;
    case 'pause':navigate('home');notify('Exploration sauvegardée. Reprends quand tu veux.');break;
    case 'resume':view='game';render(true);break;
    case 'replay':openSetup(result?.mode||'general');break;
    case 'export':exportSave();break;case 'import':$('#import-file').click();break;
    case 'recover':askConfirmation('Repartir avec un nouveau carnet ?','Exporte d’abord la sauvegarde illisible si tu souhaites la garder. Cette action remplace uniquement la sauvegarde de Curiona.','Nouveau carnet',()=>{state=freshState();session=null;loadIssue='';save();view='home';render();});break;
  }
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='difficulty'){setup.difficulty=el.value==='adaptive'?'adaptive':Number(el.value);setupDialog();$('#difficulty').focus();}
  else if(el.id==='question-count'){setup.count=Number(el.value);setupDialog();$('#question-count').focus();}
  else if(el.id==='category-select'){setup.themes=[el.value];setupDialog();$('#category-select').focus();}
  else if(el.id==='subtheme-select'){const cat=$('#category-select').value;setup.themes=[el.value?cat+'::'+el.value:cat];setupDialog();$('#subtheme-select').focus();}
  else if(el.dataset.theme){const id=el.dataset.theme;setup.themes=setup.themes.filter(t=>t!==id&&(!el.checked||!t.startsWith(id+'::')));if(el.checked)setup.themes.push(id);setupDialog();Array.from(document.querySelectorAll('[data-theme]')).find(e=>e.dataset.theme===id)?.focus();}
});
$('#import-file').addEventListener('change',async event=>{
  const file=event.target.files[0];event.target.value='';if(!file)return;
  if(file.size>5*1024*1024){notify('Ce fichier est trop volumineux (maximum 5 Mo).');return;}
  try{const imported=parseSave(JSON.parse(await file.text()),QUESTIONS);askConfirmation('Retrouver ce carnet ?',`Ce fichier contient ${imported.total} réponses, ${imported.xp} XP et ${imported.history.length} parties. Il remplacera le carnet actuel. Exporte ton carnet actuel pour le conserver.`,'Importer ce carnet',()=>{stopTimer();state=imported;session=null;loadIssue='';save();view='stats';render(true);notify('Ton carnet a été restauré.');});}catch(error){notify(error instanceof SyntaxError?'Ce fichier JSON est illisible.':error.message);}
});
document.addEventListener('keydown',event=>{
  if(event.ctrlKey||event.altKey||event.metaKey)return;
  if($('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;
  if(view!=='game'||!session)return;
  if(event.key==='Escape'){event.preventDefault();navigate('home');return;}
  if(event.key==='Enter'&&session.current.answered&&!event.target.closest('button,a')){event.preventDefault();nextQuestion();return;}
  if(session.current.answered)return;const numeric=Number(event.key);let index=/^[1-4]$/.test(event.key)?numeric-1:['a','b','c','d'].indexOf(event.key.toLowerCase());
  if(index<0&&/^Digit[1-4]$/.test(event.code))index=Number(event.code.at(-1))-1;
  if(index>=0&&index<session.current.order.length){event.preventDefault();answer(session.current.order[index]);}
});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();save();});
window.addEventListener('pagehide',save);
// Interface de diagnostic en lecture seule pour les vérifications locales.
window.Curiona={info:()=>({questions:QUESTIONS.length,categories:CATEGORIES.map(c=>({id:c.id,count:QUESTIONS.filter(q=>q.category===c.id).length}))}),snapshot:()=>structuredClone({view,state,session,result}),bank:()=>structuredClone(QUESTIONS)};
render();

})();
